INSERT INTO ref.conflict (conflict_id, subject, status, readings, why_it_matters, next_action, resolution, blocking_for, source_ids) VALUES ('conflict.fl.5000_threshold', 'Florida $5,000 disabled-veteran property deduction threshold', 'contested_unresolved', '[{"source": "src.mod.sentinel", "value": "any service-connected rating"}, {"source": "src.rr.transition_finances", "value": "10% or more"}]'::jsonb, NULL, 'Read Fla. Stat. 196.24.', NULL, '{}'::text[], ARRAY['src.mod.sentinel','src.rr.transition_finances']::text[]);
INSERT INTO ref.conflict (conflict_id, subject, status, readings, why_it_matters, next_action, resolution, blocking_for, source_ids) VALUES ('conflict.fl.recreation_thresholds', 'Florida free hunting, fishing and park access rating thresholds', 'contested_unresolved', '[{"source": "src.mod.sentinel", "value": "50%+ rating: free hunting and fishing"}, {"source": "src.mod.sentinel", "value": "100% rating: free five-year hunting and fishing license (other sources give different thresholds)"}]'::jsonb, NULL, 'Read FWC and DEP rules directly.', NULL, '{}'::text[], ARRAY['src.mod.sentinel']::text[]);
INSERT INTO ref.conflict (conflict_id, subject, status, readings, why_it_matters, next_action, resolution, blocking_for, source_ids) VALUES ('conflict.state_tax.full_exempt_count', 'How many jurisdictions fully exempt military retirement (TY2025)', 'contested_unresolved', '[{"source": "src.rr.transition_finances", "value": "38 of 51 including the 9 with no income tax"}, {"source": "src.rr.transition_finances", "value": "approximately 28 income-tax states"}, {"source": "src.rr.transition_finances", "value": "30 states named in the report''s own full-exemption list"}]'::jsonb, 'The report is internally inconsistent; the per-state summary is carried, the headline count is not.', NULL, NULL, '{}'::text[], ARRAY['src.rr.transition_finances']::text[]);
