INSERT INTO ref.directory_entry (entry_id, kind, jurisdiction_code, name, place, org_type, program, care_types, phone, phone_e164, text_line, mailbox, url, eligibility_note, caveat, dedicated_coordinator, also_in_crisis_floor, last_checked, status, source_ids) VALUES ('nat.np.cohen', 'national', 'FEDERAL', 'Cohen Veterans Network', NULL, 'nonprofit', NULL, ARRAY['wv_ptsd','wv_mental_health','wv_parenthood']::text[], '844-336-4226', '+18443364226', NULL, NULL, 'https://www.cohenveteransnetwork.org/', 'Free or low-cost therapy for post-9/11 veterans and families; accepts TRICARE; telehealth. Clinic list in cohen_clinics.', 'Clinic count is contested (conflict.wv.cohen_clinic_count).', NULL, NULL, NULL, 'UNVERIFIED', ARRAY['src.rr.women_veterans_50_state','src.mod.women_veterans']::text[]);
INSERT INTO ref.directory_entry (entry_id, kind, jurisdiction_code, name, place, org_type, program, care_types, phone, phone_e164, text_line, mailbox, url, eligibility_note, caveat, dedicated_coordinator, also_in_crisis_floor, last_checked, status, source_ids) VALUES ('nat.np.headstrong', 'national', 'FEDERAL', 'Headstrong Project', NULL, 'nonprofit', NULL, ARRAY['wv_ptsd','wv_mental_health']::text[], NULL, NULL, NULL, NULL, 'https://www.theheadstrongproject.org/', 'Free trauma-focused therapy (CPT, EMDR, PE); first 30 sessions cost-free; intake response within 2 business days. States listed by the source: AZ, CA, CO, FL, GA, ID, IL, MD, NJ, NY, NC, OR, PA, TX, VA, WA, plus DC.', 'Source says 15 states + DC but lists 16 states (conflict.wv.headstrong_state_count).', NULL, NULL, NULL, 'UNVERIFIED', ARRAY['src.rr.women_veterans_50_state']::text[]);
INSERT INTO ref.directory_entry (entry_id, kind, jurisdiction_code, name, place, org_type, program, care_types, phone, phone_e164, text_line, mailbox, url, eligibility_note, caveat, dedicated_coordinator, also_in_crisis_floor, last_checked, status, source_ids) VALUES ('nat.np.wwp_women_warriors', 'national', 'FEDERAL', 'Wounded Warrior Project — Women Warriors Initiative', NULL, 'nonprofit', NULL, ARRAY['wv_mental_health','wv_mst']::text[], NULL, NULL, NULL, NULL, 'https://www.woundedwarriorproject.org/', 'WWP Talk (weekly one-to-one calls), Project Odyssey (12 weeks), Warrior Care Network; funds women-veteran MST programs.', NULL, NULL, NULL, NULL, 'UNVERIFIED', ARRAY['src.rr.women_veterans_50_state']::text[]);
INSERT INTO ref.directory_entry (entry_id, kind, jurisdiction_code, name, place, org_type, program, care_types, phone, phone_e164, text_line, mailbox, url, eligibility_note, caveat, dedicated_coordinator, also_in_crisis_floor, last_checked, status, source_ids) VALUES ('nat.np.give_an_hour', 'national', 'FEDERAL', 'Give an Hour', NULL, 'nonprofit', NULL, ARRAY['wv_mental_health']::text[], NULL, NULL, NULL, NULL, 'https://giveanhour.org/', 'Free mental health care through volunteer providers in every state; serves regardless of discharge status per the source.', NULL, NULL, NULL, NULL, 'UNVERIFIED', ARRAY['src.rr.women_veterans_50_state']::text[]);
