INSERT INTO ref.directory_entry (entry_id, kind, jurisdiction_code, name, place, org_type, program, care_types, phone, phone_e164, text_line, mailbox, url, eligibility_note, caveat, dedicated_coordinator, also_in_crisis_floor, last_checked, status, source_ids) VALUES ('nat.np.usvets_advance', 'national', 'FEDERAL', 'U.S.VETS ADVANCE Women''s Program', NULL, 'nonprofit', NULL, ARRAY['wv_housing','wv_mst','wv_employment']::text[], NULL, NULL, NULL, NULL, 'https://usvets.org/', 'Women veterans including those with children: sexual-trauma treatment, substance-use treatment, work re-entry. Sites named: Long Beach CA, Barber''s Point HI, Phoenix AZ (women''s wing opened 2026). Also runs Women Vets on Point (national navigation).', NULL, NULL, NULL, NULL, 'UNVERIFIED', ARRAY['src.rr.women_veterans_50_state']::text[]);
