INSERT INTO ref.education_program (program_id, name, authority, carried_by, stacking_notes, note, is_authority_stub, status, source_ids) VALUES ('edu.dod.ta', 'Federal Tuition Assistance', '10 U.S.C. 2007; DoDI 1322.25', ARRAY['ednav:dod.tuition_assistance','v2.0','sentinel:gr.fta']::text[], NULL, 'Subject to appropriation. Sentinel''s FY26 figures are in guard_reserve.json.', true, 'UNVERIFIED', ARRAY['src.mod.education_navigator','src.gov.master_record','src.mod.sentinel']::text[]);
