INSERT INTO ref.rating_code (code, name, body_system, subsection, cfr_section, notes, has_criteria, status, status_note, source_ids, cited_codes) VALUES ('5000', 'Osteomyelitis, acute, subacute, or chronic', 'THE MUSCULOSKELETAL SYSTEM', 'Acute, Subacute, or Chronic Diseases', '38 CFR 4.71a', 'Note (1): A rating of 10 percent, as an exception to the amputation rule, is to be assigned in any case of active osteomyelitis where the amputation rating for the affected part is no percent. This 10 percent rating and the other partial ratings of 30 percent or less are to be combined with ratings for ankylosis, limited motion, nonunion or malunion, shortening, etc., subject, of course, to the amputation rule. The 60 percent rating, as it is based on constitutional symptoms, is not subject to the amputation rule. A rating for osteomyelitis will not be applied following cure by removal or radical resection of the affected bone. Note (2): The 20 percent rating on the basis of activity within the past 5 years is not assignable following the initial infection of active osteomyelitis with no subsequent reactivation. The prerequisite for this historical rating is an established recurrent osteomyelitis. To qualify for the 10 percent rating, 2 or more episodes following the initial infection are required. This 20 percent rating or the 10 percent rating, when applicable, will be assigned once only to cover disability at all sites of previously active infection with a future ending date in the case of the 20 percent rating.', true, 'SOURCE_CHECKED', NULL, ARRAY['src.ecfr.38_part4_2026_08_27']::text[], '{}'::text[]);
INSERT INTO ref.rating_code (code, name, body_system, subsection, cfr_section, notes, has_criteria, status, status_note, source_ids, cited_codes) VALUES ('5001', 'Bones and Joints, tuberculosis', 'THE MUSCULOSKELETAL SYSTEM', 'Acute, Subacute, or Chronic Diseases', '38 CFR 4.71a', 'Inactive: See §§ 4.88c and 4.89', true, 'SOURCE_CHECKED', NULL, ARRAY['src.ecfr.38_part4_2026_08_27']::text[], '{}'::text[]);
INSERT INTO ref.rating_code (code, name, body_system, subsection, cfr_section, notes, has_criteria, status, status_note, source_ids, cited_codes) VALUES ('5002', 'Multi-joint arthritis (except post-traumatic and gout), 2 or more joints, as an active process', 'THE MUSCULOSKELETAL SYSTEM', 'Acute, Subacute, or Chronic Diseases', '38 CFR 4.71a', 'Note (1): Examples of conditions rated using this diagnostic code include, but are not limited to, rheumatoid arthritis, psoriatic arthritis, and spondyloarthropathies. Note (2): For chronic residuals, rate under diagnostic code 5003. Note (3): The ratings for the active process will not be combined with the residual ratings for limitation of motion, ankylosis, or diagnostic code 5003. Instead, assign the higher evaluation.', true, 'SOURCE_CHECKED', NULL, ARRAY['src.ecfr.38_part4_2026_08_27']::text[], ARRAY['5003']::text[]);
INSERT INTO ref.rating_code (code, name, body_system, subsection, cfr_section, notes, has_criteria, status, status_note, source_ids, cited_codes) VALUES ('5003', 'Degenerative arthritis, other than post-traumatic', 'THE MUSCULOSKELETAL SYSTEM', 'Acute, Subacute, or Chronic Diseases', '38 CFR 4.71a', 'Degenerative arthritis established by X-ray findings will be rated on the basis of limitation of motion under the appropriate diagnostic codes for the specific joint or joints involved (DC 5200 etc.). When however, the limitation of motion of the specific joint or joints involved is noncompensable under the appropriate diagnostic codes, a rating of 10 pct is for application for each such major joint or group of minor joints affected by limitation of motion, to be combined, not added under diagnostic code 5003. Limitation of motion must be objectively confirmed by findings such as swelling, muscle spasm, or satisfactory evidence of painful motion. In the absence of limitation of motion, rate as below: Note (1): The 20 pct and 10 pct ratings based on X-ray findings, above, will not be combined with ratings based on limitation of motion. Note (2): The 20 pct and 10 pct ratings based on X-ray findings, above, will not be utilized in rating conditions listed under diagnostic codes 5013 to 5024, inclusive.', true, 'SOURCE_CHECKED', NULL, ARRAY['src.ecfr.38_part4_2026_08_27']::text[], ARRAY['5013','5014','5015','5016','5017','5019','5021','5023','5024','5200']::text[]);
INSERT INTO ref.rating_code (code, name, body_system, subsection, cfr_section, notes, has_criteria, status, status_note, source_ids, cited_codes) VALUES ('5004', 'Arthritis, gonorrheal', 'THE MUSCULOSKELETAL SYSTEM', 'Acute, Subacute, or Chronic Diseases', '38 CFR 4.71a', 'Note (2): With the types of arthritis, diagnostic codes 5004 through 5009, rate the acute phase under diagnostic code 5002; rate any chronic residuals under diagnostic code 5003.', false, 'SOURCE_CHECKED', NULL, ARRAY['src.ecfr.38_part4_2026_08_27']::text[], ARRAY['5002','5003','5005','5006','5007','5008','5009']::text[]);
INSERT INTO ref.rating_code (code, name, body_system, subsection, cfr_section, notes, has_criteria, status, status_note, source_ids, cited_codes) VALUES ('5005', 'Arthritis, pneumococcic', 'THE MUSCULOSKELETAL SYSTEM', 'Acute, Subacute, or Chronic Diseases', '38 CFR 4.71a', 'Note (2): With the types of arthritis, diagnostic codes 5004 through 5009, rate the acute phase under diagnostic code 5002; rate any chronic residuals under diagnostic code 5003.', false, 'SOURCE_CHECKED', NULL, ARRAY['src.ecfr.38_part4_2026_08_27']::text[], ARRAY['5002','5003','5004','5006','5007','5008','5009']::text[]);
INSERT INTO ref.rating_code (code, name, body_system, subsection, cfr_section, notes, has_criteria, status, status_note, source_ids, cited_codes) VALUES ('5006', 'Arthritis, typhoid', 'THE MUSCULOSKELETAL SYSTEM', 'Acute, Subacute, or Chronic Diseases', '38 CFR 4.71a', 'Note (2): With the types of arthritis, diagnostic codes 5004 through 5009, rate the acute phase under diagnostic code 5002; rate any chronic residuals under diagnostic code 5003.', false, 'SOURCE_CHECKED', NULL, ARRAY['src.ecfr.38_part4_2026_08_27']::text[], ARRAY['5002','5003','5004','5005','5007','5008','5009']::text[]);
