INSERT INTO ref.rating_code (code, name, body_system, subsection, cfr_section, notes, has_criteria, status, status_note, source_ids, cited_codes) VALUES ('5008', 'Arthritis, streptococcic', 'THE MUSCULOSKELETAL SYSTEM', 'Acute, Subacute, or Chronic Diseases', '38 CFR 4.71a', 'Note (2): With the types of arthritis, diagnostic codes 5004 through 5009, rate the acute phase under diagnostic code 5002; rate any chronic residuals under diagnostic code 5003.', false, 'SOURCE_CHECKED', NULL, ARRAY['src.ecfr.38_part4_2026_08_27']::text[], ARRAY['5002','5003','5004','5005','5006','5007','5009']::text[]);
INSERT INTO ref.rating_code (code, name, body_system, subsection, cfr_section, notes, has_criteria, status, status_note, source_ids, cited_codes) VALUES ('5009', 'Other specified forms of arthropathy (excluding gout)', 'THE MUSCULOSKELETAL SYSTEM', 'Acute, Subacute, or Chronic Diseases', '38 CFR 4.71a', 'Note (1): Other specified forms of arthropathy include, but are not limited to, Charcot neuropathic, hypertrophic, crystalline, and other autoimmune arthropathies. Note (2): With the types of arthritis, diagnostic codes 5004 through 5009, rate the acute phase under diagnostic code 5002; rate any chronic residuals under diagnostic code 5003.', false, 'SOURCE_CHECKED', NULL, ARRAY['src.ecfr.38_part4_2026_08_27']::text[], ARRAY['5002','5003','5004','5005','5006','5007','5008']::text[]);
INSERT INTO ref.rating_code (code, name, body_system, subsection, cfr_section, notes, has_criteria, status, status_note, source_ids, cited_codes) VALUES ('5010', 'Post-traumatic arthritis', 'THE MUSCULOSKELETAL SYSTEM', 'Acute, Subacute, or Chronic Diseases', '38 CFR 4.71a', 'Post-traumatic arthritis: Rate as limitation of motion, dislocation, or other specified instability under the affected joint. If there are 2 or more joints affected, each rating shall be combined in accordance with § 4.25.', false, 'SOURCE_CHECKED', NULL, ARRAY['src.ecfr.38_part4_2026_08_27']::text[], '{}'::text[]);
INSERT INTO ref.rating_code (code, name, body_system, subsection, cfr_section, notes, has_criteria, status, status_note, source_ids, cited_codes) VALUES ('5011', 'Decompression illness', 'THE MUSCULOSKELETAL SYSTEM', 'Acute, Subacute, or Chronic Diseases', '38 CFR 4.71a', NULL, false, 'SOURCE_CHECKED', NULL, ARRAY['src.ecfr.38_part4_2026_08_27']::text[], '{}'::text[]);
INSERT INTO ref.rating_code (code, name, body_system, subsection, cfr_section, notes, has_criteria, status, status_note, source_ids, cited_codes) VALUES ('5012', 'Bones, neoplasm, malignant, primary or secondary', 'THE MUSCULOSKELETAL SYSTEM', 'Acute, Subacute, or Chronic Diseases', '38 CFR 4.71a', 'Note: The 100 percent rating will be continued for 1 year following the cessation of surgical, X-ray, antineoplastic chemotherapy or other prescribed therapeutic procedure. If there has been no local recurrence or metastases, rate based on residuals.', true, 'SOURCE_CHECKED', NULL, ARRAY['src.ecfr.38_part4_2026_08_27']::text[], '{}'::text[]);
INSERT INTO ref.rating_code (code, name, body_system, subsection, cfr_section, notes, has_criteria, status, status_note, source_ids, cited_codes) VALUES ('5013', 'Osteoporosis, residuals of', 'THE MUSCULOSKELETAL SYSTEM', 'Acute, Subacute, or Chronic Diseases', '38 CFR 4.71a', 'Note (2): The 20 pct and 10 pct ratings based on X-ray findings, above, will not be utilized in rating conditions listed under diagnostic codes 5013 to 5024, inclusive. Note to DCs 5013 through 5024: Evaluate the diseases under diagnostic codes 5013 through 5024 as degenerative arthritis, based on limitation of motion of affected parts.', false, 'SOURCE_CHECKED', NULL, ARRAY['src.ecfr.38_part4_2026_08_27']::text[], ARRAY['5014','5015','5016','5017','5019','5021','5023','5024']::text[]);
