INSERT INTO ref.rating_code (code, name, body_system, subsection, cfr_section, notes, has_criteria, status, status_note, source_ids, cited_codes) VALUES ('5213', 'Supination and pronation, impairment', 'THE MUSCULOSKELETAL SYSTEM', 'Elbow and Forearm', '38 CFR 4.71a', 'Note: In all the forearm and wrist injuries, codes 5205 through 5213, multiple impaired finger movements due to tendon tie-up, muscle or nerve injury, are to be separately rated and combined not to exceed rating for loss of use of hand.', true, 'SOURCE_CHECKED', NULL, ARRAY['src.ecfr.38_part4_2026_08_27']::text[], ARRAY['5205','5206','5207','5208','5209','5210','5211','5212']::text[]);
