INSERT INTO ref.rating_code (code, name, body_system, subsection, cfr_section, notes, has_criteria, status, status_note, source_ids, cited_codes) VALUES ('5242', 'Degenerative arthritis, degenerative disc disease other than intervertebral disc syndrome (also, see either DC 5003 or 5010)', 'THE MUSCULOSKELETAL SYSTEM', 'Spine', '38 CFR 4.71a', NULL, false, 'SOURCE_CHECKED', NULL, ARRAY['src.ecfr.38_part4_2026_08_27']::text[], '{}'::text[]);
INSERT INTO ref.rating_code (code, name, body_system, subsection, cfr_section, notes, has_criteria, status, status_note, source_ids, cited_codes) VALUES ('5243', 'Intervertebral disc syndrome', 'THE MUSCULOSKELETAL SYSTEM', 'Spine', '38 CFR 4.71a', 'Evaluate intervertebral disc syndrome (preoperatively or postoperatively) either under the General Rating Formula for Diseases and Injuries of the Spine or under the Formula for Rating Intervertebral Disc Syndrome Based on Incapacitating Episodes, whichever method results in the higher evaluation when all disabilities are combined under § 4.25.', false, 'SOURCE_CHECKED', NULL, ARRAY['src.ecfr.38_part4_2026_08_27']::text[], '{}'::text[]);
INSERT INTO ref.rating_code (code, name, body_system, subsection, cfr_section, notes, has_criteria, status, status_note, source_ids, cited_codes) VALUES ('5244', 'Traumatic paralysis, complete', 'THE MUSCULOSKELETAL SYSTEM', 'Spine', '38 CFR 4.71a', 'Paraplegia: Rate under diagnostic code 5110. Quadriplegia: Rate separately under diagnostic codes 5109 and 5110 and combine evaluations in accordance with § 4.25. Note: If traumatic paralysis does not cause loss of use of both hands or both feet, it is incomplete paralysis. Evaluate residuals of incomplete traumatic paralysis under the appropriate diagnostic code (e.g., § 4.124a, Diseases of the Peripheral Nerves).', false, 'SOURCE_CHECKED', NULL, ARRAY['src.ecfr.38_part4_2026_08_27']::text[], ARRAY['5109','5110']::text[]);
INSERT INTO ref.rating_code (code, name, body_system, subsection, cfr_section, notes, has_criteria, status, status_note, source_ids, cited_codes) VALUES ('5250', 'Hip, ankylosis', 'THE MUSCULOSKELETAL SYSTEM', 'Hip and Thigh', '38 CFR 4.71a', 'Note: At the conclusion of the 100 percent evaluation period, evaluate resurfacing under diagnostic codes 5250 through 5255; there is no minimum evaluation for resurfacing.', true, 'SOURCE_CHECKED', NULL, ARRAY['src.ecfr.38_part4_2026_08_27']::text[], ARRAY['5251','5252','5253','5254','5255']::text[]);
INSERT INTO ref.rating_code (code, name, body_system, subsection, cfr_section, notes, has_criteria, status, status_note, source_ids, cited_codes) VALUES ('5251', 'Thigh, limitation of extension', 'THE MUSCULOSKELETAL SYSTEM', 'Hip and Thigh', '38 CFR 4.71a', 'Note: At the conclusion of the 100 percent evaluation period, evaluate resurfacing under diagnostic codes 5250 through 5255; there is no minimum evaluation for resurfacing.', true, 'SOURCE_CHECKED', NULL, ARRAY['src.ecfr.38_part4_2026_08_27']::text[], ARRAY['5250','5252','5253','5254','5255']::text[]);
INSERT INTO ref.rating_code (code, name, body_system, subsection, cfr_section, notes, has_criteria, status, status_note, source_ids, cited_codes) VALUES ('5252', 'Thigh, limitation of flexion', 'THE MUSCULOSKELETAL SYSTEM', 'Hip and Thigh', '38 CFR 4.71a', 'Note: At the conclusion of the 100 percent evaluation period, evaluate resurfacing under diagnostic codes 5250 through 5255; there is no minimum evaluation for resurfacing.', true, 'SOURCE_CHECKED', NULL, ARRAY['src.ecfr.38_part4_2026_08_27']::text[], ARRAY['5250','5251','5253','5254','5255']::text[]);
INSERT INTO ref.rating_code (code, name, body_system, subsection, cfr_section, notes, has_criteria, status, status_note, source_ids, cited_codes) VALUES ('5253', 'Thigh, impairment', 'THE MUSCULOSKELETAL SYSTEM', 'Hip and Thigh', '38 CFR 4.71a', 'Note: At the conclusion of the 100 percent evaluation period, evaluate resurfacing under diagnostic codes 5250 through 5255; there is no minimum evaluation for resurfacing.', true, 'SOURCE_CHECKED', NULL, ARRAY['src.ecfr.38_part4_2026_08_27']::text[], ARRAY['5250','5251','5252','5254','5255']::text[]);
INSERT INTO ref.rating_code (code, name, body_system, subsection, cfr_section, notes, has_criteria, status, status_note, source_ids, cited_codes) VALUES ('5254', 'Hip, flail joint', 'THE MUSCULOSKELETAL SYSTEM', 'Hip and Thigh', '38 CFR 4.71a', 'Note: At the conclusion of the 100 percent evaluation period, evaluate resurfacing under diagnostic codes 5250 through 5255; there is no minimum evaluation for resurfacing.', true, 'SOURCE_CHECKED', NULL, ARRAY['src.ecfr.38_part4_2026_08_27']::text[], ARRAY['5250','5251','5252','5253','5255']::text[]);
INSERT INTO ref.rating_code (code, name, body_system, subsection, cfr_section, notes, has_criteria, status, status_note, source_ids, cited_codes) VALUES ('5255', 'Femur, impairment', 'THE MUSCULOSKELETAL SYSTEM', 'Hip and Thigh', '38 CFR 4.71a', 'Malunion of: Evaluate under diagnostic codes 5256, 5257, 5260, or 5261 for the knee, or 5250-5254 for the hip, whichever results in the highest evaluation. Note: At the conclusion of the 100 percent evaluation period, evaluate resurfacing under diagnostic codes 5250 through 5255; there is no minimum evaluation for resurfacing.', true, 'SOURCE_CHECKED', NULL, ARRAY['src.ecfr.38_part4_2026_08_27']::text[], ARRAY['5250','5251','5252','5253','5254','5256','5257','5260','5261']::text[]);
INSERT INTO ref.rating_code (code, name, body_system, subsection, cfr_section, notes, has_criteria, status, status_note, source_ids, cited_codes) VALUES ('5256', 'Knee, ankylosis', 'THE MUSCULOSKELETAL SYSTEM', 'Knee and Leg', '38 CFR 4.71a', 'Note: At the conclusion of the 100 percent evaluation period, evaluate resurfacing under diagnostic codes 5256 through 5262; there is no minimum evaluation for resurfacing.', true, 'SOURCE_CHECKED', NULL, ARRAY['src.ecfr.38_part4_2026_08_27']::text[], ARRAY['5257','5258','5259','5260','5261','5262']::text[]);
INSERT INTO ref.rating_code (code, name, body_system, subsection, cfr_section, notes, has_criteria, status, status_note, source_ids, cited_codes) VALUES ('5257', 'Knee, other impairment', 'THE MUSCULOSKELETAL SYSTEM', 'Knee and Leg', '38 CFR 4.71a', 'Note (1): For patellar instability, the patellofemoral complex consists of the quadriceps tendon, the patella, and the patellar tendon. Note (2): A surgical procedure that does not involve repair of one or more patellofemoral components that contribute to the underlying instability shall not qualify as surgical repair for patellar instability (including, but not limited to, arthroscopy to remove loose bodies and joint aspiration). Note: At the conclusion of the 100 percent evaluation period, evaluate resurfacing under diagnostic codes 5256 through 5262; there is no minimum evaluation for resurfacing.', true, 'SOURCE_CHECKED', NULL, ARRAY['src.ecfr.38_part4_2026_08_27']::text[], ARRAY['5256','5258','5259','5260','5261','5262']::text[]);
INSERT INTO ref.rating_code (code, name, body_system, subsection, cfr_section, notes, has_criteria, status, status_note, source_ids, cited_codes) VALUES ('5258', 'Cartilage, semilunar, dislocated', 'THE MUSCULOSKELETAL SYSTEM', 'Knee and Leg', '38 CFR 4.71a', 'Note: At the conclusion of the 100 percent evaluation period, evaluate resurfacing under diagnostic codes 5256 through 5262; there is no minimum evaluation for resurfacing.', true, 'SOURCE_CHECKED', NULL, ARRAY['src.ecfr.38_part4_2026_08_27']::text[], ARRAY['5256','5257','5259','5260','5261','5262']::text[]);
INSERT INTO ref.rating_code (code, name, body_system, subsection, cfr_section, notes, has_criteria, status, status_note, source_ids, cited_codes) VALUES ('5259', 'Cartilage, semilunar, removal', 'THE MUSCULOSKELETAL SYSTEM', 'Knee and Leg', '38 CFR 4.71a', 'Note: At the conclusion of the 100 percent evaluation period, evaluate resurfacing under diagnostic codes 5256 through 5262; there is no minimum evaluation for resurfacing.', true, 'SOURCE_CHECKED', NULL, ARRAY['src.ecfr.38_part4_2026_08_27']::text[], ARRAY['5256','5257','5258','5260','5261','5262']::text[]);
INSERT INTO ref.rating_code (code, name, body_system, subsection, cfr_section, notes, has_criteria, status, status_note, source_ids, cited_codes) VALUES ('5260', 'Leg, limitation of flexion', 'THE MUSCULOSKELETAL SYSTEM', 'Knee and Leg', '38 CFR 4.71a', 'Note: At the conclusion of the 100 percent evaluation period, evaluate resurfacing under diagnostic codes 5256 through 5262; there is no minimum evaluation for resurfacing.', true, 'SOURCE_CHECKED', NULL, ARRAY['src.ecfr.38_part4_2026_08_27']::text[], ARRAY['5256','5257','5258','5259','5261','5262']::text[]);
INSERT INTO ref.rating_code (code, name, body_system, subsection, cfr_section, notes, has_criteria, status, status_note, source_ids, cited_codes) VALUES ('5261', 'Leg, limitation of extension', 'THE MUSCULOSKELETAL SYSTEM', 'Knee and Leg', '38 CFR 4.71a', 'Note: At the conclusion of the 100 percent evaluation period, evaluate resurfacing under diagnostic codes 5256 through 5262; there is no minimum evaluation for resurfacing.', true, 'SOURCE_CHECKED', NULL, ARRAY['src.ecfr.38_part4_2026_08_27']::text[], ARRAY['5256','5257','5258','5259','5260','5262']::text[]);
INSERT INTO ref.rating_code (code, name, body_system, subsection, cfr_section, notes, has_criteria, status, status_note, source_ids, cited_codes) VALUES ('5262', 'Tibia and fibula, impairment', 'THE MUSCULOSKELETAL SYSTEM', 'Knee and Leg', '38 CFR 4.71a', 'Evaluate under diagnostic codes 5256, 5257, 5260, or 5261 for the knee, or 5270 or 5271 for the ankle, whichever results in the highest evaluation. Note: At the conclusion of the 100 percent evaluation period, evaluate resurfacing under diagnostic codes 5256 through 5262; there is no minimum evaluation for resurfacing.', true, 'SOURCE_CHECKED', NULL, ARRAY['src.ecfr.38_part4_2026_08_27']::text[], ARRAY['5256','5257','5258','5259','5260','5261','5270','5271']::text[]);
INSERT INTO ref.rating_code (code, name, body_system, subsection, cfr_section, notes, has_criteria, status, status_note, source_ids, cited_codes) VALUES ('5263', 'Genu recurvatum', 'THE MUSCULOSKELETAL SYSTEM', 'Knee and Leg', '38 CFR 4.71a', NULL, true, 'SOURCE_CHECKED', NULL, ARRAY['src.ecfr.38_part4_2026_08_27']::text[], '{}'::text[]);
INSERT INTO ref.rating_code (code, name, body_system, subsection, cfr_section, notes, has_criteria, status, status_note, source_ids, cited_codes) VALUES ('5269', 'Plantar fasciitis', 'THE MUSCULOSKELETAL SYSTEM', 'The Foot', '38 CFR 4.71a', 'Note (1): With actual loss of use of the foot, rate 40 percent Note (2): If a veteran has been recommended for surgical intervention, but is not a surgical candidate, evaluate under the 20 percent or 30 percent criteria, whichever is applicable', true, 'SOURCE_CHECKED', NULL, ARRAY['src.ecfr.38_part4_2026_08_27']::text[], '{}'::text[]);
INSERT INTO ref.rating_code (code, name, body_system, subsection, cfr_section, notes, has_criteria, status, status_note, source_ids, cited_codes) VALUES ('5270', 'Ankle, ankylosis', 'THE MUSCULOSKELETAL SYSTEM', 'Ankle', '38 CFR 4.71a', NULL, true, 'SOURCE_CHECKED', NULL, ARRAY['src.ecfr.38_part4_2026_08_27']::text[], '{}'::text[]);
