INSERT INTO ref.rating_code (code, name, body_system, subsection, cfr_section, notes, has_criteria, status, status_note, source_ids, cited_codes) VALUES ('5297', 'Removal of', 'THE MUSCULOSKELETAL SYSTEM', 'The Ribs', '38 CFR 4.71a', 'Note (1): The rating for rib resection or removal is not to be applied with ratings for purrulent pleurisy, lobectomy, pneumonectomy or injuries of pleural cavity. Note (2): However, rib resection will be considered as rib removal in thoracoplasty performed for collapse therapy or to accomplish obliteration of space and will be combined with the rating for lung collapse, or with the rating for lobectomy, pneumonectomy or the graduated ratings for pulmonary tuberculosis.', true, 'SOURCE_CHECKED', NULL, ARRAY['src.ecfr.38_part4_2026_08_27']::text[], '{}'::text[]);
