INSERT INTO ref.rating_code (code, name, body_system, subsection, cfr_section, notes, has_criteria, status, status_note, source_ids, cited_codes) VALUES ('6014', 'Malignant neoplasms of the eye, orbit, and adnexa (excluding skin)', 'THE EYE', 'Diseases of the Eye', '38 CFR 4.79', 'Note: Continue the 100 percent rating beyond the cessation of any surgical, X-ray, antineoplastic chemotherapy, or other therapeutic procedure. Six months after discontinuance of such treatment, the appropriate disability rating will be determined by mandatory VA examination. Any change in evaluation based upon that or any subsequent examination will be subject to the provisions of § 3.105(e) of this chapter. If there has been no local recurrence or metastasis, evaluate based on residuals Malignant neoplasms of the eye, orbit, and adnexa (excluding skin) that do not require therapy comparable to that for systemic malignancies: Separately evaluate visual and nonvisual impairment, e.g., disfigurement (diagnostic code 7800), and combine the evaluations', true, 'SOURCE_CHECKED', NULL, ARRAY['src.ecfr.38_part4_2026_08_27']::text[], ARRAY['7800']::text[]);
INSERT INTO ref.rating_code (code, name, body_system, subsection, cfr_section, notes, has_criteria, status, status_note, source_ids, cited_codes) VALUES ('6015', 'Benign neoplasms of the eye, orbit, and adnexa (excluding skin)', 'THE EYE', 'Diseases of the Eye', '38 CFR 4.79', 'Separately evaluate visual and nonvisual impairment, e.g., disfigurement (diagnostic code 7800), and combine the evaluations', false, 'SOURCE_CHECKED', NULL, ARRAY['src.ecfr.38_part4_2026_08_27']::text[], ARRAY['7800']::text[]);
INSERT INTO ref.rating_code (code, name, body_system, subsection, cfr_section, notes, has_criteria, status, status_note, source_ids, cited_codes) VALUES ('6016', 'Nystagmus, central', 'THE EYE', 'Diseases of the Eye', '38 CFR 4.79', NULL, true, 'SOURCE_CHECKED', NULL, ARRAY['src.ecfr.38_part4_2026_08_27']::text[], '{}'::text[]);
INSERT INTO ref.rating_code (code, name, body_system, subsection, cfr_section, notes, has_criteria, status, status_note, source_ids, cited_codes) VALUES ('6017', 'Conjunctivitis, trachomatous, chronic', 'THE EYE', 'Diseases of the Eye', '38 CFR 4.79', 'Inactive: Evaluate based on residuals, such as visual impairment and disfigurement (diagnostic code 7800)', true, 'SOURCE_CHECKED', NULL, ARRAY['src.ecfr.38_part4_2026_08_27']::text[], ARRAY['7800']::text[]);
