INSERT INTO ref.rating_code (code, name, body_system, subsection, cfr_section, notes, has_criteria, status, status_note, source_ids, cited_codes) VALUES ('6019', 'Ptosis unilateral or bilateral', 'THE EYE', 'Diseases of the Eye', '38 CFR 4.79', 'Evaluate based on visual impairment or, in the absence of visual impairment, on disfigurement (diagnostic code 7800).', false, 'SOURCE_CHECKED', NULL, ARRAY['src.ecfr.38_part4_2026_08_27']::text[], ARRAY['7800']::text[]);
