INSERT INTO ref.rating_code (code, name, body_system, subsection, cfr_section, notes, has_criteria, status, status_note, source_ids, cited_codes) VALUES ('6027', 'Cataract', 'THE EYE', 'Diseases of the Eye', '38 CFR 4.79', 'Preoperative: Evaluate under the General Rating Formula for Diseases of the Eye Postoperative: If a replacement lens is present (pseudophakia), evaluate under the General Rating Formula for Diseases of the Eye. If there is no replacement lens, evaluate based on aphakia (diagnostic code 6029)', false, 'SOURCE_CHECKED', NULL, ARRAY['src.ecfr.38_part4_2026_08_27']::text[], ARRAY['6029']::text[]);
