INSERT INTO ref.rating_code (code, name, body_system, subsection, cfr_section, notes, has_criteria, status, status_note, source_ids, cited_codes) VALUES ('6061', 'Anatomical loss both eyes', 'THE EYE', 'Impairment of Central Visual Acuity', '38 CFR 4.79', 'Note (2): Separately evaluate eye involvement occurring as a manifestation of Graves'' Disease as diplopia (DC 6090); impairment of central visual acuity (DCs 6061-6066); or under the most appropriate DCs in § 4.79. Note (3): If eye involvement, such as exophthalmos, corneal ulcer, blurred vision, or diplopia, is also present due to thyroid disease, also separately evaluate under the appropriate diagnostic code(s) in § 4.79, Schedule of Ratings—Eye (such as diplopia (DC 6090) or impairment of central visual acuity (DCs 6061-6066)).', true, 'SOURCE_CHECKED', NULL, ARRAY['src.ecfr.38_part4_2026_08_27']::text[], ARRAY['6062','6063','6064','6065','6066','6090']::text[]);
INSERT INTO ref.rating_code (code, name, body_system, subsection, cfr_section, notes, has_criteria, status, status_note, source_ids, cited_codes) VALUES ('6062', 'Blindness, both eyes, only light perception', 'THE EYE', 'Impairment of Central Visual Acuity', '38 CFR 4.79', 'Note (2): Separately evaluate eye involvement occurring as a manifestation of Graves'' Disease as diplopia (DC 6090); impairment of central visual acuity (DCs 6061-6066); or under the most appropriate DCs in § 4.79. Note (3): If eye involvement, such as exophthalmos, corneal ulcer, blurred vision, or diplopia, is also present due to thyroid disease, also separately evaluate under the appropriate diagnostic code(s) in § 4.79, Schedule of Ratings—Eye (such as diplopia (DC 6090) or impairment of central visual acuity (DCs 6061-6066)).', true, 'SOURCE_CHECKED', NULL, ARRAY['src.ecfr.38_part4_2026_08_27']::text[], ARRAY['6061','6063','6064','6065','6066','6090']::text[]);
