INSERT INTO ref.rating_code (code, name, body_system, subsection, cfr_section, notes, has_criteria, status, status_note, source_ids, cited_codes) VALUES ('6077', 'Vision in 1 eye 10/200 (3/60): Other eye 20/40 (6/12); Vision in 1 eye 15/200 (4.5/60): Other eye 20/40 (6/12); Vision in 1 eye 20/200 (6/60): Other eye 20/40 (6/12)', 'THE EYE', 'Impairment of Central Visual Acuity', '38 CFR 4.79', NULL, false, 'SUPERSEDED', 'Listed in Appendix B (the index) but not rated anywhere in the current schedule of 38 CFR Part 4; not a current diagnostic code.', ARRAY['src.ecfr.38_part4_2026_08_27']::text[], '{}'::text[]);
INSERT INTO ref.rating_code (code, name, body_system, subsection, cfr_section, notes, has_criteria, status, status_note, source_ids, cited_codes) VALUES ('6078', 'Vision in 1 eye 20/100 (6/30): Other eye 20/100 (6/30); Vision in 1 eye 20/100 (6/30): Other eye 20/70 (6/21); Vision in 1 eye 20/100 (6/30): Other eye 20/50 (6/15); Vision in 1 eye 20/70 (6/21): Other eye 20/70 (6/21); Vision in 1 eye 20/70 (6/21): Other eye 20/50 (6/15); Vision in 1 eye 20/50 (6/15): Other eye 20/50 (6/15)', 'THE EYE', 'Impairment of Central Visual Acuity', '38 CFR 4.79', NULL, false, 'SUPERSEDED', 'Listed in Appendix B (the index) but not rated anywhere in the current schedule of 38 CFR Part 4; not a current diagnostic code.', ARRAY['src.ecfr.38_part4_2026_08_27']::text[], '{}'::text[]);
INSERT INTO ref.rating_code (code, name, body_system, subsection, cfr_section, notes, has_criteria, status, status_note, source_ids, cited_codes) VALUES ('6079', 'Vision in 1 eye 20/100 (6/30): Other eye 20/40 (6/12); Vision in 1 eye 20/70 (6/21): Other eye 20/40 (6/12); Vision in 1 eye 20/50 (6/15): Other eye 20/40 (6/12)', 'THE EYE', 'Impairment of Central Visual Acuity', '38 CFR 4.79', NULL, false, 'SUPERSEDED', 'Listed in Appendix B (the index) but not rated anywhere in the current schedule of 38 CFR Part 4; not a current diagnostic code.', ARRAY['src.ecfr.38_part4_2026_08_27']::text[], '{}'::text[]);
INSERT INTO ref.rating_code (code, name, body_system, subsection, cfr_section, notes, has_criteria, status, status_note, source_ids, cited_codes) VALUES ('6080', 'Impairment of Field Vision: Field vision, impairment', 'THE EYE', 'Impairment of Central Visual Acuity', '38 CFR 4.79', 'Or evaluate each affected eye as 20/50 (6/15)', true, 'SOURCE_CHECKED', NULL, ARRAY['src.ecfr.38_part4_2026_08_27']::text[], '{}'::text[]);
INSERT INTO ref.rating_code (code, name, body_system, subsection, cfr_section, notes, has_criteria, status, status_note, source_ids, cited_codes) VALUES ('6081', 'Impairment of Field Vision: Scotoma', 'THE EYE', 'Impairment of Central Visual Acuity', '38 CFR 4.79', 'Alternatively, evaluate based on visual impairment due to scotoma, if that would result in a higher evaluation', true, 'SOURCE_CHECKED', NULL, ARRAY['src.ecfr.38_part4_2026_08_27']::text[], '{}'::text[]);
INSERT INTO ref.rating_code (code, name, body_system, subsection, cfr_section, notes, has_criteria, status, status_note, source_ids, cited_codes) VALUES ('6090', 'Impairment of Muscle Function: Diplopia', 'THE EYE', 'Impairment of Central Visual Acuity', '38 CFR 4.79', '(a) Central 20 degrees (Equivalentvisual acuity: 5/200 (1.5/60)) (b) 21 degrees to 30 degrees (1) Down (Equivalentvisual acuity: 15/200 (4.5/60)) (2) Lateral (Equivalentvisual acuity: 20/100 (6/30)) (3) Up (Equivalentvisual acuity: 20/70 (6/21)) (c) 31 degrees to 40 degrees (1) Down (Equivalentvisual acuity: 20/200 (6/60)) (2) Lateral (Equivalentvisual acuity: 20/70 (6/21)) (3) Up (Equivalentvisual acuity: 20/40 (6/12)) Note: In accordance with 38 CFR 4.31, diplopia that is occasional or that is correctable with spectacles is evaluated at 0 percent.', false, 'SOURCE_CHECKED', NULL, ARRAY['src.ecfr.38_part4_2026_08_27']::text[], '{}'::text[]);
INSERT INTO ref.rating_code (code, name, body_system, subsection, cfr_section, notes, has_criteria, status, status_note, source_ids, cited_codes) VALUES ('6091', 'Impairment of Muscle Function: Symblepharon', 'THE EYE', 'Impairment of Central Visual Acuity', '38 CFR 4.79', 'Evaluate under the General Rating Formula for Diseases of the Eye, lagophthalmos (diagnostic code 6022), disfigurement (diagnostic code 7800), etc., depending on the particular findings, and combine in accordance with § 4.25', false, 'SOURCE_CHECKED', NULL, ARRAY['src.ecfr.38_part4_2026_08_27']::text[], ARRAY['6022','7800']::text[]);
INSERT INTO ref.rating_code (code, name, body_system, subsection, cfr_section, notes, has_criteria, status, status_note, source_ids, cited_codes) VALUES ('6092', 'Impairment of Muscle Function: Diplopia, limited muscle function', 'THE EYE', 'Impairment of Central Visual Acuity', '38 CFR 4.79', NULL, false, 'SUPERSEDED', 'Listed in Appendix B (the index) but not rated anywhere in the current schedule of 38 CFR Part 4; not a current diagnostic code.', ARRAY['src.ecfr.38_part4_2026_08_27']::text[], '{}'::text[]);
INSERT INTO ref.rating_code (code, name, body_system, subsection, cfr_section, notes, has_criteria, status, status_note, source_ids, cited_codes) VALUES ('6200', 'Chronic suppurative otitis media', 'THE EAR', NULL, '38 CFR 4.87', 'Note: Evaluate hearing impairment, and complications such as labyrinthitis, tinnitus, facial nerve paralysis, or bone loss of skull, separately. Note (1): A separate evaluation for tinnitus may be combined with an evaluation under diagnostic codes 6100, 6200, 6204, or other diagnostic code, except when tinnitus supports an evaluation under one of those diagnostic codes.', true, 'SOURCE_CHECKED', NULL, ARRAY['src.ecfr.38_part4_2026_08_27']::text[], ARRAY['6204']::text[]);
INSERT INTO ref.rating_code (code, name, body_system, subsection, cfr_section, notes, has_criteria, status, status_note, source_ids, cited_codes) VALUES ('6201', 'Chronic nonsuppurative otitis media', 'THE EAR', NULL, '38 CFR 4.87', 'Rate hearing impairment', false, 'SOURCE_CHECKED', NULL, ARRAY['src.ecfr.38_part4_2026_08_27']::text[], '{}'::text[]);
INSERT INTO ref.rating_code (code, name, body_system, subsection, cfr_section, notes, has_criteria, status, status_note, source_ids, cited_codes) VALUES ('6202', 'Otosclerosis', 'THE EAR', NULL, '38 CFR 4.87', 'Rate hearing impairment', false, 'SOURCE_CHECKED', NULL, ARRAY['src.ecfr.38_part4_2026_08_27']::text[], '{}'::text[]);
INSERT INTO ref.rating_code (code, name, body_system, subsection, cfr_section, notes, has_criteria, status, status_note, source_ids, cited_codes) VALUES ('6204', 'Peripheral vestibular disorders', 'THE EAR', NULL, '38 CFR 4.87', 'Note: Objective findings supporting the diagnosis of vestibular disequilibrium are required before a compensable evaluation can be assigned under this code. Hearing impairment or suppuration shall be separately rated and combined. Note (1): A separate evaluation for tinnitus may be combined with an evaluation under diagnostic codes 6100, 6200, 6204, or other diagnostic code, except when tinnitus supports an evaluation under one of those diagnostic codes.', true, 'SOURCE_CHECKED', NULL, ARRAY['src.ecfr.38_part4_2026_08_27']::text[], ARRAY['6200']::text[]);
INSERT INTO ref.rating_code (code, name, body_system, subsection, cfr_section, notes, has_criteria, status, status_note, source_ids, cited_codes) VALUES ('6205', 'Meniere''s syndrome', 'THE EAR', NULL, '38 CFR 4.87', 'Note: Evaluate Meniere''s syndrome either under these criteria or by separately evaluating vertigo (as a peripheral vestibular disorder), hearing impairment, and tinnitus, whichever method results in a higher overall evaluation. But do not combine an evaluation for hearing impairment, tinnitus, or vertigo with an evaluation under diagnostic code 6205.', true, 'SOURCE_CHECKED', NULL, ARRAY['src.ecfr.38_part4_2026_08_27']::text[], '{}'::text[]);
INSERT INTO ref.rating_code (code, name, body_system, subsection, cfr_section, notes, has_criteria, status, status_note, source_ids, cited_codes) VALUES ('6207', 'Loss of auricle', 'THE EAR', NULL, '38 CFR 4.87', NULL, true, 'SOURCE_CHECKED', NULL, ARRAY['src.ecfr.38_part4_2026_08_27']::text[], '{}'::text[]);
INSERT INTO ref.rating_code (code, name, body_system, subsection, cfr_section, notes, has_criteria, status, status_note, source_ids, cited_codes) VALUES ('6208', 'Malignant neoplasm', 'THE EAR', NULL, '38 CFR 4.87', 'Note: A rating of 100 percent shall continue beyond the cessation of any surgical, radiation treatment, antineoplastic chemotherapy or other therapeutic procedure. Six months after discontinuance of such treatment, the appropriate disability rating shall be determined by mandatory VA examination. Any change in evaluation based on that or any subsequent examination shall be subject to the provisions of § 3.105(e) of this chapter. If there has been no local recurrence or metastasis, rate on residuals.', true, 'SOURCE_CHECKED', NULL, ARRAY['src.ecfr.38_part4_2026_08_27']::text[], '{}'::text[]);
INSERT INTO ref.rating_code (code, name, body_system, subsection, cfr_section, notes, has_criteria, status, status_note, source_ids, cited_codes) VALUES ('6209', 'Benign neoplasm', 'THE EAR', NULL, '38 CFR 4.87', 'Rate on impairment of function.', false, 'SOURCE_CHECKED', NULL, ARRAY['src.ecfr.38_part4_2026_08_27']::text[], '{}'::text[]);
INSERT INTO ref.rating_code (code, name, body_system, subsection, cfr_section, notes, has_criteria, status, status_note, source_ids, cited_codes) VALUES ('6210', 'Chronic otitis externa', 'THE EAR', NULL, '38 CFR 4.87', NULL, true, 'SOURCE_CHECKED', NULL, ARRAY['src.ecfr.38_part4_2026_08_27']::text[], '{}'::text[]);
INSERT INTO ref.rating_code (code, name, body_system, subsection, cfr_section, notes, has_criteria, status, status_note, source_ids, cited_codes) VALUES ('6211', 'Tympanic membrane', 'THE EAR', NULL, '38 CFR 4.87', NULL, true, 'SOURCE_CHECKED', NULL, ARRAY['src.ecfr.38_part4_2026_08_27']::text[], '{}'::text[]);
INSERT INTO ref.rating_code (code, name, body_system, subsection, cfr_section, notes, has_criteria, status, status_note, source_ids, cited_codes) VALUES ('6260', 'Tinnitus, recurrent', 'THE EAR', NULL, '38 CFR 4.87', 'Note (1): A separate evaluation for tinnitus may be combined with an evaluation under diagnostic codes 6100, 6200, 6204, or other diagnostic code, except when tinnitus supports an evaluation under one of those diagnostic codes. Note (2): Assign only a single evaluation for recurrent tinnitus, whether the sound is perceived in one ear, both ears, or in the head. Note (3): Do not evaluate objective tinnitus (in which the sound is audible to other people and has a definable cause that may or may not be pathologic) under this diagnostic code, but evaluate it as part of any underlying condition causing it.', true, 'SOURCE_CHECKED', NULL, ARRAY['src.ecfr.38_part4_2026_08_27']::text[], ARRAY['6200','6204']::text[]);
INSERT INTO ref.rating_code (code, name, body_system, subsection, cfr_section, notes, has_criteria, status, status_note, source_ids, cited_codes) VALUES ('6275', 'Smell, complete loss', 'OTHER SENSE ORGANS', NULL, '38 CFR 4.87a', 'Note: Evaluation will be assigned under diagnostic codes 6275 or 6276 only if there is an anatomical or pathological basis for the condition.', true, 'SOURCE_CHECKED', NULL, ARRAY['src.ecfr.38_part4_2026_08_27']::text[], ARRAY['6276']::text[]);
INSERT INTO ref.rating_code (code, name, body_system, subsection, cfr_section, notes, has_criteria, status, status_note, source_ids, cited_codes) VALUES ('6276', 'Taste, complete loss', 'OTHER SENSE ORGANS', NULL, '38 CFR 4.87a', 'Note: Evaluation will be assigned under diagnostic codes 6275 or 6276 only if there is an anatomical or pathological basis for the condition.', true, 'SOURCE_CHECKED', NULL, ARRAY['src.ecfr.38_part4_2026_08_27']::text[], ARRAY['6275']::text[]);
INSERT INTO ref.rating_code (code, name, body_system, subsection, cfr_section, notes, has_criteria, status, status_note, source_ids, cited_codes) VALUES ('6300', 'Vibriosis (Cholera, Non-cholera)', 'INFECTIOUS DISEASES, IMMUNE DISORDERS AND NUTRITIONAL DEFICIENCIES', NULL, '38 CFR 4.88b', 'Evaluate under the General Rating Formula. Note: Rate residuals of cholera and non-cholera vibrio infections, such as renal failure, skin, and musculoskeletal conditions, within the appropriate body system.', false, 'SOURCE_CHECKED', NULL, ARRAY['src.ecfr.38_part4_2026_08_27']::text[], '{}'::text[]);
INSERT INTO ref.rating_code (code, name, body_system, subsection, cfr_section, notes, has_criteria, status, status_note, source_ids, cited_codes) VALUES ('6301', 'Visceral Leishmaniasis', 'INFECTIOUS DISEASES, IMMUNE DISORDERS AND NUTRITIONAL DEFICIENCIES', NULL, '38 CFR 4.88b', 'Note 1: Continue a 100 percent evaluation beyond the cessation of treatment for active disease. Six months after discontinuance of such treatment, determine the appropriate disability rating by mandatory VA examination. Any change in evaluation based upon that or any subsequent examination shall be subject to the provisions of § 3.105(e) of this chapter. Thereafter, rate under the appropriate body system any residual disability of infection, which includes, but is not limited to liver damage and bone marrow disease. Note 2: Confirm the recurrence of active infection by culture, histopathology, or other diagnostic laboratory testing.', true, 'SOURCE_CHECKED', NULL, ARRAY['src.ecfr.38_part4_2026_08_27']::text[], '{}'::text[]);
INSERT INTO ref.rating_code (code, name, body_system, subsection, cfr_section, notes, has_criteria, status, status_note, source_ids, cited_codes) VALUES ('6302', 'Leprosy (Hansen''s Disease)', 'INFECTIOUS DISEASES, IMMUNE DISORDERS AND NUTRITIONAL DEFICIENCIES', NULL, '38 CFR 4.88b', 'Note: Continue a 100 percent evaluation beyond the cessation of treatment for active disease. Six months after discontinuance of such treatment, determine the appropriate disability rating by mandatory VA examination. Any change in evaluation based upon that or any subsequent examination shall be subject to the provisions of § 3.105(e) of this chapter. Thereafter, rate under the appropriate body system any residual disability of infection, which includes, but is not limited to, skin lesions, peripheral neuropathy, or amputations.', true, 'SOURCE_CHECKED', NULL, ARRAY['src.ecfr.38_part4_2026_08_27']::text[], '{}'::text[]);
INSERT INTO ref.rating_code (code, name, body_system, subsection, cfr_section, notes, has_criteria, status, status_note, source_ids, cited_codes) VALUES ('6304', 'Malaria', 'INFECTIOUS DISEASES, IMMUNE DISORDERS AND NUTRITIONAL DEFICIENCIES', NULL, '38 CFR 4.88b', 'Evaluate under the General Rating Formula. Note 1: The diagnosis of malaria, both initially and during relapse, depends on the identification of the malarial parasites in blood smears or other specific diagnostic laboratory tests such as antigen detection, immunologic (immunochromatographic) tests, and molecular testing such as polymerase chain reaction tests. Note 2: Rate under the appropriate body system any residual disability of infection, which includes, but is not limited to, liver or splenic damage, and central nervous system conditions.', false, 'SOURCE_CHECKED', NULL, ARRAY['src.ecfr.38_part4_2026_08_27']::text[], '{}'::text[]);
INSERT INTO ref.rating_code (code, name, body_system, subsection, cfr_section, notes, has_criteria, status, status_note, source_ids, cited_codes) VALUES ('6305', 'Lymphatic filariasis, to include elephantiasis', 'INFECTIOUS DISEASES, IMMUNE DISORDERS AND NUTRITIONAL DEFICIENCIES', NULL, '38 CFR 4.88b', 'Evaluate under the General Rating Formula. Note: Rate under the appropriate body system any residual disability of infection, which includes, but is not limited to, epididymitis, lymphangitis, lymphatic obstruction, or lymphedema affecting extremities, genitals, and/or breasts.', false, 'SOURCE_CHECKED', NULL, ARRAY['src.ecfr.38_part4_2026_08_27']::text[], '{}'::text[]);
INSERT INTO ref.rating_code (code, name, body_system, subsection, cfr_section, notes, has_criteria, status, status_note, source_ids, cited_codes) VALUES ('6306', 'Bartonellosis', 'INFECTIOUS DISEASES, IMMUNE DISORDERS AND NUTRITIONAL DEFICIENCIES', NULL, '38 CFR 4.88b', 'Evaluate under the General Rating Formula. Note: Rate under the appropriate body system any residual disability of infection, which includes, but is not limited to, endocarditis or skin lesions.', false, 'SOURCE_CHECKED', NULL, ARRAY['src.ecfr.38_part4_2026_08_27']::text[], '{}'::text[]);
INSERT INTO ref.rating_code (code, name, body_system, subsection, cfr_section, notes, has_criteria, status, status_note, source_ids, cited_codes) VALUES ('6307', 'Plague', 'INFECTIOUS DISEASES, IMMUNE DISORDERS AND NUTRITIONAL DEFICIENCIES', NULL, '38 CFR 4.88b', 'Evaluate under the General Rating Formula. Note: Rate under the appropriate body system any residual disability of infection.', false, 'SOURCE_CHECKED', NULL, ARRAY['src.ecfr.38_part4_2026_08_27']::text[], '{}'::text[]);
INSERT INTO ref.rating_code (code, name, body_system, subsection, cfr_section, notes, has_criteria, status, status_note, source_ids, cited_codes) VALUES ('6308', 'Relapsing fever', 'INFECTIOUS DISEASES, IMMUNE DISORDERS AND NUTRITIONAL DEFICIENCIES', NULL, '38 CFR 4.88b', 'Evaluate under the General Rating Formula. Note: Rate under the appropriate body system any residual disability of infection, which includes, but is not limited to, liver or spleen damage, iritis, uveitis, or central nervous system involvement.', false, 'SOURCE_CHECKED', NULL, ARRAY['src.ecfr.38_part4_2026_08_27']::text[], '{}'::text[]);
INSERT INTO ref.rating_code (code, name, body_system, subsection, cfr_section, notes, has_criteria, status, status_note, source_ids, cited_codes) VALUES ('6309', 'Rheumatic fever', 'INFECTIOUS DISEASES, IMMUNE DISORDERS AND NUTRITIONAL DEFICIENCIES', NULL, '38 CFR 4.88b', 'Evaluate under the General Rating Formula. Note: Rate under the appropriate body system any residual disability of infection, which includes, but is not limited to, heart damage.', false, 'SOURCE_CHECKED', NULL, ARRAY['src.ecfr.38_part4_2026_08_27']::text[], '{}'::text[]);
INSERT INTO ref.rating_code (code, name, body_system, subsection, cfr_section, notes, has_criteria, status, status_note, source_ids, cited_codes) VALUES ('6310', 'Syphilis', 'INFECTIOUS DISEASES, IMMUNE DISORDERS AND NUTRITIONAL DEFICIENCIES', NULL, '38 CFR 4.88b', 'Note: Rate under the appropriate body system any residual disability of infection, which includes, but is not limited to, diseases of the nervous system, vascular system, eyes, or ears (see DC 7004, DC 8013, DC 8014, DC 8015, and DC 9301).', false, 'SOURCE_CHECKED', NULL, ARRAY['src.ecfr.38_part4_2026_08_27']::text[], ARRAY['7004','8013','8014','8015','9301']::text[]);
INSERT INTO ref.rating_code (code, name, body_system, subsection, cfr_section, notes, has_criteria, status, status_note, source_ids, cited_codes) VALUES ('6311', 'Tuberculosis, miliary', 'INFECTIOUS DISEASES, IMMUNE DISORDERS AND NUTRITIONAL DEFICIENCIES', NULL, '38 CFR 4.88b', 'Inactive disease: See §§ 4.88c and 4.89. Note 1: Confirm the recurrence of active infection by culture, histopathology, or other diagnostic laboratory testing. Note 2: Rate under the appropriate body system any residual disability of infection which includes, but is not limited to, skin conditions and conditions of the respiratory, central nervous, musculoskeletal, ocular, gastrointestinal, and genitourinary systems and those residuals listed in § 4.88c.', true, 'SOURCE_CHECKED', NULL, ARRAY['src.ecfr.38_part4_2026_08_27']::text[], '{}'::text[]);
INSERT INTO ref.rating_code (code, name, body_system, subsection, cfr_section, notes, has_criteria, status, status_note, source_ids, cited_codes) VALUES ('6312', 'Nontuberculosis mycobacterium infection', 'INFECTIOUS DISEASES, IMMUNE DISORDERS AND NUTRITIONAL DEFICIENCIES', NULL, '38 CFR 4.88b', 'Note 1: Continue the rating of 100 percent for the duration of treatment for active disease followed by a mandatory VA exam. If there is no relapse, rate on residuals. Any change in evaluation based upon that or any subsequent examination shall be subject to the provisions of § 3.105(e) of this chapter. Note 2: Confirm the recurrence of active infection by culture, histopathology, or other diagnostic laboratory testing. Note 3: Rate under the appropriate body system any residual disability of infection which includes, but is not limited to, skin conditions and conditions of the respiratory, central nervous, musculoskeletal, ocular, gastrointestinal, and genitourinary systems and those residuals listed in § 4.88c.', true, 'SOURCE_CHECKED', NULL, ARRAY['src.ecfr.38_part4_2026_08_27']::text[], '{}'::text[]);
INSERT INTO ref.rating_code (code, name, body_system, subsection, cfr_section, notes, has_criteria, status, status_note, source_ids, cited_codes) VALUES ('6313', 'Avitaminosis', 'INFECTIOUS DISEASES, IMMUNE DISORDERS AND NUTRITIONAL DEFICIENCIES', NULL, '38 CFR 4.88b', NULL, true, 'SOURCE_CHECKED', NULL, ARRAY['src.ecfr.38_part4_2026_08_27']::text[], '{}'::text[]);
INSERT INTO ref.rating_code (code, name, body_system, subsection, cfr_section, notes, has_criteria, status, status_note, source_ids, cited_codes) VALUES ('6314', 'Beriberi', 'INFECTIOUS DISEASES, IMMUNE DISORDERS AND NUTRITIONAL DEFICIENCIES', NULL, '38 CFR 4.88b', 'Thereafter rate residuals under the appropriate body system.', true, 'SOURCE_CHECKED', NULL, ARRAY['src.ecfr.38_part4_2026_08_27']::text[], '{}'::text[]);
INSERT INTO ref.rating_code (code, name, body_system, subsection, cfr_section, notes, has_criteria, status, status_note, source_ids, cited_codes) VALUES ('6315', 'Pellagra', 'INFECTIOUS DISEASES, IMMUNE DISORDERS AND NUTRITIONAL DEFICIENCIES', NULL, '38 CFR 4.88b', NULL, true, 'SOURCE_CHECKED', NULL, ARRAY['src.ecfr.38_part4_2026_08_27']::text[], '{}'::text[]);
INSERT INTO ref.rating_code (code, name, body_system, subsection, cfr_section, notes, has_criteria, status, status_note, source_ids, cited_codes) VALUES ('6316', 'Brucellosis', 'INFECTIOUS DISEASES, IMMUNE DISORDERS AND NUTRITIONAL DEFICIENCIES', NULL, '38 CFR 4.88b', 'Evaluate under the General Rating Formula. Note 1: Culture, serologic testing, or both must confirm the initial diagnosis and recurrence of active infection. Note 2: Rate under the appropriate body system any residual disability of infection, which includes, but is not limited to, meningitis, liver, spleen and musculoskeletal conditions.', false, 'SOURCE_CHECKED', NULL, ARRAY['src.ecfr.38_part4_2026_08_27']::text[], '{}'::text[]);
INSERT INTO ref.rating_code (code, name, body_system, subsection, cfr_section, notes, has_criteria, status, status_note, source_ids, cited_codes) VALUES ('6317', 'Rickettsial, ehrlichia, and anaplasma infections', 'INFECTIOUS DISEASES, IMMUNE DISORDERS AND NUTRITIONAL DEFICIENCIES', NULL, '38 CFR 4.88b', 'Evaluate under the General Rating Formula. Note 1: Rate under the appropriate body system any residual disability of infection, which includes, but is not limited to, bone marrow, spleen, central nervous system, and skin conditions. Note 2: This diagnostic code includes, but is not limited to, scrub typhus, Rickettsial pox, African tick-borne fever, Rocky Mountain spotted fever, ehrlichiosis, or anaplasmosis.', false, 'SOURCE_CHECKED', NULL, ARRAY['src.ecfr.38_part4_2026_08_27']::text[], '{}'::text[]);
INSERT INTO ref.rating_code (code, name, body_system, subsection, cfr_section, notes, has_criteria, status, status_note, source_ids, cited_codes) VALUES ('6318', 'Melioidosis', 'INFECTIOUS DISEASES, IMMUNE DISORDERS AND NUTRITIONAL DEFICIENCIES', NULL, '38 CFR 4.88b', 'Evaluate under the General Rating Formula. Note 1: Confirm by culture or other specific diagnostic laboratory tests the initial diagnosis and any relapse or chronic activity of infection. Note 2: Rate under the appropriate body system any residual disability of infection, which includes, but is not limited to, arthritis, lung lesions, or meningitis.', false, 'SOURCE_CHECKED', NULL, ARRAY['src.ecfr.38_part4_2026_08_27']::text[], '{}'::text[]);
INSERT INTO ref.rating_code (code, name, body_system, subsection, cfr_section, notes, has_criteria, status, status_note, source_ids, cited_codes) VALUES ('6319', 'Lyme disease', 'INFECTIOUS DISEASES, IMMUNE DISORDERS AND NUTRITIONAL DEFICIENCIES', NULL, '38 CFR 4.88b', 'Evaluate under the General Rating Formula. Note: Rate under the appropriate body system any residual disability of infection, which includes, but is not limited to, arthritis, Bell''s palsy, radiculopathy, ocular, or cognitive dysfunction.', false, 'SOURCE_CHECKED', NULL, ARRAY['src.ecfr.38_part4_2026_08_27']::text[], '{}'::text[]);
INSERT INTO ref.rating_code (code, name, body_system, subsection, cfr_section, notes, has_criteria, status, status_note, source_ids, cited_codes) VALUES ('6320', 'Parasitic diseases', 'INFECTIOUS DISEASES, IMMUNE DISORDERS AND NUTRITIONAL DEFICIENCIES', NULL, '38 CFR 4.88b', 'Evaluate under the General Rating Formula. Note: Rate under the appropriate body system any residual disability of infection.', false, 'SOURCE_CHECKED', NULL, ARRAY['src.ecfr.38_part4_2026_08_27']::text[], '{}'::text[]);
INSERT INTO ref.rating_code (code, name, body_system, subsection, cfr_section, notes, has_criteria, status, status_note, source_ids, cited_codes) VALUES ('6325', 'Hyperinfection syndrome or disseminated strongyloidiasis', 'INFECTIOUS DISEASES, IMMUNE DISORDERS AND NUTRITIONAL DEFICIENCIES', NULL, '38 CFR 4.88b', 'Note: Continue the rating of 100 percent through active disease followed by a mandatory VA exam. If there is no relapse, rate on residual disability. Any change in evaluation based upon that or any subsequent examination shall be subject to the provisions of § 3.105(e) of this chapter.', true, 'SOURCE_CHECKED', NULL, ARRAY['src.ecfr.38_part4_2026_08_27']::text[], '{}'::text[]);
INSERT INTO ref.rating_code (code, name, body_system, subsection, cfr_section, notes, has_criteria, status, status_note, source_ids, cited_codes) VALUES ('6326', 'Schistosomiasis', 'INFECTIOUS DISEASES, IMMUNE DISORDERS AND NUTRITIONAL DEFICIENCIES', NULL, '38 CFR 4.88b', 'Note: Rate under the appropriate body system any residual disability of infection, which includes, but is not limited to, conditions of the liver, intestinal system, female genital tract, genitourinary tract, or central nervous system.', true, 'SOURCE_CHECKED', NULL, ARRAY['src.ecfr.38_part4_2026_08_27']::text[], '{}'::text[]);
INSERT INTO ref.rating_code (code, name, body_system, subsection, cfr_section, notes, has_criteria, status, status_note, source_ids, cited_codes) VALUES ('6329', 'Hemorrhagic fevers, including dengue, yellow fever, and others', 'INFECTIOUS DISEASES, IMMUNE DISORDERS AND NUTRITIONAL DEFICIENCIES', NULL, '38 CFR 4.88b', 'Evaluate under the General Rating Formula. Note: Rate under the appropriate body system any residual disability of infection, which includes, but is not limited to, conditions of the central nervous system, liver, or kidney.', false, 'SOURCE_CHECKED', NULL, ARRAY['src.ecfr.38_part4_2026_08_27']::text[], '{}'::text[]);
INSERT INTO ref.rating_code (code, name, body_system, subsection, cfr_section, notes, has_criteria, status, status_note, source_ids, cited_codes) VALUES ('6330', 'Campylobacter jejuni infection', 'INFECTIOUS DISEASES, IMMUNE DISORDERS AND NUTRITIONAL DEFICIENCIES', NULL, '38 CFR 4.88b', 'Evaluate under the General Rating Formula. Note: Rate under the appropriate body system any residual disability of infection, which includes, but is not limited to, Guillain-Barre syndrome, reactive arthritis, or uveitis.', false, 'SOURCE_CHECKED', NULL, ARRAY['src.ecfr.38_part4_2026_08_27']::text[], '{}'::text[]);
INSERT INTO ref.rating_code (code, name, body_system, subsection, cfr_section, notes, has_criteria, status, status_note, source_ids, cited_codes) VALUES ('6331', 'Coxiella burnetii infection (Q Fever)', 'INFECTIOUS DISEASES, IMMUNE DISORDERS AND NUTRITIONAL DEFICIENCIES', NULL, '38 CFR 4.88b', 'Evaluate under the General Rating Formula. Note: Rate under the appropriate body system any residual disability of infection, which includes, but is not limited to, chronic hepatitis, endocarditis, osteomyelitis, post Q-fever chronic fatigue syndrome, or vascular infections.', false, 'SOURCE_CHECKED', NULL, ARRAY['src.ecfr.38_part4_2026_08_27']::text[], '{}'::text[]);
INSERT INTO ref.rating_code (code, name, body_system, subsection, cfr_section, notes, has_criteria, status, status_note, source_ids, cited_codes) VALUES ('6333', 'Nontyphoid salmonella infections', 'INFECTIOUS DISEASES, IMMUNE DISORDERS AND NUTRITIONAL DEFICIENCIES', NULL, '38 CFR 4.88b', 'Evaluate under the General Rating Formula. Note: Rate under the appropriate body system any residual disability of infection, which includes, but is not limited to, reactive arthritis.', false, 'SOURCE_CHECKED', NULL, ARRAY['src.ecfr.38_part4_2026_08_27']::text[], '{}'::text[]);
INSERT INTO ref.rating_code (code, name, body_system, subsection, cfr_section, notes, has_criteria, status, status_note, source_ids, cited_codes) VALUES ('6334', 'Shigella infections', 'INFECTIOUS DISEASES, IMMUNE DISORDERS AND NUTRITIONAL DEFICIENCIES', NULL, '38 CFR 4.88b', 'Evaluate under the General Rating Formula. Note: Rate under the appropriate body system any residual disability of infection, which includes, but is not limited to, hemolytic-uremic syndrome or reactive arthritis.', false, 'SOURCE_CHECKED', NULL, ARRAY['src.ecfr.38_part4_2026_08_27']::text[], '{}'::text[]);
INSERT INTO ref.rating_code (code, name, body_system, subsection, cfr_section, notes, has_criteria, status, status_note, source_ids, cited_codes) VALUES ('6335', 'West Nile virus infection', 'INFECTIOUS DISEASES, IMMUNE DISORDERS AND NUTRITIONAL DEFICIENCIES', NULL, '38 CFR 4.88b', 'Evaluate under the General Rating Formula. Note: Rate under the appropriate body system any residual disability of infection, which includes, but is not limited to, variable physical, functional, or cognitive disabilities.', false, 'SOURCE_CHECKED', NULL, ARRAY['src.ecfr.38_part4_2026_08_27']::text[], '{}'::text[]);
INSERT INTO ref.rating_code (code, name, body_system, subsection, cfr_section, notes, has_criteria, status, status_note, source_ids, cited_codes) VALUES ('6350', 'Lupus erythematosus', 'INFECTIOUS DISEASES, IMMUNE DISORDERS AND NUTRITIONAL DEFICIENCIES', NULL, '38 CFR 4.88b', 'Note: Evaluate this condition either by combining the evaluations for residuals under the appropriate system, or by evaluating DC 6350, whichever method results in a higher evaluation.', true, 'SOURCE_CHECKED', NULL, ARRAY['src.ecfr.38_part4_2026_08_27']::text[], '{}'::text[]);
INSERT INTO ref.rating_code (code, name, body_system, subsection, cfr_section, notes, has_criteria, status, status_note, source_ids, cited_codes) VALUES ('6351', 'HIV-Related Illness', 'INFECTIOUS DISEASES, IMMUNE DISORDERS AND NUTRITIONAL DEFICIENCIES', NULL, '38 CFR 4.88b', 'Note 1: In addition to standard therapies and regimens, the term “approved medication(s)” includes treatment regimens and medications prescribed as part of a research protocol at an accredited medical institution. Note 2: Diagnosed psychiatric illness, central nervous system manifestations, opportunistic infections, and neoplasms may be rated separately under the appropriate diagnostic codes if a higher overall evaluation results, provided the disability symptoms do not overlap with evaluations otherwise assignable above. Note 3: The following list of opportunistic infections are considered AIDS-defining conditions, that is, a diagnosis of AIDS follows if a person has HIV and one more of these infections, regardless of the CD4 count—candidiasis of the bronchi, trachea, esophagus, or lungs; invasive cervical cancer; coccidioidomycosis; cryptococcosis; cryptosporidiosis; cytomegalovirus (particularly CMV retinitis); HIV-related encephalopathy; herpes simplex-chronic ulcers for greater than one month, or bronchitis, pneumonia, or esophagitis; histoplasmosis; isosporiasis (chronic intestinal); Kaposi''s sarcoma; lymphoma; mycobacterium avium complex; tuberculosis; pneumocystis jirovecii (carinii) pneumonia; pneumonia, recurrent; progressive multifocal leukoencephalopathy; salmonella septicemia, recurrent; toxoplasmosis of the brain; and wasting syndrome due to HIV.', true, 'SOURCE_CHECKED', NULL, ARRAY['src.ecfr.38_part4_2026_08_27']::text[], '{}'::text[]);
INSERT INTO ref.rating_code (code, name, body_system, subsection, cfr_section, notes, has_criteria, status, status_note, source_ids, cited_codes) VALUES ('6354', 'Chronic Fatigue Syndrome (CFS)', 'INFECTIOUS DISEASES, IMMUNE DISORDERS AND NUTRITIONAL DEFICIENCIES', NULL, '38 CFR 4.88b', 'Note: For the purpose of evaluating this disability, incapacitation exists only when a licensed physician prescribes bed rest and treatment.', true, 'SOURCE_CHECKED', NULL, ARRAY['src.ecfr.38_part4_2026_08_27']::text[], '{}'::text[]);
INSERT INTO ref.rating_code (code, name, body_system, subsection, cfr_section, notes, has_criteria, status, status_note, source_ids, cited_codes) VALUES ('6502', 'Septum, nasal, deviation', 'THE RESPIRATORY SYSTEM', 'Nose and Throat', '38 CFR 4.97', NULL, true, 'SOURCE_CHECKED', NULL, ARRAY['src.ecfr.38_part4_2026_08_27']::text[], '{}'::text[]);
INSERT INTO ref.rating_code (code, name, body_system, subsection, cfr_section, notes, has_criteria, status, status_note, source_ids, cited_codes) VALUES ('6504', 'Nose, loss of part of, or scars', 'THE RESPIRATORY SYSTEM', 'Nose and Throat', '38 CFR 4.97', 'Note: Or evaluate as DC 7800, scars, disfiguring, head, face, or neck.', true, 'SOURCE_CHECKED', NULL, ARRAY['src.ecfr.38_part4_2026_08_27']::text[], ARRAY['7800']::text[]);
