INSERT INTO ref.rating_code (code, name, body_system, subsection, cfr_section, notes, has_criteria, status, status_note, source_ids, cited_codes) VALUES ('6513', 'Sinusitis, maxillary, chronic', 'THE RESPIRATORY SYSTEM', 'Nose and Throat', '38 CFR 4.97', NULL, false, 'SOURCE_CHECKED', NULL, ARRAY['src.ecfr.38_part4_2026_08_27']::text[], '{}'::text[]);
INSERT INTO ref.rating_code (code, name, body_system, subsection, cfr_section, notes, has_criteria, status, status_note, source_ids, cited_codes) VALUES ('6514', 'Sinusitis, sphenoid, chronic', 'THE RESPIRATORY SYSTEM', 'Nose and Throat', '38 CFR 4.97', NULL, false, 'SOURCE_CHECKED', NULL, ARRAY['src.ecfr.38_part4_2026_08_27']::text[], '{}'::text[]);
INSERT INTO ref.rating_code (code, name, body_system, subsection, cfr_section, notes, has_criteria, status, status_note, source_ids, cited_codes) VALUES ('6515', 'Laryngitis, tuberculous', 'THE RESPIRATORY SYSTEM', 'Nose and Throat', '38 CFR 4.97', 'Rate under §§ 4.88c or 4.89, whichever is appropriate.', false, 'SOURCE_CHECKED', NULL, ARRAY['src.ecfr.38_part4_2026_08_27']::text[], '{}'::text[]);
INSERT INTO ref.rating_code (code, name, body_system, subsection, cfr_section, notes, has_criteria, status, status_note, source_ids, cited_codes) VALUES ('6516', 'Laryngitis, chronic', 'THE RESPIRATORY SYSTEM', 'Nose and Throat', '38 CFR 4.97', NULL, true, 'SOURCE_CHECKED', NULL, ARRAY['src.ecfr.38_part4_2026_08_27']::text[], '{}'::text[]);
INSERT INTO ref.rating_code (code, name, body_system, subsection, cfr_section, notes, has_criteria, status, status_note, source_ids, cited_codes) VALUES ('6518', 'Laryngectomy, total', 'THE RESPIRATORY SYSTEM', 'Nose and Throat', '38 CFR 4.97', 'Rate the residuals of partial laryngectomy as laryngitis (DC 6516), aphonia (DC 6519), or stenosis of larynx (DC 6520).', true, 'SOURCE_CHECKED', NULL, ARRAY['src.ecfr.38_part4_2026_08_27']::text[], ARRAY['6516','6519','6520']::text[]);
INSERT INTO ref.rating_code (code, name, body_system, subsection, cfr_section, notes, has_criteria, status, status_note, source_ids, cited_codes) VALUES ('6519', 'Aphonia, complete organic', 'THE RESPIRATORY SYSTEM', 'Nose and Throat', '38 CFR 4.97', 'Note: Evaluate incomplete aphonia as laryngitis, chronic (DC 6516).', true, 'SOURCE_CHECKED', NULL, ARRAY['src.ecfr.38_part4_2026_08_27']::text[], ARRAY['6516']::text[]);
INSERT INTO ref.rating_code (code, name, body_system, subsection, cfr_section, notes, has_criteria, status, status_note, source_ids, cited_codes) VALUES ('6520', 'Larynx, stenosis of', 'THE RESPIRATORY SYSTEM', 'Nose and Throat', '38 CFR 4.97', 'Note: Or evaluate as aphonia (DC 6519).', true, 'SOURCE_CHECKED', NULL, ARRAY['src.ecfr.38_part4_2026_08_27']::text[], ARRAY['6519']::text[]);
INSERT INTO ref.rating_code (code, name, body_system, subsection, cfr_section, notes, has_criteria, status, status_note, source_ids, cited_codes) VALUES ('6521', 'Pharynx, injuries to', 'THE RESPIRATORY SYSTEM', 'Nose and Throat', '38 CFR 4.97', NULL, true, 'SOURCE_CHECKED', NULL, ARRAY['src.ecfr.38_part4_2026_08_27']::text[], '{}'::text[]);
INSERT INTO ref.rating_code (code, name, body_system, subsection, cfr_section, notes, has_criteria, status, status_note, source_ids, cited_codes) VALUES ('6522', 'Allergic or vasomotor rhinitis', 'THE RESPIRATORY SYSTEM', 'Nose and Throat', '38 CFR 4.97', NULL, true, 'SOURCE_CHECKED', NULL, ARRAY['src.ecfr.38_part4_2026_08_27']::text[], '{}'::text[]);
