INSERT INTO ref.rating_code (code, name, body_system, subsection, cfr_section, notes, has_criteria, status, status_note, source_ids, cited_codes) VALUES ('6524', 'Granulomatous rhinitis', 'THE RESPIRATORY SYSTEM', 'Nose and Throat', '38 CFR 4.97', NULL, true, 'SOURCE_CHECKED', NULL, ARRAY['src.ecfr.38_part4_2026_08_27']::text[], '{}'::text[]);
INSERT INTO ref.rating_code (code, name, body_system, subsection, cfr_section, notes, has_criteria, status, status_note, source_ids, cited_codes) VALUES ('6600', 'Bronchitis, chronic', 'THE RESPIRATORY SYSTEM', 'Trachea and Bronchi', '38 CFR 4.97', NULL, true, 'SOURCE_CHECKED', NULL, ARRAY['src.ecfr.38_part4_2026_08_27']::text[], '{}'::text[]);
INSERT INTO ref.rating_code (code, name, body_system, subsection, cfr_section, notes, has_criteria, status, status_note, source_ids, cited_codes) VALUES ('6601', 'Bronchiectasis', 'THE RESPIRATORY SYSTEM', 'Trachea and Bronchi', '38 CFR 4.97', 'Or rate according to pulmonary impairment as for chronic bronchitis (DC 6600). Note: An incapacitating episode is one that requires bedrest and treatment by a physician.', true, 'SOURCE_CHECKED', NULL, ARRAY['src.ecfr.38_part4_2026_08_27']::text[], ARRAY['6600']::text[]);
INSERT INTO ref.rating_code (code, name, body_system, subsection, cfr_section, notes, has_criteria, status, status_note, source_ids, cited_codes) VALUES ('6602', 'Asthma, bronchial', 'THE RESPIRATORY SYSTEM', 'Trachea and Bronchi', '38 CFR 4.97', 'Note: In the absence of clinical findings of asthma at time of examination, a verified history of asthmatic attacks must be of record.', true, 'SOURCE_CHECKED', NULL, ARRAY['src.ecfr.38_part4_2026_08_27']::text[], '{}'::text[]);
INSERT INTO ref.rating_code (code, name, body_system, subsection, cfr_section, notes, has_criteria, status, status_note, source_ids, cited_codes) VALUES ('6603', 'Emphysema, pulmonary', 'THE RESPIRATORY SYSTEM', 'Trachea and Bronchi', '38 CFR 4.97', NULL, true, 'SOURCE_CHECKED', NULL, ARRAY['src.ecfr.38_part4_2026_08_27']::text[], '{}'::text[]);
INSERT INTO ref.rating_code (code, name, body_system, subsection, cfr_section, notes, has_criteria, status, status_note, source_ids, cited_codes) VALUES ('6604', 'Chronic obstructive pulmonary disease', 'THE RESPIRATORY SYSTEM', 'Trachea and Bronchi', '38 CFR 4.97', NULL, true, 'SOURCE_CHECKED', NULL, ARRAY['src.ecfr.38_part4_2026_08_27']::text[], '{}'::text[]);
