INSERT INTO ref.rating_code (code, name, body_system, subsection, cfr_section, notes, has_criteria, status, status_note, source_ids, cited_codes) VALUES ('6704', 'Ratings for Pulmonary Tuberculosis (Chronic) Entitled on August 19, 1968: Active, advancement unspecified', 'THE RESPIRATORY SYSTEM', 'Lungs and Pleura Tuberculosis', '38 CFR 4.97', NULL, true, 'SOURCE_CHECKED', NULL, ARRAY['src.ecfr.38_part4_2026_08_27']::text[], '{}'::text[]);
INSERT INTO ref.rating_code (code, name, body_system, subsection, cfr_section, notes, has_criteria, status, status_note, source_ids, cited_codes) VALUES ('6721', 'Ratings for Pulmonary Tuberculosis (Chronic) Entitled on August 19, 1968: Inactive, far advanced', 'THE RESPIRATORY SYSTEM', 'Lungs and Pleura Tuberculosis', '38 CFR 4.97', NULL, false, 'SOURCE_CHECKED', NULL, ARRAY['src.ecfr.38_part4_2026_08_27']::text[], '{}'::text[]);
