INSERT INTO ref.rating_code (code, name, body_system, subsection, cfr_section, notes, has_criteria, status, status_note, source_ids, cited_codes) VALUES ('6723', 'Ratings for Pulmonary Tuberculosis (Chronic) Entitled on August 19, 1968: Inactive, minimal', 'THE RESPIRATORY SYSTEM', 'Lungs and Pleura Tuberculosis', '38 CFR 4.97', NULL, false, 'SOURCE_CHECKED', NULL, ARRAY['src.ecfr.38_part4_2026_08_27']::text[], '{}'::text[]);
INSERT INTO ref.rating_code (code, name, body_system, subsection, cfr_section, notes, has_criteria, status, status_note, source_ids, cited_codes) VALUES ('6724', 'Ratings for Pulmonary Tuberculosis (Chronic) Entitled on August 19, 1968: Inactive, advancement unspecified', 'THE RESPIRATORY SYSTEM', 'Lungs and Pleura Tuberculosis', '38 CFR 4.97', NULL, false, 'SOURCE_CHECKED', NULL, ARRAY['src.ecfr.38_part4_2026_08_27']::text[], '{}'::text[]);
INSERT INTO ref.rating_code (code, name, body_system, subsection, cfr_section, notes, has_criteria, status, status_note, source_ids, cited_codes) VALUES ('6730', 'Ratings for Pulmonary Tuberculosis Initially Evaluated After August 19, 1968: Chronic, active', 'THE RESPIRATORY SYSTEM', 'Lungs and Pleura Tuberculosis', '38 CFR 4.97', 'Note: Active pulmonary tuberculosis will be considered permanently and totally disabling for non-service-connected pension purposes in the following circumstances:', true, 'SOURCE_CHECKED', NULL, ARRAY['src.ecfr.38_part4_2026_08_27']::text[], '{}'::text[]);
INSERT INTO ref.rating_code (code, name, body_system, subsection, cfr_section, notes, has_criteria, status, status_note, source_ids, cited_codes) VALUES ('6731', 'Ratings for Pulmonary Tuberculosis Initially Evaluated After August 19, 1968: Chronic, inactive', 'THE RESPIRATORY SYSTEM', 'Lungs and Pleura Tuberculosis', '38 CFR 4.97', 'Depending on the specific findings, rate residuals as interstitial lung disease, restrictive lung disease, or, when obstructive lung disease is the major residual, as chronic bronchitis (DC 6600). Rate thoracoplasty as removal of ribs under DC 5297. Note: A mandatory examination will be requested immediately following notification that active tuberculosis evaluated under DC 6730 has become inactive. Any change in evaluation will be carried out under the provisions of § 3.105(e).', false, 'SOURCE_CHECKED', NULL, ARRAY['src.ecfr.38_part4_2026_08_27']::text[], ARRAY['5297','6600','6730']::text[]);
INSERT INTO ref.rating_code (code, name, body_system, subsection, cfr_section, notes, has_criteria, status, status_note, source_ids, cited_codes) VALUES ('6732', 'Ratings for Pulmonary Tuberculosis Initially Evaluated After August 19, 1968: Pleurisy, active or inactive', 'THE RESPIRATORY SYSTEM', 'Lungs and Pleura Tuberculosis', '38 CFR 4.97', 'Rate under §§ 4.88c or 4.89, whichever is appropriate.', false, 'SOURCE_CHECKED', NULL, ARRAY['src.ecfr.38_part4_2026_08_27']::text[], '{}'::text[]);
INSERT INTO ref.rating_code (code, name, body_system, subsection, cfr_section, notes, has_criteria, status, status_note, source_ids, cited_codes) VALUES ('6817', 'Pulmonary Vascular Disease', 'THE RESPIRATORY SYSTEM', 'Nontuberculous Diseases', '38 CFR 4.97', 'Note: Evaluate other residuals following pulmonary embolism under the most appropriate diagnostic code, such as chronic bronchitis (DC 6600) or chronic pleural effusion or fibrosis (DC 6844), but do not combine that evaluation with any of the above evaluations.', true, 'SOURCE_CHECKED', NULL, ARRAY['src.ecfr.38_part4_2026_08_27']::text[], ARRAY['6600','6844']::text[]);
INSERT INTO ref.rating_code (code, name, body_system, subsection, cfr_section, notes, has_criteria, status, status_note, source_ids, cited_codes) VALUES ('6819', 'Neoplasms, malignant', 'THE RESPIRATORY SYSTEM', 'Nontuberculous Diseases', '38 CFR 4.97', 'Note: A rating of 100 percent shall continue beyond the cessation of any surgical, X-ray, antineoplastic chemotherapy or other therapeutic procedure. Six months after discontinuance of such treatment, the appropriate disability rating shall be determined by mandatory VA examination. Any change in evaluation based upon that or any subsequent examination shall be subject to the provisions of § 3.105(e) of this chapter. If there has been no local recurrence or metastasis, rate on residuals.', true, 'SOURCE_CHECKED', NULL, ARRAY['src.ecfr.38_part4_2026_08_27']::text[], '{}'::text[]);
INSERT INTO ref.rating_code (code, name, body_system, subsection, cfr_section, notes, has_criteria, status, status_note, source_ids, cited_codes) VALUES ('6820', 'Neoplasms, benign', 'THE RESPIRATORY SYSTEM', 'Nontuberculous Diseases', '38 CFR 4.97', 'Evaluate using an appropriate respiratory analogy.', false, 'SOURCE_CHECKED', NULL, ARRAY['src.ecfr.38_part4_2026_08_27']::text[], '{}'::text[]);
