INSERT INTO ref.rating_code (code, name, body_system, subsection, cfr_section, notes, has_criteria, status, status_note, source_ids, cited_codes) VALUES ('6845', 'Pleural effusion or fibrosis', 'THE RESPIRATORY SYSTEM', 'Restrictive Lung Disease', '38 CFR 4.97', NULL, false, 'SOURCE_CHECKED', NULL, ARRAY['src.ecfr.38_part4_2026_08_27']::text[], '{}'::text[]);
INSERT INTO ref.rating_code (code, name, body_system, subsection, cfr_section, notes, has_criteria, status, status_note, source_ids, cited_codes) VALUES ('6846', 'Sarcoidosis', 'THE RESPIRATORY SYSTEM', 'Restrictive Lung Disease', '38 CFR 4.97', 'Or rate active disease or residuals as chronic bronchitis (DC 6600) and extra-pulmonary involvement under specific body system involved', true, 'SOURCE_CHECKED', NULL, ARRAY['src.ecfr.38_part4_2026_08_27']::text[], ARRAY['6600']::text[]);
INSERT INTO ref.rating_code (code, name, body_system, subsection, cfr_section, notes, has_criteria, status, status_note, source_ids, cited_codes) VALUES ('6847', 'Sleep Apnea Syndromes', 'THE RESPIRATORY SYSTEM', 'Restrictive Lung Disease', '38 CFR 4.97', NULL, true, 'SOURCE_CHECKED', NULL, ARRAY['src.ecfr.38_part4_2026_08_27']::text[], '{}'::text[]);
INSERT INTO ref.rating_code (code, name, body_system, subsection, cfr_section, notes, has_criteria, status, status_note, source_ids, cited_codes) VALUES ('7000', 'Valvular heart disease', 'THE CARDIOVASCULAR SYSTEM', 'Diseases of the Heart', '38 CFR 4.104', 'Thereafter, with diagnosis confirmed by findings on physical examination and either echocardiogram, Doppler echocardiogram, or cardiac catheterization, use the General Rating Formula.', true, 'SOURCE_CHECKED', 'The regulation prints this code with diagnostic code 7002; they share its rating rows.', ARRAY['src.ecfr.38_part4_2026_08_27']::text[], '{}'::text[]);
INSERT INTO ref.rating_code (code, name, body_system, subsection, cfr_section, notes, has_criteria, status, status_note, source_ids, cited_codes) VALUES ('7001', 'Endocarditis', 'THE CARDIOVASCULAR SYSTEM', 'Diseases of the Heart', '38 CFR 4.104', 'Thereafter, with diagnosis confirmed by findings on physical examination and either echocardiogram, Doppler echocardiogram, or cardiac catheterization, use the General Rating Formula.', true, 'SOURCE_CHECKED', 'The regulation prints this code with diagnostic code 7002; they share its rating rows.', ARRAY['src.ecfr.38_part4_2026_08_27']::text[], '{}'::text[]);
INSERT INTO ref.rating_code (code, name, body_system, subsection, cfr_section, notes, has_criteria, status, status_note, source_ids, cited_codes) VALUES ('7002', 'Pericarditis', 'THE CARDIOVASCULAR SYSTEM', 'Diseases of the Heart', '38 CFR 4.104', 'Thereafter, with diagnosis confirmed by findings on physical examination and either echocardiogram, Doppler echocardiogram, or cardiac catheterization, use the General Rating Formula.', true, 'SOURCE_CHECKED', NULL, ARRAY['src.ecfr.38_part4_2026_08_27']::text[], '{}'::text[]);
INSERT INTO ref.rating_code (code, name, body_system, subsection, cfr_section, notes, has_criteria, status, status_note, source_ids, cited_codes) VALUES ('7003', 'Pericardial adhesions', 'THE CARDIOVASCULAR SYSTEM', 'Diseases of the Heart', '38 CFR 4.104', NULL, false, 'SOURCE_CHECKED', NULL, ARRAY['src.ecfr.38_part4_2026_08_27']::text[], '{}'::text[]);
INSERT INTO ref.rating_code (code, name, body_system, subsection, cfr_section, notes, has_criteria, status, status_note, source_ids, cited_codes) VALUES ('7004', 'Syphilitic heart disease', 'THE CARDIOVASCULAR SYSTEM', 'Diseases of the Heart', '38 CFR 4.104', 'Note: Evaluate syphilitic aortic aneurysms under DC 7110 (Aortic aneurysm: Ascending, thoracic, abdominal).', false, 'SOURCE_CHECKED', NULL, ARRAY['src.ecfr.38_part4_2026_08_27']::text[], ARRAY['7110']::text[]);
INSERT INTO ref.rating_code (code, name, body_system, subsection, cfr_section, notes, has_criteria, status, status_note, source_ids, cited_codes) VALUES ('7005', 'Arteriosclerotic heart disease', 'THE CARDIOVASCULAR SYSTEM', 'Diseases of the Heart', '38 CFR 4.104', 'Note: If non-service-connected arteriosclerotic heart disease is superimposed on service-connected valvular or other non-arteriosclerotic heart disease, request a medical opinion as to which condition is causing the current signs and symptoms.', false, 'SOURCE_CHECKED', NULL, ARRAY['src.ecfr.38_part4_2026_08_27']::text[], '{}'::text[]);
INSERT INTO ref.rating_code (code, name, body_system, subsection, cfr_section, notes, has_criteria, status, status_note, source_ids, cited_codes) VALUES ('7006', 'Myocardial infarction', 'THE CARDIOVASCULAR SYSTEM', 'Diseases of the Heart', '38 CFR 4.104', 'Thereafter, use the General Rating Formula.', true, 'SOURCE_CHECKED', NULL, ARRAY['src.ecfr.38_part4_2026_08_27']::text[], '{}'::text[]);
INSERT INTO ref.rating_code (code, name, body_system, subsection, cfr_section, notes, has_criteria, status, status_note, source_ids, cited_codes) VALUES ('7007', 'Hypertensive heart disease', 'THE CARDIOVASCULAR SYSTEM', 'Diseases of the Heart', '38 CFR 4.104', NULL, false, 'SOURCE_CHECKED', NULL, ARRAY['src.ecfr.38_part4_2026_08_27']::text[], '{}'::text[]);
INSERT INTO ref.rating_code (code, name, body_system, subsection, cfr_section, notes, has_criteria, status, status_note, source_ids, cited_codes) VALUES ('7008', 'Hyperthyroid heart disease', 'THE CARDIOVASCULAR SYSTEM', 'Diseases of the Heart', '38 CFR 4.104', 'Rate under the appropriate cardiovascular diagnostic code, depending on particular findings. For DCs 7009, 7010, 7011, and 7015, a single evaluation will be assigned under the diagnostic code that reflects the predominant disability picture.', false, 'SOURCE_CHECKED', NULL, ARRAY['src.ecfr.38_part4_2026_08_27']::text[], ARRAY['7009','7010','7011','7015']::text[]);
INSERT INTO ref.rating_code (code, name, body_system, subsection, cfr_section, notes, has_criteria, status, status_note, source_ids, cited_codes) VALUES ('7009', 'Bradycardia (Bradyarrhythmia), symptomatic, requiring permanent pacemaker implantation', 'THE CARDIOVASCULAR SYSTEM', 'Diseases of the Heart', '38 CFR 4.104', 'Thereafter, use the General Rating Formula. Note (1): Bradycardia (bradyarrhythmia) refers to conduction abnormalities that produce a heart rate less than 60 beats/min. There are five general classes of bradyarrhythmia: Sinus bradycardia, including sinoatrial block; atrioventricular (AV) junctional (nodal) escape rhythm; AV heart block (second or third degree) or AV dissociation; atrial fibrillation or flutter with a slow ventricular response; and, idioventricular escape rhythm. Note (2): Asymptomatic bradycardia (bradyarrhythmia) is a medical finding only. It is not a disability subject to compensation.', true, 'SOURCE_CHECKED', NULL, ARRAY['src.ecfr.38_part4_2026_08_27']::text[], '{}'::text[]);
INSERT INTO ref.rating_code (code, name, body_system, subsection, cfr_section, notes, has_criteria, status, status_note, source_ids, cited_codes) VALUES ('7010', 'Supraventricular tachycardia', 'THE CARDIOVASCULAR SYSTEM', 'Diseases of the Heart', '38 CFR 4.104', 'Note (1): Examples of supraventricular tachycardia include, but are not limited to: Atrial fibrillation, atrial flutter, sinus tachycardia, sinoatrial nodal reentrant tachycardia, atrioventricular nodal reentrant tachycardia, atrioventricular reentrant tachycardia, atrial tachycardia, junctional tachycardia, and multifocal atrial tachycardia. Note (2): For the purposes of this diagnostic code, a treatment intervention occurs whenever a symptomatic patient requires intravenous pharmacologic adjustment, cardioversion, and/or ablation for symptom relief.', true, 'SOURCE_CHECKED', NULL, ARRAY['src.ecfr.38_part4_2026_08_27']::text[], '{}'::text[]);
INSERT INTO ref.rating_code (code, name, body_system, subsection, cfr_section, notes, has_criteria, status, status_note, source_ids, cited_codes) VALUES ('7011', 'Ventricular arrhythmias', 'THE CARDIOVASCULAR SYSTEM', 'Diseases of the Heart', '38 CFR 4.104', 'Note: When inpatient hospitalization for sustained ventricular arrhythmia or ventricular aneurysmectomy is required, a 100-percent evaluation begins on the date of hospital admission with a mandatory VA examination six months following hospital discharge. Evaluate post-surgical residuals under the General Rating Formula. Apply the provisions of § 3.105(e) of this chapter to any change in evaluation based upon that or any subsequent examination.', true, 'SOURCE_CHECKED', NULL, ARRAY['src.ecfr.38_part4_2026_08_27']::text[], '{}'::text[]);
INSERT INTO ref.rating_code (code, name, body_system, subsection, cfr_section, notes, has_criteria, status, status_note, source_ids, cited_codes) VALUES ('7015', 'Atrioventricular block', 'THE CARDIOVASCULAR SYSTEM', 'Diseases of the Heart', '38 CFR 4.104', 'Benign (First-Degree and Second-Degree, Type I): Evaluate under the General Rating Formula. Non-Benign (Second-Degree, Type II and Third-Degree): Evaluate under DC 7018 (implantable cardiac pacemakers).', false, 'SOURCE_CHECKED', NULL, ARRAY['src.ecfr.38_part4_2026_08_27']::text[], ARRAY['7018']::text[]);
INSERT INTO ref.rating_code (code, name, body_system, subsection, cfr_section, notes, has_criteria, status, status_note, source_ids, cited_codes) VALUES ('7016', 'Heart valve replacement', 'THE CARDIOVASCULAR SYSTEM', 'Diseases of the Heart', '38 CFR 4.104', 'Thereafter, use the General Rating Formula. Note: Six months following discharge from inpatient hospitalization, disability evaluation shall be conducted by mandatory VA examination using the General Rating Formula. Apply the provisions of § 3.105(e) of this chapter to any change in evaluation based upon that or any subsequent examination.', true, 'SOURCE_CHECKED', NULL, ARRAY['src.ecfr.38_part4_2026_08_27']::text[], '{}'::text[]);
INSERT INTO ref.rating_code (code, name, body_system, subsection, cfr_section, notes, has_criteria, status, status_note, source_ids, cited_codes) VALUES ('7017', 'Coronary bypass surgery', 'THE CARDIOVASCULAR SYSTEM', 'Diseases of the Heart', '38 CFR 4.104', 'Thereafter, use the General Rating Formula.', true, 'SOURCE_CHECKED', NULL, ARRAY['src.ecfr.38_part4_2026_08_27']::text[], '{}'::text[]);
INSERT INTO ref.rating_code (code, name, body_system, subsection, cfr_section, notes, has_criteria, status, status_note, source_ids, cited_codes) VALUES ('7018', 'Implantable cardiac pacemakers', 'THE CARDIOVASCULAR SYSTEM', 'Diseases of the Heart', '38 CFR 4.104', 'Evaluate as supraventricular tachycardia (DC 7010), ventricular arrhythmias (DC 7011), or atrioventricular block (DC 7015). Note: Evaluate automatic implantable cardioverter-defibrillators (AICDs) under DC 7011.', true, 'SOURCE_CHECKED', NULL, ARRAY['src.ecfr.38_part4_2026_08_27']::text[], ARRAY['7010','7011','7015']::text[]);
INSERT INTO ref.rating_code (code, name, body_system, subsection, cfr_section, notes, has_criteria, status, status_note, source_ids, cited_codes) VALUES ('7019', 'Cardiac transplantation', 'THE CARDIOVASCULAR SYSTEM', 'Diseases of the Heart', '38 CFR 4.104', 'Evaluate under the General Rating Formula. Note: One year following discharge from inpatient hospitalization, determine the appropriate disability rating by mandatory VA examination. Apply the provisions of § 3.105(e) of this chapter to any change in evaluation based upon that or any subsequent examination.', true, 'SOURCE_CHECKED', NULL, ARRAY['src.ecfr.38_part4_2026_08_27']::text[], '{}'::text[]);
INSERT INTO ref.rating_code (code, name, body_system, subsection, cfr_section, notes, has_criteria, status, status_note, source_ids, cited_codes) VALUES ('7020', 'Cardiomyopathy', 'THE CARDIOVASCULAR SYSTEM', 'Diseases of the Heart', '38 CFR 4.104', NULL, false, 'SOURCE_CHECKED', NULL, ARRAY['src.ecfr.38_part4_2026_08_27']::text[], '{}'::text[]);
INSERT INTO ref.rating_code (code, name, body_system, subsection, cfr_section, notes, has_criteria, status, status_note, source_ids, cited_codes) VALUES ('7101', 'Hypertensive vascular disease', 'THE CARDIOVASCULAR SYSTEM', 'Diseases of the Arteries and Veins', '38 CFR 4.104', 'Note (1): Hypertension or isolated systolic hypertension must be confirmed by readings taken two or more times on at least three different days. For purposes of this section, the term hypertension means that the diastolic blood pressure is predominantly 90mm. or greater, and isolated systolic hypertension means that the systolic blood pressure is predominantly 160mm. or greater with a diastolic blood pressure of less than 90mm. Note (2): Evaluate hypertension due to aortic insufficiency or hyperthyroidism, which is usually the isolated systolic type, as part of the condition causing it rather than by a separate evaluation. Note (3): Evaluate hypertension separately from hypertensive heart disease and other types of heart disease.', true, 'SOURCE_CHECKED', NULL, ARRAY['src.ecfr.38_part4_2026_08_27']::text[], '{}'::text[]);
INSERT INTO ref.rating_code (code, name, body_system, subsection, cfr_section, notes, has_criteria, status, status_note, source_ids, cited_codes) VALUES ('7110', 'Aortic aneurysm: ascending, thoracic, abdominal', 'THE CARDIOVASCULAR SYSTEM', 'Diseases of the Arteries and Veins', '38 CFR 4.104', 'Evaluate non-cardiovascular residuals of surgical correction according to organ systems affected. Note: When surgery is required, a 100-percent evaluation begins on the date a physician recommends surgical correction with a mandatory VA examination six months following hospital discharge. Evaluate post-surgical residuals under the General Rating Formula. Any change in evaluation based upon that or any subsequent examination shall be subject to the provisions of § 3.105(e) of this chapter.', true, 'SOURCE_CHECKED', NULL, ARRAY['src.ecfr.38_part4_2026_08_27']::text[], '{}'::text[]);
INSERT INTO ref.rating_code (code, name, body_system, subsection, cfr_section, notes, has_criteria, status, status_note, source_ids, cited_codes) VALUES ('7111', 'Aneurysm, large artery', 'THE CARDIOVASCULAR SYSTEM', 'Diseases of the Arteries and Veins', '38 CFR 4.104', 'Following surgery: Evaluate under DC 7114 (peripheral arterial disease). Note: Six months following discharge from inpatient hospitalization for surgery, determine the appropriate disability rating by mandatory VA examination. Any change in evaluation based upon that or any subsequent examination shall be subject to the provisions of § 3.105(e) of this chapter.', true, 'SOURCE_CHECKED', NULL, ARRAY['src.ecfr.38_part4_2026_08_27']::text[], ARRAY['7114']::text[]);
INSERT INTO ref.rating_code (code, name, body_system, subsection, cfr_section, notes, has_criteria, status, status_note, source_ids, cited_codes) VALUES ('7112', 'Aneurysm, small artery', 'THE CARDIOVASCULAR SYSTEM', 'Diseases of the Arteries and Veins', '38 CFR 4.104', 'Note: If symptomatic, evaluate according to body system affected. Following surgery, evaluate residuals under the body system affected.', true, 'SOURCE_CHECKED', NULL, ARRAY['src.ecfr.38_part4_2026_08_27']::text[], '{}'::text[]);
INSERT INTO ref.rating_code (code, name, body_system, subsection, cfr_section, notes, has_criteria, status, status_note, source_ids, cited_codes) VALUES ('7113', 'Arteriovenous fistula, traumatic', 'THE CARDIOVASCULAR SYSTEM', 'Diseases of the Arteries and Veins', '38 CFR 4.104', NULL, true, 'SOURCE_CHECKED', NULL, ARRAY['src.ecfr.38_part4_2026_08_27']::text[], '{}'::text[]);
INSERT INTO ref.rating_code (code, name, body_system, subsection, cfr_section, notes, has_criteria, status, status_note, source_ids, cited_codes) VALUES ('7114', 'Peripheral arterial disease', 'THE CARDIOVASCULAR SYSTEM', 'Diseases of the Arteries and Veins', '38 CFR 4.104', 'Note (1): The ankle/brachial index (ABI) is the ratio of the systolic blood pressure at the ankle divided by the simultaneous brachial artery systolic blood pressure. For the purposes of this diagnostic code, normal ABI will be greater than or equal to 0.80. The ankle pressure (AP) is the systolic blood pressure measured at the ankle. Normal AP is greater than or equal to 100 mm Hg. The toe pressure (TP) is the systolic blood pressure measured at the great toe. Normal TP is greater than or equal to 60 mm Hg. Transcutaneous oxygen tension (Tc PO2) is measured at the first intercostal space on the foot. Normal Tc PO2 is greater than or equal to 60 mm Hg. All measurements must be determined by objective testing. Note (2): If AP, TP, and Tc PO2 testing are not of record, evaluate based on ABI unless the examiner states that an AP, TP, or Tc PO2 test is needed in a particular case because ABI does not sufficiently reflect the severity of the veteran''s peripheral arterial disease. In all other cases, evaluate based on the test that provides the highest impairment value Note (3): Evaluate residuals of aortic and large arterial bypass surgery or arterial graft as peripheral arterial disease. Note (4): These evaluations involve a single extremity. If more than one extremity is affected, evaluate each extremity separately and combine (under § 4.25), using the bilateral factor (§ 4.26), if applicable.', true, 'SOURCE_CHECKED', NULL, ARRAY['src.ecfr.38_part4_2026_08_27']::text[], '{}'::text[]);
INSERT INTO ref.rating_code (code, name, body_system, subsection, cfr_section, notes, has_criteria, status, status_note, source_ids, cited_codes) VALUES ('7115', 'Thrombo-angiitis obliterans (Buerger''s Disease)', 'THE CARDIOVASCULAR SYSTEM', 'Diseases of the Arteries and Veins', '38 CFR 4.104', 'Lower extremity: Rate under DC 7114. Note (1): These evaluations involve a single extremity. If more than one extremity is affected, evaluate each extremity separately and combine (under § 4.25), using the bilateral factor (§ 4.26), if applicable. Note (2): Trophic changes include, but are not limited to, skin changes (thinning, atrophy, fissuring, ulceration, scarring, absence of hair) as well as nail changes (clubbing, deformities).', true, 'SOURCE_CHECKED', NULL, ARRAY['src.ecfr.38_part4_2026_08_27']::text[], ARRAY['7114']::text[]);
INSERT INTO ref.rating_code (code, name, body_system, subsection, cfr_section, notes, has_criteria, status, status_note, source_ids, cited_codes) VALUES ('7117', 'Raynaud''s syndrome (secondary Raynaud''s phenomenon, secondary Raynaud''s)', 'THE CARDIOVASCULAR SYSTEM', 'Diseases of the Arteries and Veins', '38 CFR 4.104', 'Note (1): For purposes of this section, characteristic attacks consist of sequential color changes of the digits of one or more extremities lasting minutes to hours, sometimes with pain and paresthesias, and precipitated by exposure to cold or by emotional upsets. These evaluations are for Raynaud''s syndrome as a whole, regardless of the number of extremities involved or whether the nose and ears are involved. Note (2): This section is for evaluating Raynaud''s syndrome (secondary Raynaud''s phenomenon or secondary Raynaud''s). For evaluation of Raynaud''s disease (primary Raynaud''s), see DC 7124.', true, 'SOURCE_CHECKED', NULL, ARRAY['src.ecfr.38_part4_2026_08_27']::text[], ARRAY['7124']::text[]);
INSERT INTO ref.rating_code (code, name, body_system, subsection, cfr_section, notes, has_criteria, status, status_note, source_ids, cited_codes) VALUES ('7118', 'Angioneurotic edema', 'THE CARDIOVASCULAR SYSTEM', 'Diseases of the Arteries and Veins', '38 CFR 4.104', NULL, true, 'SOURCE_CHECKED', NULL, ARRAY['src.ecfr.38_part4_2026_08_27']::text[], '{}'::text[]);
INSERT INTO ref.rating_code (code, name, body_system, subsection, cfr_section, notes, has_criteria, status, status_note, source_ids, cited_codes) VALUES ('7119', 'Erythromelalgia', 'THE CARDIOVASCULAR SYSTEM', 'Diseases of the Arteries and Veins', '38 CFR 4.104', 'Note: For purposes of this section, a characteristic attack of erythromelalgia consists of burning pain in the hands, feet, or both, usually bilateral and symmetrical, with increased skin temperature and redness, occurring at warm ambient temperatures. These evaluations are for the disease as a whole, regardless of the number of extremities involved.', true, 'SOURCE_CHECKED', NULL, ARRAY['src.ecfr.38_part4_2026_08_27']::text[], '{}'::text[]);
INSERT INTO ref.rating_code (code, name, body_system, subsection, cfr_section, notes, has_criteria, status, status_note, source_ids, cited_codes) VALUES ('7120', 'Varicose veins', 'THE CARDIOVASCULAR SYSTEM', 'Diseases of the Arteries and Veins', '38 CFR 4.104', 'Evaluate under diagnostic code 7121.', false, 'SOURCE_CHECKED', NULL, ARRAY['src.ecfr.38_part4_2026_08_27']::text[], ARRAY['7121']::text[]);
INSERT INTO ref.rating_code (code, name, body_system, subsection, cfr_section, notes, has_criteria, status, status_note, source_ids, cited_codes) VALUES ('7121', 'Post-phlebitic syndrome', 'THE CARDIOVASCULAR SYSTEM', 'Diseases of the Arteries and Veins', '38 CFR 4.104', 'Note: These evaluations are for involvement of a single extremity. If more than one extremity is involved, evaluate each extremity separately and combine (under § 4.25), using the bilateral factor (§ 4.26), if applicable.', true, 'SOURCE_CHECKED', NULL, ARRAY['src.ecfr.38_part4_2026_08_27']::text[], '{}'::text[]);
INSERT INTO ref.rating_code (code, name, body_system, subsection, cfr_section, notes, has_criteria, status, status_note, source_ids, cited_codes) VALUES ('7122', 'Cold injury residuals', 'THE CARDIOVASCULAR SYSTEM', 'Diseases of the Arteries and Veins', '38 CFR 4.104', 'Note (1): Separately evaluate amputations of fingers or toes, and complications such as squamous cell carcinoma at the site of a cold injury scar or peripheral neuropathy, under other diagnostic codes. Separately evaluate other disabilities diagnosed as the residual effects of cold injury, such as Raynaud''s syndrome (which is otherwise known as secondary Raynaud''s phenomenon), muscle atrophy, etc., unless they are used to support an evaluation under diagnostic code 7122. Note (2): Evaluate each affected part (e.g., hand, foot, ear, nose) separately and combine the ratings in accordance with §§ 4.25 and 4.26.', true, 'SOURCE_CHECKED', NULL, ARRAY['src.ecfr.38_part4_2026_08_27']::text[], '{}'::text[]);
INSERT INTO ref.rating_code (code, name, body_system, subsection, cfr_section, notes, has_criteria, status, status_note, source_ids, cited_codes) VALUES ('7123', 'Soft tissue sarcoma', 'THE CARDIOVASCULAR SYSTEM', 'Diseases of the Arteries and Veins', '38 CFR 4.104', 'Note: A rating of 100 percent shall continue beyond the cessation of any surgical, X-ray, antineoplastic chemotherapy or other therapeutic procedure. Six months after discontinuance of such treatment, the appropriate disability rating shall be determined by mandatory VA examination. Any change in evaluation based upon that or any subsequent examination shall be subject to the provisions of § 3.105(e) of this chapter. If there has been no local recurrence or metastasis, rate on residuals.', true, 'SOURCE_CHECKED', NULL, ARRAY['src.ecfr.38_part4_2026_08_27']::text[], '{}'::text[]);
INSERT INTO ref.rating_code (code, name, body_system, subsection, cfr_section, notes, has_criteria, status, status_note, source_ids, cited_codes) VALUES ('7124', 'Raynaud''s disease (primary Raynaud''s)', 'THE CARDIOVASCULAR SYSTEM', 'Diseases of the Arteries and Veins', '38 CFR 4.104', 'Note (1): For purposes of this section, characteristic attacks consist of intermittent and episodic color changes of the digits of one or more extremities, lasting minutes or longer, with occasional pain and paresthesias, and precipitated by exposure to cold or by emotional upsets. These evaluations are for the disease as a whole, regardless of the number of extremities involved or whether the nose and ears are involved. Note (2): Trophic changes include, but are not limited to, skin changes (thinning, atrophy, fissuring, ulceration, scarring, absence of hair) as well as nail changes (clubbing, deformities). Note (3): This section is for evaluating Raynaud''s disease (primary Raynaud''s). For evaluation of Raynaud''s syndrome (also known as secondary Raynaud''s phenomenon, or secondary Raynaud''s), see DC 7117.', true, 'SOURCE_CHECKED', NULL, ARRAY['src.ecfr.38_part4_2026_08_27']::text[], ARRAY['7117']::text[]);
INSERT INTO ref.rating_code (code, name, body_system, subsection, cfr_section, notes, has_criteria, status, status_note, source_ids, cited_codes) VALUES ('7200', 'Soft tissue injury of the mouth, other than tongue or lips', 'THE DIGESTIVE SYSTEM', NULL, '38 CFR 4.114', 'Rate as for disfigurement (diagnostic codes 7800 and 7804) and impairment of mastication.', false, 'SOURCE_CHECKED', NULL, ARRAY['src.ecfr.38_part4_2026_08_27']::text[], ARRAY['7800','7804']::text[]);
INSERT INTO ref.rating_code (code, name, body_system, subsection, cfr_section, notes, has_criteria, status, status_note, source_ids, cited_codes) VALUES ('7201', 'Lips, injuries', 'THE DIGESTIVE SYSTEM', NULL, '38 CFR 4.114', 'Rate as disfigurement (diagnostic codes 7800 and 7804).', false, 'SOURCE_CHECKED', NULL, ARRAY['src.ecfr.38_part4_2026_08_27']::text[], ARRAY['7800','7804']::text[]);
INSERT INTO ref.rating_code (code, name, body_system, subsection, cfr_section, notes, has_criteria, status, status_note, source_ids, cited_codes) VALUES ('7202', 'Tongue, loss of whole or part', 'THE DIGESTIVE SYSTEM', NULL, '38 CFR 4.114', 'Note (1): Rate the residuals of speech impairment as complete organic aphonia (DC 6519) or incomplete aphonia as laryngitis, chronic (DC 6516). Note (2): Dietary modifications due to this condition must be prescribed by a medical provider.', true, 'SOURCE_CHECKED', NULL, ARRAY['src.ecfr.38_part4_2026_08_27']::text[], ARRAY['6516','6519']::text[]);
INSERT INTO ref.rating_code (code, name, body_system, subsection, cfr_section, notes, has_criteria, status, status_note, source_ids, cited_codes) VALUES ('7203', 'Esophagus, stricture', 'THE DIGESTIVE SYSTEM', NULL, '38 CFR 4.114', 'Note (1): Findings must be documented by barium swallow, computerized tomography, or esophagogastroduodenoscopy. Note (2): Non-gastrointestinal complications of procedures should be rated under the appropriate system. Note (3): This diagnostic code applies, but is not limited to, esophagitis, mechanical or chemical; Mallory Weiss syndrome (bleeding at junction of esophagus and stomach due to tears) due to caustic ingestion of alkali or acid; drug-induced or infectious esophagitis due to Candida, virus, or other organism; idiopathic eosinophilic, or lymphocytic esophagitis; esophagitis due to radiation therapy; esophagitis due to peptic stricture; and any esophageal condition that requires treatment with sclerotherapy. Note (4): Recurrent esophageal stricture is defined as the inability to maintain target esophageal diameter beyond 4 weeks after the target diameter has been achieved. Note (5): Refractory esophageal stricture is defined as the inability to achieve target esophageal diameter despite receiving no fewer than 5 dilatation sessions performed at 2-week intervals.', true, 'SOURCE_CHECKED', NULL, ARRAY['src.ecfr.38_part4_2026_08_27']::text[], '{}'::text[]);
INSERT INTO ref.rating_code (code, name, body_system, subsection, cfr_section, notes, has_criteria, status, status_note, source_ids, cited_codes) VALUES ('7204', 'Esophageal motility disorder', 'THE DIGESTIVE SYSTEM', NULL, '38 CFR 4.114', 'Rate as esophagus, stricture of (DC 7203). Note: This diagnostic code applies, but is not limited to, achalasia (cardiospasm), diffuse esophageal spasm (DES), corkscrew esophagus, nutcracker esophagus, and other motor disorders of the esophagus; esophageal rings (including Schatzki rings), mucosal webs or folds, and impairment of the esophagus caused by systemic conditions such as myasthenia gravis, scleroderma, and other neurologic conditions.', false, 'SOURCE_CHECKED', NULL, ARRAY['src.ecfr.38_part4_2026_08_27']::text[], ARRAY['7203']::text[]);
INSERT INTO ref.rating_code (code, name, body_system, subsection, cfr_section, notes, has_criteria, status, status_note, source_ids, cited_codes) VALUES ('7205', 'Esophagus, diverticulum', 'THE DIGESTIVE SYSTEM', NULL, '38 CFR 4.114', 'Rate as esophagus, stricture of (DC 7203). Note: This diagnostic code, applies, but is not limited to, pharyngo- esophageal (Zenker''s) diverticulum, mid-esophageal diverticulum, and epiphrenic (distal esophagus) diverticulum.', false, 'SOURCE_CHECKED', NULL, ARRAY['src.ecfr.38_part4_2026_08_27']::text[], ARRAY['7203']::text[]);
INSERT INTO ref.rating_code (code, name, body_system, subsection, cfr_section, notes, has_criteria, status, status_note, source_ids, cited_codes) VALUES ('7206', 'Gastroesophageal reflux disease', 'THE DIGESTIVE SYSTEM', NULL, '38 CFR 4.114', 'Note (1): Findings must be documented by barium swallow, computerized tomography, or esophagogastroduodenoscopy. Note (2): Non-gastrointestinal complications of procedures should be rated under the appropriate system. Note (3): This diagnostic code applies, but is not limited to, esophagitis, mechanical or chemical; Mallory Weiss syndrome (bleeding at junction of esophagus and stomach due to tears) due to caustic ingestion of alkali or acid; drug-induced or infectious esophagitis due to Candida, virus, or other organism; idiopathic eosinophilic, or lymphocytic esophagitis; esophagitis due to radiation therapy; esophagitis due to peptic stricture; and any esophageal condition that requires treatment with sclerotherapy. Note (4): Recurrent esophageal stricture is defined as the inability to maintain target esophageal diameter beyond 4 weeks after the target diameter has been achieved. Note (5): Refractory esophageal stricture is defined as the inability to achieve target esophageal diameter despite receiving no fewer than 5 dilatation sessions performed at 2-week intervals.', true, 'SOURCE_CHECKED', NULL, ARRAY['src.ecfr.38_part4_2026_08_27']::text[], '{}'::text[]);
INSERT INTO ref.rating_code (code, name, body_system, subsection, cfr_section, notes, has_criteria, status, status_note, source_ids, cited_codes) VALUES ('7207', 'Barrett''s esophagus', 'THE DIGESTIVE SYSTEM', NULL, '38 CFR 4.114', 'With esophageal stricture: Rate as esophagus, stricture of (DC 7203). Note (1): If malignancy develops, rate as malignant neoplasms of the digestive system, exclusive of skin growths (DC 7343). Note (2): If the condition is resolved via surgery, radiofrequency ablation, or other treatment, rate residuals as esophagus, stricture of (DC 7203).', true, 'SOURCE_CHECKED', NULL, ARRAY['src.ecfr.38_part4_2026_08_27']::text[], ARRAY['7203','7343']::text[]);
INSERT INTO ref.rating_code (code, name, body_system, subsection, cfr_section, notes, has_criteria, status, status_note, source_ids, cited_codes) VALUES ('7301', 'Peritoneum, adhesions of, due to surgery, trauma, or infection', 'THE DIGESTIVE SYSTEM', NULL, '38 CFR 4.114', NULL, true, 'SOURCE_CHECKED', NULL, ARRAY['src.ecfr.38_part4_2026_08_27']::text[], '{}'::text[]);
INSERT INTO ref.rating_code (code, name, body_system, subsection, cfr_section, notes, has_criteria, status, status_note, source_ids, cited_codes) VALUES ('7303', 'Chronic complications of upper gastrointestinal surgery', 'THE DIGESTIVE SYSTEM', NULL, '38 CFR 4.114', 'Note (1): For resection of small intestine, use DC 7328. Note (2): If pancreatic surgery results in a vitamin or mineral deficiency (e.g., B12, iron, calcium, or fat-soluble vitamins), evaluate under the appropriate vitamin/mineral deficiency code and assign the higher rating. For example, evaluate Vitamin A, B, C or D deficiencies under DC 6313; ocular manifestations of vitamin deficiencies, such as night blindness, under DC 6313; keratitis or keratomalacia due to Vitamin A deficiency under DC 6001; Vitamin E deficiency under neuropathy; and Vitamin K deficiency under prolonged clotting (e.g., DC 7705). Note (3): This diagnostic code includes operations performed on the esophagus, stomach, pancreas, and small intestine, including bariatric surgery.', true, 'SOURCE_CHECKED', NULL, ARRAY['src.ecfr.38_part4_2026_08_27']::text[], ARRAY['6001','6313','7328','7705']::text[]);
INSERT INTO ref.rating_code (code, name, body_system, subsection, cfr_section, notes, has_criteria, status, status_note, source_ids, cited_codes) VALUES ('7304', 'Peptic ulcer disease', 'THE DIGESTIVE SYSTEM', NULL, '38 CFR 4.114', 'Note: After three months at the 100% evaluation, rate on residuals as determined by mandatory VA medical examination. Apply the provisions of § 3.105(e) of this chapter to any change in evaluation based upon that or any subsequent examination.', true, 'SOURCE_CHECKED', NULL, ARRAY['src.ecfr.38_part4_2026_08_27']::text[], '{}'::text[]);
INSERT INTO ref.rating_code (code, name, body_system, subsection, cfr_section, notes, has_criteria, status, status_note, source_ids, cited_codes) VALUES ('7305', 'Ulcer, duodenal', 'THE DIGESTIVE SYSTEM', NULL, '38 CFR 4.114', NULL, false, 'SUPERSEDED', 'Removed from 38 CFR Part 4 (Appendix A: Evaluation November 1, 1962; Removed May 19, 2024). Name as it stood in the 2020 edition.', ARRAY['src.ecfr.38_part4_2026_08_27']::text[], '{}'::text[]);
INSERT INTO ref.rating_code (code, name, body_system, subsection, cfr_section, notes, has_criteria, status, status_note, source_ids, cited_codes) VALUES ('7306', 'Ulcer, marginal', 'THE DIGESTIVE SYSTEM', NULL, '38 CFR 4.114', NULL, false, 'SUPERSEDED', 'Removed from 38 CFR Part 4 (Appendix A: Criterion April 8, 1959; Removed May 19, 2024). Name as it stood in the 2020 edition.', ARRAY['src.ecfr.38_part4_2026_08_27']::text[], '{}'::text[]);
INSERT INTO ref.rating_code (code, name, body_system, subsection, cfr_section, notes, has_criteria, status, status_note, source_ids, cited_codes) VALUES ('7307', 'Gastritis, chronic', 'THE DIGESTIVE SYSTEM', NULL, '38 CFR 4.114', 'Rate as peptic ulcer disease (DC 7304). Note: This diagnostic code includes Helicobacter pylori infection, drug-induced gastritis, Zollinger-Ellison syndrome, and portal-hypertensive gastropathy with varix-related complications.', false, 'SOURCE_CHECKED', NULL, ARRAY['src.ecfr.38_part4_2026_08_27']::text[], ARRAY['7304']::text[]);
INSERT INTO ref.rating_code (code, name, body_system, subsection, cfr_section, notes, has_criteria, status, status_note, source_ids, cited_codes) VALUES ('7308', 'Postgastrectomy syndromes', 'THE DIGESTIVE SYSTEM', NULL, '38 CFR 4.114', 'Rate residuals as chronic complications of upper gastrointestinal surgery (DC 7303).', false, 'SOURCE_CHECKED', NULL, ARRAY['src.ecfr.38_part4_2026_08_27']::text[], ARRAY['7303']::text[]);
INSERT INTO ref.rating_code (code, name, body_system, subsection, cfr_section, notes, has_criteria, status, status_note, source_ids, cited_codes) VALUES ('7309', 'Stomach, stenosis', 'THE DIGESTIVE SYSTEM', NULL, '38 CFR 4.114', 'Rate as chronic complications of upper gastrointestinal surgery (DC 7303) or peptic ulcer disease (DC 7304), depending on the predominant disability.', false, 'SOURCE_CHECKED', NULL, ARRAY['src.ecfr.38_part4_2026_08_27']::text[], ARRAY['7303','7304']::text[]);
INSERT INTO ref.rating_code (code, name, body_system, subsection, cfr_section, notes, has_criteria, status, status_note, source_ids, cited_codes) VALUES ('7310', 'Stomach, injury of, residuals', 'THE DIGESTIVE SYSTEM', NULL, '38 CFR 4.114', 'Pre-operative: Rate as adhesions of peritoneum due to surgery, trauma, disease, or infection (DC 7301). No adhesions are necessary when evaluating under DC 7301. Post-operative: Rate as chronic complications of upper gastrointestinal surgery (DC 7303).', false, 'SOURCE_CHECKED', NULL, ARRAY['src.ecfr.38_part4_2026_08_27']::text[], ARRAY['7301','7303']::text[]);
INSERT INTO ref.rating_code (code, name, body_system, subsection, cfr_section, notes, has_criteria, status, status_note, source_ids, cited_codes) VALUES ('7311', 'Liver, injury of, residuals', 'THE DIGESTIVE SYSTEM', NULL, '38 CFR 4.114', 'Depending on the specific residuals, separately evaluate as adhesions of peritoneum (diagnostic code 7301), cirrhosis of liver (diagnostic code 7312), and chronic liver disease without cirrhosis (diagnostic code 7345).', false, 'SOURCE_CHECKED', NULL, ARRAY['src.ecfr.38_part4_2026_08_27']::text[], ARRAY['7301','7312','7345']::text[]);
INSERT INTO ref.rating_code (code, name, body_system, subsection, cfr_section, notes, has_criteria, status, status_note, source_ids, cited_codes) VALUES ('7312', 'Cirrhosis of the liver', 'THE DIGESTIVE SYSTEM', NULL, '38 CFR 4.114', 'Note (1): Rate hepatocellular carcinoma occurring with cirrhosis under DC 7343 (Malignant neoplasms of the digestive system, exclusive of skin growths) in lieu of DC 7312. Note (2): Biochemical studies, imaging studies, or biopsy must confirm liver dysfunction (including hyponatremia, thrombocytopenia, and/or coagulopathy). Note (3): Rate condition based on symptomatology where the evidence does not contain a Model for End-Stage Liver Disease score.', true, 'SOURCE_CHECKED', NULL, ARRAY['src.ecfr.38_part4_2026_08_27']::text[], ARRAY['7343']::text[]);
INSERT INTO ref.rating_code (code, name, body_system, subsection, cfr_section, notes, has_criteria, status, status_note, source_ids, cited_codes) VALUES ('7314', 'Chronic biliary tract disease', 'THE DIGESTIVE SYSTEM', NULL, '38 CFR 4.114', 'Note: This diagnostic code includes cholangitis, biliary strictures, Sphincter of Oddi dysfunction, bile duct injury, and choledochal cyst. Rate primary sclerosing cholangitis under chronic liver disease without cirrhosis (DC 7345).', true, 'SOURCE_CHECKED', NULL, ARRAY['src.ecfr.38_part4_2026_08_27']::text[], ARRAY['7345']::text[]);
INSERT INTO ref.rating_code (code, name, body_system, subsection, cfr_section, notes, has_criteria, status, status_note, source_ids, cited_codes) VALUES ('7315', 'Cholelithiasis, chronic', 'THE DIGESTIVE SYSTEM', NULL, '38 CFR 4.114', 'Rate as chronic biliary tract disease (DC 7314).', false, 'SOURCE_CHECKED', NULL, ARRAY['src.ecfr.38_part4_2026_08_27']::text[], ARRAY['7314']::text[]);
INSERT INTO ref.rating_code (code, name, body_system, subsection, cfr_section, notes, has_criteria, status, status_note, source_ids, cited_codes) VALUES ('7316', 'Cholangitis, chronic', 'THE DIGESTIVE SYSTEM', NULL, '38 CFR 4.114', NULL, false, 'SUPERSEDED', 'Removed from 38 CFR Part 4 (Appendix A: Removed May 19, 2024). Name as it stood in the 2020 edition.', ARRAY['src.ecfr.38_part4_2026_08_27']::text[], '{}'::text[]);
INSERT INTO ref.rating_code (code, name, body_system, subsection, cfr_section, notes, has_criteria, status, status_note, source_ids, cited_codes) VALUES ('7317', 'Gallbladder, injury of', 'THE DIGESTIVE SYSTEM', NULL, '38 CFR 4.114', 'Rate as adhesions of the peritoneum due to surgery, trauma, disease, or infection (DC 7301); or chronic gallbladder and biliary tract disease (DC 7314), or cholecystectomy (gallbladder removal), complications of (such as strictures and biliary leaks) (DC 7318), depending on the predominant disability. Note: When rating gallbladder injuries analogous to DC 7301, a finding of adhesions is not necessary.', false, 'SOURCE_CHECKED', NULL, ARRAY['src.ecfr.38_part4_2026_08_27']::text[], ARRAY['7301','7314','7318']::text[]);
INSERT INTO ref.rating_code (code, name, body_system, subsection, cfr_section, notes, has_criteria, status, status_note, source_ids, cited_codes) VALUES ('7318', 'Cholecystectomy (gallbladder removal), complications of (such as strictures and biliary leaks)', 'THE DIGESTIVE SYSTEM', NULL, '38 CFR 4.114', NULL, true, 'SOURCE_CHECKED', NULL, ARRAY['src.ecfr.38_part4_2026_08_27']::text[], '{}'::text[]);
INSERT INTO ref.rating_code (code, name, body_system, subsection, cfr_section, notes, has_criteria, status, status_note, source_ids, cited_codes) VALUES ('7319', 'Irritable bowel syndrome (IBS)', 'THE DIGESTIVE SYSTEM', NULL, '38 CFR 4.114', 'Note: This diagnostic code may include functional digestive disorders (see § 3.317 of this chapter), such as dyspepsia, functional bloating and constipation, and diarrhea. Evaluate other symptoms of a functional digestive disorder not encompassed by this diagnostic code under the appropriate diagnostic code, to include gastrointestinal dysmotility syndrome (DC 7356), following the general principles of § 4.14 and this section.', true, 'SOURCE_CHECKED', NULL, ARRAY['src.ecfr.38_part4_2026_08_27']::text[], ARRAY['7356']::text[]);
INSERT INTO ref.rating_code (code, name, body_system, subsection, cfr_section, notes, has_criteria, status, status_note, source_ids, cited_codes) VALUES ('7321', 'Amebiasis', 'THE DIGESTIVE SYSTEM', NULL, '38 CFR 4.114', NULL, false, 'SUPERSEDED', 'Removed from 38 CFR Part 4 (Appendix A: Evaluation July 6, 1950; criterion March 10, 1976; Removed May 19, 2024). Name as it stood in the 2020 edition.', ARRAY['src.ecfr.38_part4_2026_08_27']::text[], '{}'::text[]);
INSERT INTO ref.rating_code (code, name, body_system, subsection, cfr_section, notes, has_criteria, status, status_note, source_ids, cited_codes) VALUES ('7322', 'Dysentery, bacillary', 'THE DIGESTIVE SYSTEM', NULL, '38 CFR 4.114', NULL, false, 'SUPERSEDED', 'Removed from 38 CFR Part 4 (Appendix A: Removed May 19, 2024). Name as it stood in the 2020 edition.', ARRAY['src.ecfr.38_part4_2026_08_27']::text[], '{}'::text[]);
INSERT INTO ref.rating_code (code, name, body_system, subsection, cfr_section, notes, has_criteria, status, status_note, source_ids, cited_codes) VALUES ('7323', 'Colitis, ulcerative', 'THE DIGESTIVE SYSTEM', NULL, '38 CFR 4.114', 'Rate as Crohn''s disease or undifferentiated form of inflammatory bowel disease (DC 7326).', false, 'SOURCE_CHECKED', NULL, ARRAY['src.ecfr.38_part4_2026_08_27']::text[], ARRAY['7326']::text[]);
INSERT INTO ref.rating_code (code, name, body_system, subsection, cfr_section, notes, has_criteria, status, status_note, source_ids, cited_codes) VALUES ('7324', 'Distomiasis, intestinal or hepatic', 'THE DIGESTIVE SYSTEM', NULL, '38 CFR 4.114', NULL, false, 'SUPERSEDED', 'Removed from 38 CFR Part 4 (Appendix A: Removed May 19, 2024). Name as it stood in the 2020 edition.', ARRAY['src.ecfr.38_part4_2026_08_27']::text[], '{}'::text[]);
INSERT INTO ref.rating_code (code, name, body_system, subsection, cfr_section, notes, has_criteria, status, status_note, source_ids, cited_codes) VALUES ('7325', 'Enteritis, chronic', 'THE DIGESTIVE SYSTEM', NULL, '38 CFR 4.114', 'Rate as Irritable Bowel Syndrome (DC 7319) or Crohn''s disease or undifferentiated form of inflammatory bowel disease (DC 7326), depending on the predominant disability.', false, 'SOURCE_CHECKED', NULL, ARRAY['src.ecfr.38_part4_2026_08_27']::text[], ARRAY['7319','7326']::text[]);
INSERT INTO ref.rating_code (code, name, body_system, subsection, cfr_section, notes, has_criteria, status, status_note, source_ids, cited_codes) VALUES ('7326', 'Crohn''s disease or undifferentiated form of inflammatory bowel disease', 'THE DIGESTIVE SYSTEM', NULL, '38 CFR 4.114', 'Note (1): Following colectomy/colostomy with persistent or recurrent symptoms, rate either under DC 7326 or DC 7329 (Intestine, large, resection of), whichever provides the highest rating. Note (2): VA requires diagnoses under DC 7326 to be confirmed by endoscopy or radiologic studies. Note (3): Inflammation may involve small bowel (ileitis), large bowel (colitis), or inflammation of any component of the gastrointestinal tract from the mouth to the anus.', true, 'SOURCE_CHECKED', NULL, ARRAY['src.ecfr.38_part4_2026_08_27']::text[], ARRAY['7329']::text[]);
INSERT INTO ref.rating_code (code, name, body_system, subsection, cfr_section, notes, has_criteria, status, status_note, source_ids, cited_codes) VALUES ('7327', 'Diverticulitis and diverticulosis', 'THE DIGESTIVE SYSTEM', NULL, '38 CFR 4.114', 'Note: For colectomy or colostomy, use DC 7327 or DC 7329 (Intestine, large, resection of), whichever results in a higher evaluation.', true, 'SOURCE_CHECKED', NULL, ARRAY['src.ecfr.38_part4_2026_08_27']::text[], ARRAY['7329']::text[]);
INSERT INTO ref.rating_code (code, name, body_system, subsection, cfr_section, notes, has_criteria, status, status_note, source_ids, cited_codes) VALUES ('7328', 'Intestine, small, resection of', 'THE DIGESTIVE SYSTEM', NULL, '38 CFR 4.114', 'Note: This diagnostic code includes short bowel syndrome, mesenteric ischemic thrombosis, and post-bariatric surgery complications. Where short bowel syndrome results in high-output syndrome, to include high-output stoma, consider assigning a higher evaluation under DC 7329 (Intestine, large, resection of).', true, 'SOURCE_CHECKED', NULL, ARRAY['src.ecfr.38_part4_2026_08_27']::text[], ARRAY['7329']::text[]);
INSERT INTO ref.rating_code (code, name, body_system, subsection, cfr_section, notes, has_criteria, status, status_note, source_ids, cited_codes) VALUES ('7329', 'Intestine, large, resection', 'THE DIGESTIVE SYSTEM', NULL, '38 CFR 4.114', NULL, true, 'SOURCE_CHECKED', NULL, ARRAY['src.ecfr.38_part4_2026_08_27']::text[], '{}'::text[]);
INSERT INTO ref.rating_code (code, name, body_system, subsection, cfr_section, notes, has_criteria, status, status_note, source_ids, cited_codes) VALUES ('7330', 'Intestinal fistulous diseases, external', 'THE DIGESTIVE SYSTEM', NULL, '38 CFR 4.114', 'Note: This code applies to external fistulas that have developed as a consequence of abdominal trauma, surgery, radiation, malignancy, infection, or ischemia.', true, 'SOURCE_CHECKED', NULL, ARRAY['src.ecfr.38_part4_2026_08_27']::text[], '{}'::text[]);
INSERT INTO ref.rating_code (code, name, body_system, subsection, cfr_section, notes, has_criteria, status, status_note, source_ids, cited_codes) VALUES ('7331', 'Peritonitis', 'THE DIGESTIVE SYSTEM', NULL, '38 CFR 4.114', 'Inactive: See §§ 4.88b and 4.89.', true, 'SOURCE_CHECKED', NULL, ARRAY['src.ecfr.38_part4_2026_08_27']::text[], '{}'::text[]);
INSERT INTO ref.rating_code (code, name, body_system, subsection, cfr_section, notes, has_criteria, status, status_note, source_ids, cited_codes) VALUES ('7332', 'Rectum and anus, impairment of sphincter control', 'THE DIGESTIVE SYSTEM', NULL, '38 CFR 4.114', 'Note: Complete or partial loss of sphincter control refers to the inability to retain or expel stool at an appropriate time and place.', true, 'SOURCE_CHECKED', NULL, ARRAY['src.ecfr.38_part4_2026_08_27']::text[], '{}'::text[]);
INSERT INTO ref.rating_code (code, name, body_system, subsection, cfr_section, notes, has_criteria, status, status_note, source_ids, cited_codes) VALUES ('7333', 'Rectum & anus, stricture', 'THE DIGESTIVE SYSTEM', NULL, '38 CFR 4.114', 'Note (1): Conditions rated under this code include dyssynergic defecation (levator ani) and anismus (functional constipation). Note (2): Evaluate an ostomy as Intestine, large, resection of (DC 7329).', true, 'SOURCE_CHECKED', NULL, ARRAY['src.ecfr.38_part4_2026_08_27']::text[], ARRAY['7329']::text[]);
INSERT INTO ref.rating_code (code, name, body_system, subsection, cfr_section, notes, has_criteria, status, status_note, source_ids, cited_codes) VALUES ('7334', 'Rectum, prolapse', 'THE DIGESTIVE SYSTEM', NULL, '38 CFR 4.114', 'Note (1): For repairable prolapse of the rectum, continue the 100% evaluation for two months following repair. Thereafter, determine the appropriate evaluation based on residuals by mandatory VA examination. Apply the provisions of § 3.105(e) of this chapter to any change in evaluation based upon that or any subsequent examination. Note (2): Where impairment of sphincter control constitutes the predominant disability, rate under diagnostic code 7332 (Rectum and anus, impairment of sphincter control).', true, 'SOURCE_CHECKED', NULL, ARRAY['src.ecfr.38_part4_2026_08_27']::text[], ARRAY['7332']::text[]);
INSERT INTO ref.rating_code (code, name, body_system, subsection, cfr_section, notes, has_criteria, status, status_note, source_ids, cited_codes) VALUES ('7335', 'Ano, fistula in, including anorectal fistula, anorectal abscess', 'THE DIGESTIVE SYSTEM', NULL, '38 CFR 4.114', NULL, true, 'SOURCE_CHECKED', NULL, ARRAY['src.ecfr.38_part4_2026_08_27']::text[], '{}'::text[]);
INSERT INTO ref.rating_code (code, name, body_system, subsection, cfr_section, notes, has_criteria, status, status_note, source_ids, cited_codes) VALUES ('7336', 'Hemorrhoids, external or internal', 'THE DIGESTIVE SYSTEM', NULL, '38 CFR 4.114', NULL, true, 'SOURCE_CHECKED', NULL, ARRAY['src.ecfr.38_part4_2026_08_27']::text[], '{}'::text[]);
INSERT INTO ref.rating_code (code, name, body_system, subsection, cfr_section, notes, has_criteria, status, status_note, source_ids, cited_codes) VALUES ('7337', 'Pruritus ani (anal itching)', 'THE DIGESTIVE SYSTEM', NULL, '38 CFR 4.114', NULL, true, 'SOURCE_CHECKED', NULL, ARRAY['src.ecfr.38_part4_2026_08_27']::text[], '{}'::text[]);
INSERT INTO ref.rating_code (code, name, body_system, subsection, cfr_section, notes, has_criteria, status, status_note, source_ids, cited_codes) VALUES ('7338', 'Hernia, including femoral, inguinal, umbilical, ventral, incisional, and other (but not including hiatal)', 'THE DIGESTIVE SYSTEM', NULL, '38 CFR 4.114', 'Note (1): With two compensable inguinal hernias, evaluate the more severely disabling hernia first, and then add 10% to that rating to account for the second compensable hernia. Do not add 10% to that rating if the more severely disabling hernia is rated at 100%. Note (2): Any one of the following activities of daily living are sufficient for evaluation: bathing, dressing, hygiene, and/or transfers.', true, 'SOURCE_CHECKED', NULL, ARRAY['src.ecfr.38_part4_2026_08_27']::text[], '{}'::text[]);
INSERT INTO ref.rating_code (code, name, body_system, subsection, cfr_section, notes, has_criteria, status, status_note, source_ids, cited_codes) VALUES ('7339', 'Hernia, ventral, postoperative', 'THE DIGESTIVE SYSTEM', NULL, '38 CFR 4.114', NULL, false, 'SUPERSEDED', 'Removed from 38 CFR Part 4 (Appendix A: Criterion March 10, 1976; removed May 19, 2024). Name as it stood in the 2020 edition.', ARRAY['src.ecfr.38_part4_2026_08_27']::text[], '{}'::text[]);
INSERT INTO ref.rating_code (code, name, body_system, subsection, cfr_section, notes, has_criteria, status, status_note, source_ids, cited_codes) VALUES ('7340', 'Hernia, femoral', 'THE DIGESTIVE SYSTEM', NULL, '38 CFR 4.114', NULL, false, 'SUPERSEDED', 'Removed from 38 CFR Part 4 (Appendix A: Removed May 19, 2024). Name as it stood in the 2020 edition.', ARRAY['src.ecfr.38_part4_2026_08_27']::text[], '{}'::text[]);
INSERT INTO ref.rating_code (code, name, body_system, subsection, cfr_section, notes, has_criteria, status, status_note, source_ids, cited_codes) VALUES ('7342', 'Visceroptosis', 'THE DIGESTIVE SYSTEM', NULL, '38 CFR 4.114', NULL, true, 'SOURCE_CHECKED', NULL, ARRAY['src.ecfr.38_part4_2026_08_27']::text[], '{}'::text[]);
INSERT INTO ref.rating_code (code, name, body_system, subsection, cfr_section, notes, has_criteria, status, status_note, source_ids, cited_codes) VALUES ('7343', 'Neoplasms, malignant', 'THE DIGESTIVE SYSTEM', NULL, '38 CFR 4.114', 'Note: A rating of 100 percent shall continue beyond the cessation of any surgical, X-ray, antineoplastic chemotherapy or other therapeutic procedure. Six months after discontinuance of such treatment, the appropriate disability rating shall be determined by mandatory VA examination. Any change in evaluation based upon that or any subsequent examination shall be subject to the provisions of § 3.105(e) of this chapter. If there has been no local recurrence or metastasis, rate on residuals.', true, 'SOURCE_CHECKED', NULL, ARRAY['src.ecfr.38_part4_2026_08_27']::text[], '{}'::text[]);
INSERT INTO ref.rating_code (code, name, body_system, subsection, cfr_section, notes, has_criteria, status, status_note, source_ids, cited_codes) VALUES ('7344', 'Benign neoplasms, exclusive of skin growths', 'THE DIGESTIVE SYSTEM', NULL, '38 CFR 4.114', 'Evaluate under a diagnostic code appropriate to the predominant disability or the specific residuals after treatment. Note: This diagnostic code includes lipoma, leiomyoma, colon polyps, or villous adenoma.', false, 'SOURCE_CHECKED', NULL, ARRAY['src.ecfr.38_part4_2026_08_27']::text[], '{}'::text[]);
INSERT INTO ref.rating_code (code, name, body_system, subsection, cfr_section, notes, has_criteria, status, status_note, source_ids, cited_codes) VALUES ('7345', 'Chronic liver disease without cirrhosis', 'THE DIGESTIVE SYSTEM', NULL, '38 CFR 4.114', 'Note (1): 100% evaluation shall continue for six months following discontinuance of parenteral antiviral therapy and administration of parenteral immunomodulatory drugs. Six months after discontinuance of parenteral antiviral therapy and parenteral immunomodulatory drugs, determine the appropriate disability rating by mandatory VA exam. Apply the provisions of § 3.105(e) of this chapter to any change in evaluation based upon that or any subsequent examination. Note (2): For individuals for whom physicians recommend both parenteral antiviral therapy and parenteral immunomodulatory drugs, but for whom treatment is medically contraindicated, rate according to DC 7312 (Cirrhosis of the liver). Note (3): This diagnostic code includes Hepatitis B (confirmed by serologic testing), primary biliary cirrhosis (PBC), primary sclerosing cholangitis (PSC), autoimmune liver disease, Wilson''s disease, Alpha-1-antitrypsin deficiency, hemochromatosis, drug-induced hepatitis, and non-alcoholic steatohepatitis (NASH). Track Hepatitis C (or non-A, non-B hepatitis) under DC 7354 but evaluate it using the criteria in this entry. Note (4): Evaluate sequelae, such as cirrhosis or malignancy of the liver, under an appropriate diagnostic code, but do not use the same signs and symptoms as the basis for evaluation under DC 7354 and under a diagnostic code for sequelae. (See § 4.14)', true, 'SOURCE_CHECKED', NULL, ARRAY['src.ecfr.38_part4_2026_08_27']::text[], ARRAY['7312','7354']::text[]);
INSERT INTO ref.rating_code (code, name, body_system, subsection, cfr_section, notes, has_criteria, status, status_note, source_ids, cited_codes) VALUES ('7346', 'Hiatal hernia and paraesophageal hernia', 'THE DIGESTIVE SYSTEM', NULL, '38 CFR 4.114', 'Rate as esophagus, stricture of (DC 7203).', false, 'SOURCE_CHECKED', NULL, ARRAY['src.ecfr.38_part4_2026_08_27']::text[], ARRAY['7203']::text[]);
INSERT INTO ref.rating_code (code, name, body_system, subsection, cfr_section, notes, has_criteria, status, status_note, source_ids, cited_codes) VALUES ('7347', 'Pancreatitis, chronic', 'THE DIGESTIVE SYSTEM', NULL, '38 CFR 4.114', 'Note (1): Appropriate diagnostic studies must confirm that abdominal pain in this condition results from pancreatitis. Note (2): Separately rate endocrine dysfunction resulting in diabetes due to pancreatic insufficiency under DC 7913 (Diabetes mellitus).', true, 'SOURCE_CHECKED', NULL, ARRAY['src.ecfr.38_part4_2026_08_27']::text[], ARRAY['7913']::text[]);
INSERT INTO ref.rating_code (code, name, body_system, subsection, cfr_section, notes, has_criteria, status, status_note, source_ids, cited_codes) VALUES ('7348', 'Vagotomy with pyloroplasty or gastroenterostomy', 'THE DIGESTIVE SYSTEM', NULL, '38 CFR 4.114', 'Note: Rate recurrent ulcer following complete vagotomy under DC 7304 (Peptic ulcer disease), with a minimum rating of 20%; and rate post-operative residuals not addressed by this diagnostic code under DC 7303 (Chronic complications of upper gastrointestinal surgery).', true, 'SOURCE_CHECKED', NULL, ARRAY['src.ecfr.38_part4_2026_08_27']::text[], ARRAY['7303','7304']::text[]);
INSERT INTO ref.rating_code (code, name, body_system, subsection, cfr_section, notes, has_criteria, status, status_note, source_ids, cited_codes) VALUES ('7350', 'Liver abscess', 'THE DIGESTIVE SYSTEM', NULL, '38 CFR 4.114', 'Assign a rating of 100% for 6 months from the date of initial diagnosis. Six months following initial diagnosis, determine the appropriate disability rating by mandatory VA examination. Thereafter, rate the condition based on chronic residuals under the appropriate body system. Apply the provisions of § 3.105(e) of this chapter to any reduction in evaluation. Note:This diagnostic code includes abscesses caused by bacterial, viral, amebic (e.g., E. hystolytica), fungal (e.g., C. albicans), and other agents.', false, 'SOURCE_CHECKED', NULL, ARRAY['src.ecfr.38_part4_2026_08_27']::text[], '{}'::text[]);
INSERT INTO ref.rating_code (code, name, body_system, subsection, cfr_section, notes, has_criteria, status, status_note, source_ids, cited_codes) VALUES ('7351', 'Liver transplant', 'THE DIGESTIVE SYSTEM', NULL, '38 CFR 4.114', 'Note: Assign a rating of 100% as of the date of hospital admission for transplant surgery. One year following discharge, determine the appropriate disability rating by mandatory VA examination. Apply the provisions of § 3.105(e) of this chapter to any change in evaluation based upon that or any subsequent examination. Rate residuals of any recurrent underlying liver disease under the appropriate diagnostic code and, when appropriate, combine with other post-transplant residuals under the appropriate body system(s), subject to the provisions of § 4.14 and this section.', true, 'SOURCE_CHECKED', NULL, ARRAY['src.ecfr.38_part4_2026_08_27']::text[], '{}'::text[]);
INSERT INTO ref.rating_code (code, name, body_system, subsection, cfr_section, notes, has_criteria, status, status_note, source_ids, cited_codes) VALUES ('7352', 'Pancreas transplant', 'THE DIGESTIVE SYSTEM', NULL, '38 CFR 4.114', 'Note: Assign a rating of 100% as of the date of hospital admission for transplant surgery. One year following discharge, determine the appropriate disability rating by mandatory VA examination. Apply the provisions of § 3.105(e) of this chapter to any change in evaluation based upon that or any subsequent examination.', true, 'SOURCE_CHECKED', NULL, ARRAY['src.ecfr.38_part4_2026_08_27']::text[], '{}'::text[]);
INSERT INTO ref.rating_code (code, name, body_system, subsection, cfr_section, notes, has_criteria, status, status_note, source_ids, cited_codes) VALUES ('7354', 'Hepatitis C (or non-A, non-B hepatitis)', 'THE DIGESTIVE SYSTEM', NULL, '38 CFR 4.114', 'Rate under DC 7345 (Chronic liver disease without cirrhosis).', false, 'SOURCE_CHECKED', NULL, ARRAY['src.ecfr.38_part4_2026_08_27']::text[], ARRAY['7345']::text[]);
INSERT INTO ref.rating_code (code, name, body_system, subsection, cfr_section, notes, has_criteria, status, status_note, source_ids, cited_codes) VALUES ('7355', 'Celiac disease', 'THE DIGESTIVE SYSTEM', NULL, '38 CFR 4.114', 'Note (1): An appropriate serum antibody test or endoscopy with biopsy must confirm the diagnosis. Note (2): For evaluation of celiac disease with the predominant disability of malabsorption, use the greater evaluation between DC 7328 or celiac disease under DC 7355.', true, 'SOURCE_CHECKED', NULL, ARRAY['src.ecfr.38_part4_2026_08_27']::text[], ARRAY['7328']::text[]);
INSERT INTO ref.rating_code (code, name, body_system, subsection, cfr_section, notes, has_criteria, status, status_note, source_ids, cited_codes) VALUES ('7356', 'Gastrointestinal dysmotility syndrome', 'THE DIGESTIVE SYSTEM', NULL, '38 CFR 4.114', 'Note: Use this diagnostic code for illnesses associated with § 3.317(a)(2)(i)(B)(3) of this chapter, other than those which can be evaluated under DC 7319.', true, 'SOURCE_CHECKED', NULL, ARRAY['src.ecfr.38_part4_2026_08_27']::text[], ARRAY['7319']::text[]);
INSERT INTO ref.rating_code (code, name, body_system, subsection, cfr_section, notes, has_criteria, status, status_note, source_ids, cited_codes) VALUES ('7357', 'Post pancreatectomy syndrome', 'THE DIGESTIVE SYSTEM', NULL, '38 CFR 4.114', 'Following total or partial pancreatectomy, evaluate under Pancreatitis, chronic (DC 7347), Chronic complications of upper gastrointestinal surgery (DC 7303), or based on residuals such as malabsorption (Intestine, small, resection of, DC 7328), diarrhea (Irritable bowel syndrome, DC 7319, or Crohn''s disease or undifferentiated form of inflammatory bowel disease, DC 7326), or diabetes (DC 7913), whichever provides the highest evaluation', true, 'SOURCE_CHECKED', NULL, ARRAY['src.ecfr.38_part4_2026_08_27']::text[], ARRAY['7303','7319','7326','7328','7347','7913']::text[]);
INSERT INTO ref.rating_code (code, name, body_system, subsection, cfr_section, notes, has_criteria, status, status_note, source_ids, cited_codes) VALUES ('7500', 'Kidney, removal', 'THE GENITOURINARY SYSTEM', NULL, '38 CFR 4.115b', 'Or rate as renal dysfunction if there is nephritis, infection, or pathology of the other.', true, 'SOURCE_CHECKED', NULL, ARRAY['src.ecfr.38_part4_2026_08_27']::text[], '{}'::text[]);
INSERT INTO ref.rating_code (code, name, body_system, subsection, cfr_section, notes, has_criteria, status, status_note, source_ids, cited_codes) VALUES ('7501', 'Kidney, abscess', 'THE GENITOURINARY SYSTEM', NULL, '38 CFR 4.115b', 'Rate as urinary tract infection', false, 'SOURCE_CHECKED', NULL, ARRAY['src.ecfr.38_part4_2026_08_27']::text[], '{}'::text[]);
INSERT INTO ref.rating_code (code, name, body_system, subsection, cfr_section, notes, has_criteria, status, status_note, source_ids, cited_codes) VALUES ('7502', 'Nephritis, chronic', 'THE GENITOURINARY SYSTEM', NULL, '38 CFR 4.115b', 'Rate as renal dysfunction.', false, 'SOURCE_CHECKED', NULL, ARRAY['src.ecfr.38_part4_2026_08_27']::text[], '{}'::text[]);
INSERT INTO ref.rating_code (code, name, body_system, subsection, cfr_section, notes, has_criteria, status, status_note, source_ids, cited_codes) VALUES ('7504', 'Pyelonephritis, chronic', 'THE GENITOURINARY SYSTEM', NULL, '38 CFR 4.115b', 'Rate as renal dysfunction or urinary tract infection, whichever is predominant.', false, 'SOURCE_CHECKED', NULL, ARRAY['src.ecfr.38_part4_2026_08_27']::text[], '{}'::text[]);
INSERT INTO ref.rating_code (code, name, body_system, subsection, cfr_section, notes, has_criteria, status, status_note, source_ids, cited_codes) VALUES ('7505', 'Kidney, tuberculosis', 'THE GENITOURINARY SYSTEM', NULL, '38 CFR 4.115b', 'Rate in accordance with §§ 4.88b or 4.89, whichever is appropriate.', false, 'SOURCE_CHECKED', NULL, ARRAY['src.ecfr.38_part4_2026_08_27']::text[], '{}'::text[]);
INSERT INTO ref.rating_code (code, name, body_system, subsection, cfr_section, notes, has_criteria, status, status_note, source_ids, cited_codes) VALUES ('7507', 'Nephrosclerosis, arteriolar', 'THE GENITOURINARY SYSTEM', NULL, '38 CFR 4.115b', 'Rate according to predominant symptoms as renal dysfunction, hypertension or heart disease. If rated under the cardiovascular schedule, however, the percentage rating which would otherwise be assigned will be elevated to the next higher evaluation.', false, 'SOURCE_CHECKED', NULL, ARRAY['src.ecfr.38_part4_2026_08_27']::text[], '{}'::text[]);
INSERT INTO ref.rating_code (code, name, body_system, subsection, cfr_section, notes, has_criteria, status, status_note, source_ids, cited_codes) VALUES ('7508', 'Nephrolithiasis/Ureterolithiasis/Nephrocalcinosis', 'THE GENITOURINARY SYSTEM', NULL, '38 CFR 4.115b', NULL, true, 'SOURCE_CHECKED', NULL, ARRAY['src.ecfr.38_part4_2026_08_27']::text[], '{}'::text[]);
INSERT INTO ref.rating_code (code, name, body_system, subsection, cfr_section, notes, has_criteria, status, status_note, source_ids, cited_codes) VALUES ('7509', 'Hydronephrosis', 'THE GENITOURINARY SYSTEM', NULL, '38 CFR 4.115b', 'Severe; Rate as renal dysfunction.', true, 'SOURCE_CHECKED', NULL, ARRAY['src.ecfr.38_part4_2026_08_27']::text[], '{}'::text[]);
INSERT INTO ref.rating_code (code, name, body_system, subsection, cfr_section, notes, has_criteria, status, status_note, source_ids, cited_codes) VALUES ('7510', 'Ureterolithiasis', 'THE GENITOURINARY SYSTEM', NULL, '38 CFR 4.115b', NULL, false, 'SUPERSEDED', 'Removed from 38 CFR Part 4 (Appendix A: Evaluation February 17, 1994; removed November 14, 2021). Name as it stood in the 2020 edition.', ARRAY['src.ecfr.38_part4_2026_08_27']::text[], '{}'::text[]);
INSERT INTO ref.rating_code (code, name, body_system, subsection, cfr_section, notes, has_criteria, status, status_note, source_ids, cited_codes) VALUES ('7511', 'Ureter, stricture', 'THE GENITOURINARY SYSTEM', NULL, '38 CFR 4.115b', 'Rate as hydronephrosis, except for recurrent stone formation requiring one or more of the following:', true, 'SOURCE_CHECKED', NULL, ARRAY['src.ecfr.38_part4_2026_08_27']::text[], '{}'::text[]);
INSERT INTO ref.rating_code (code, name, body_system, subsection, cfr_section, notes, has_criteria, status, status_note, source_ids, cited_codes) VALUES ('7512', 'Cystitis, chronic', 'THE GENITOURINARY SYSTEM', NULL, '38 CFR 4.115b', 'Rate as voiding dysfunction.', false, 'SOURCE_CHECKED', NULL, ARRAY['src.ecfr.38_part4_2026_08_27']::text[], '{}'::text[]);
INSERT INTO ref.rating_code (code, name, body_system, subsection, cfr_section, notes, has_criteria, status, status_note, source_ids, cited_codes) VALUES ('7515', 'Bladder, calculus', 'THE GENITOURINARY SYSTEM', NULL, '38 CFR 4.115b', 'Rate as voiding dysfunction', false, 'SOURCE_CHECKED', NULL, ARRAY['src.ecfr.38_part4_2026_08_27']::text[], '{}'::text[]);
INSERT INTO ref.rating_code (code, name, body_system, subsection, cfr_section, notes, has_criteria, status, status_note, source_ids, cited_codes) VALUES ('7516', 'Bladder, fistula', 'THE GENITOURINARY SYSTEM', NULL, '38 CFR 4.115b', 'Rate as voiding dysfunction or urinary tract infection, whichever is predominant.', true, 'SOURCE_CHECKED', NULL, ARRAY['src.ecfr.38_part4_2026_08_27']::text[], '{}'::text[]);
INSERT INTO ref.rating_code (code, name, body_system, subsection, cfr_section, notes, has_criteria, status, status_note, source_ids, cited_codes) VALUES ('7517', 'Bladder, injury', 'THE GENITOURINARY SYSTEM', NULL, '38 CFR 4.115b', 'Rate as voiding dysfunction.', false, 'SOURCE_CHECKED', NULL, ARRAY['src.ecfr.38_part4_2026_08_27']::text[], '{}'::text[]);
INSERT INTO ref.rating_code (code, name, body_system, subsection, cfr_section, notes, has_criteria, status, status_note, source_ids, cited_codes) VALUES ('7518', 'Urethra, stricture', 'THE GENITOURINARY SYSTEM', NULL, '38 CFR 4.115b', 'Rate as voiding dysfunction.', false, 'SOURCE_CHECKED', NULL, ARRAY['src.ecfr.38_part4_2026_08_27']::text[], '{}'::text[]);
INSERT INTO ref.rating_code (code, name, body_system, subsection, cfr_section, notes, has_criteria, status, status_note, source_ids, cited_codes) VALUES ('7519', 'Urethra, fistula', 'THE GENITOURINARY SYSTEM', NULL, '38 CFR 4.115b', 'Rate as voiding dysfunction.', true, 'SOURCE_CHECKED', NULL, ARRAY['src.ecfr.38_part4_2026_08_27']::text[], '{}'::text[]);
INSERT INTO ref.rating_code (code, name, body_system, subsection, cfr_section, notes, has_criteria, status, status_note, source_ids, cited_codes) VALUES ('7520', 'Penis, removal of half or more', 'THE GENITOURINARY SYSTEM', NULL, '38 CFR 4.115b', NULL, true, 'SOURCE_CHECKED', NULL, ARRAY['src.ecfr.38_part4_2026_08_27']::text[], '{}'::text[]);
INSERT INTO ref.rating_code (code, name, body_system, subsection, cfr_section, notes, has_criteria, status, status_note, source_ids, cited_codes) VALUES ('7521', 'Penis, removal of glans', 'THE GENITOURINARY SYSTEM', NULL, '38 CFR 4.115b', NULL, true, 'SOURCE_CHECKED', NULL, ARRAY['src.ecfr.38_part4_2026_08_27']::text[], '{}'::text[]);
INSERT INTO ref.rating_code (code, name, body_system, subsection, cfr_section, notes, has_criteria, status, status_note, source_ids, cited_codes) VALUES ('7522', 'Erectile dysfunction, with or without penile deformity', 'THE GENITOURINARY SYSTEM', NULL, '38 CFR 4.115b', 'Note: For the purpose of VA disability evaluation, a disease or traumatic injury of the penis resulting in scarring or deformity shall be rated under diagnostic code 7522.', true, 'SOURCE_CHECKED', NULL, ARRAY['src.ecfr.38_part4_2026_08_27']::text[], '{}'::text[]);
INSERT INTO ref.rating_code (code, name, body_system, subsection, cfr_section, notes, has_criteria, status, status_note, source_ids, cited_codes) VALUES ('7523', 'Testis, atrophy, complete', 'THE GENITOURINARY SYSTEM', NULL, '38 CFR 4.115b', NULL, true, 'SOURCE_CHECKED', NULL, ARRAY['src.ecfr.38_part4_2026_08_27']::text[], '{}'::text[]);
INSERT INTO ref.rating_code (code, name, body_system, subsection, cfr_section, notes, has_criteria, status, status_note, source_ids, cited_codes) VALUES ('7524', 'Testis, removal', 'THE GENITOURINARY SYSTEM', NULL, '38 CFR 4.115b', 'Note: In cases of the removal of one testis as the result of a service-incurred injury or disease, other than an undescended or congenitally undeveloped testis, with the absence or nonfunctioning of the other testis unrelated to service, an evaluation of 30 percent will be assigned for the service-connected testicular loss. Testis, undescended, or congenitally undeveloped is not a ratable disability.', true, 'SOURCE_CHECKED', NULL, ARRAY['src.ecfr.38_part4_2026_08_27']::text[], '{}'::text[]);
INSERT INTO ref.rating_code (code, name, body_system, subsection, cfr_section, notes, has_criteria, status, status_note, source_ids, cited_codes) VALUES ('7525', 'Prostatitis, urethritis, epididymitis, orchitis (unilateral or bilateral), chronic only', 'THE GENITOURINARY SYSTEM', NULL, '38 CFR 4.115b', 'Rate as urinary tract infection. For tubercular infections: Rate in accordance with §§ 4.88b or 4.89, whichever is appropriate.', false, 'SOURCE_CHECKED', NULL, ARRAY['src.ecfr.38_part4_2026_08_27']::text[], '{}'::text[]);
INSERT INTO ref.rating_code (code, name, body_system, subsection, cfr_section, notes, has_criteria, status, status_note, source_ids, cited_codes) VALUES ('7527', 'Prostate gland injuries, infections, hypertrophy, postoperative residuals, bladder outlet obstruction', 'THE GENITOURINARY SYSTEM', NULL, '38 CFR 4.115b', 'Rate as voiding dysfunction or urinary tract infection, whichever is predominant.', false, 'SOURCE_CHECKED', NULL, ARRAY['src.ecfr.38_part4_2026_08_27']::text[], '{}'::text[]);
INSERT INTO ref.rating_code (code, name, body_system, subsection, cfr_section, notes, has_criteria, status, status_note, source_ids, cited_codes) VALUES ('7528', 'Malignant neoplasms', 'THE GENITOURINARY SYSTEM', NULL, '38 CFR 4.115b', 'Note—Following the cessation of surgical, X-ray, antineoplastic chemotherapy or other therapeutic procedure, the rating of 100 percent shall continue with a mandatory VA examination at the expiration of six months. Any change in evaluation based upon that or any subsequent examination shall be subject to the provisions of § 3.105(e) of this chapter. If there has been no local reoccurrence or metastasis, rate on residuals as voiding dysfunction or renal dysfunction, whichever is predominant.', true, 'SOURCE_CHECKED', NULL, ARRAY['src.ecfr.38_part4_2026_08_27']::text[], '{}'::text[]);
INSERT INTO ref.rating_code (code, name, body_system, subsection, cfr_section, notes, has_criteria, status, status_note, source_ids, cited_codes) VALUES ('7529', 'Benign neoplasms', 'THE GENITOURINARY SYSTEM', NULL, '38 CFR 4.115b', 'Rate as voiding dysfunction or renal dysfunction, whichever is predominant.', false, 'SOURCE_CHECKED', NULL, ARRAY['src.ecfr.38_part4_2026_08_27']::text[], '{}'::text[]);
INSERT INTO ref.rating_code (code, name, body_system, subsection, cfr_section, notes, has_criteria, status, status_note, source_ids, cited_codes) VALUES ('7530', 'Renal disease, chronic', 'THE GENITOURINARY SYSTEM', NULL, '38 CFR 4.115b', 'Rate as renal dysfunction.', false, 'SOURCE_CHECKED', NULL, ARRAY['src.ecfr.38_part4_2026_08_27']::text[], '{}'::text[]);
INSERT INTO ref.rating_code (code, name, body_system, subsection, cfr_section, notes, has_criteria, status, status_note, source_ids, cited_codes) VALUES ('7531', 'Kidney transplant', 'THE GENITOURINARY SYSTEM', NULL, '38 CFR 4.115b', 'Note—The 100 percent evaluation shall be assigned as of the date of hospital admission for transplant surgery and shall continue with a mandatory VA examination one year following hospital discharge. Any change in evaluation based upon that or any subsequent examination shall be subject to the provisions of § 3.105(e) of this chapter.', true, 'SOURCE_CHECKED', NULL, ARRAY['src.ecfr.38_part4_2026_08_27']::text[], '{}'::text[]);
INSERT INTO ref.rating_code (code, name, body_system, subsection, cfr_section, notes, has_criteria, status, status_note, source_ids, cited_codes) VALUES ('7532', 'Renal tubular disorders', 'THE GENITOURINARY SYSTEM', NULL, '38 CFR 4.115b', 'Or rate as renal dysfunction.', true, 'SOURCE_CHECKED', NULL, ARRAY['src.ecfr.38_part4_2026_08_27']::text[], '{}'::text[]);
INSERT INTO ref.rating_code (code, name, body_system, subsection, cfr_section, notes, has_criteria, status, status_note, source_ids, cited_codes) VALUES ('7533', 'Cystic diseases of the kidneys', 'THE GENITOURINARY SYSTEM', NULL, '38 CFR 4.115b', 'Rate as renal dysfunction. Note: Cystic diseases of the kidneys include, but are not limited to, polycystic disease, uremic medullary cystic disease, medullary sponge kidney, and similar conditions such as Alport''s syndrome, cystinosis, primary oxalosis, and Fabry''s disease.', false, 'SOURCE_CHECKED', NULL, ARRAY['src.ecfr.38_part4_2026_08_27']::text[], '{}'::text[]);
INSERT INTO ref.rating_code (code, name, body_system, subsection, cfr_section, notes, has_criteria, status, status_note, source_ids, cited_codes) VALUES ('7534', 'Atherosclerotic renal disease (renal artery stenosis, atheroembolic renal disease, or large vessel disease, unspecified)', 'THE GENITOURINARY SYSTEM', NULL, '38 CFR 4.115b', 'Rate as renal dysfunction.', false, 'SOURCE_CHECKED', NULL, ARRAY['src.ecfr.38_part4_2026_08_27']::text[], '{}'::text[]);
INSERT INTO ref.rating_code (code, name, body_system, subsection, cfr_section, notes, has_criteria, status, status_note, source_ids, cited_codes) VALUES ('7535', 'Toxic nephropathy', 'THE GENITOURINARY SYSTEM', NULL, '38 CFR 4.115b', 'Rate as renal dysfunction.', false, 'SOURCE_CHECKED', NULL, ARRAY['src.ecfr.38_part4_2026_08_27']::text[], '{}'::text[]);
INSERT INTO ref.rating_code (code, name, body_system, subsection, cfr_section, notes, has_criteria, status, status_note, source_ids, cited_codes) VALUES ('7536', 'Glomerulonephritis', 'THE GENITOURINARY SYSTEM', NULL, '38 CFR 4.115b', 'Rate as renal dysfunction.', false, 'SOURCE_CHECKED', NULL, ARRAY['src.ecfr.38_part4_2026_08_27']::text[], '{}'::text[]);
INSERT INTO ref.rating_code (code, name, body_system, subsection, cfr_section, notes, has_criteria, status, status_note, source_ids, cited_codes) VALUES ('7537', 'Interstitial nephritis, including gouty nephropathy, disorders of calcium metabolism', 'THE GENITOURINARY SYSTEM', NULL, '38 CFR 4.115b', 'Rate as renal dysfunction.', false, 'SOURCE_CHECKED', NULL, ARRAY['src.ecfr.38_part4_2026_08_27']::text[], '{}'::text[]);
INSERT INTO ref.rating_code (code, name, body_system, subsection, cfr_section, notes, has_criteria, status, status_note, source_ids, cited_codes) VALUES ('7538', 'Papillary necrosis', 'THE GENITOURINARY SYSTEM', NULL, '38 CFR 4.115b', 'Rate as renal dysfunction.', false, 'SOURCE_CHECKED', NULL, ARRAY['src.ecfr.38_part4_2026_08_27']::text[], '{}'::text[]);
INSERT INTO ref.rating_code (code, name, body_system, subsection, cfr_section, notes, has_criteria, status, status_note, source_ids, cited_codes) VALUES ('7539', 'Renal amyloid disease', 'THE GENITOURINARY SYSTEM', NULL, '38 CFR 4.115b', 'Rate as renal dysfunction. Note: This diagnostic code pertains to renal involvement secondary to all glomerulonephritis conditions, all vasculitis conditions and their derivatives, and other renal conditions caused by systemic diseases, such as Lupus erythematosus, systemic lupus erythematosus nephritis, Henoch-Schonlein syndrome, scleroderma, hemolytic uremic syndrome, polyarthritis, Wegener''s granulomatosis, Goodpasture''s syndrome, and sickle cell disease.', false, 'SOURCE_CHECKED', NULL, ARRAY['src.ecfr.38_part4_2026_08_27']::text[], '{}'::text[]);
INSERT INTO ref.rating_code (code, name, body_system, subsection, cfr_section, notes, has_criteria, status, status_note, source_ids, cited_codes) VALUES ('7540', 'Disseminated intravascular coagulation', 'THE GENITOURINARY SYSTEM', NULL, '38 CFR 4.115b', 'Rate as renal dysfunction.', false, 'SOURCE_CHECKED', NULL, ARRAY['src.ecfr.38_part4_2026_08_27']::text[], '{}'::text[]);
INSERT INTO ref.rating_code (code, name, body_system, subsection, cfr_section, notes, has_criteria, status, status_note, source_ids, cited_codes) VALUES ('7541', 'Renal involvement in diabetes mellitus type I or II', 'THE GENITOURINARY SYSTEM', NULL, '38 CFR 4.115b', 'Rate as renal dysfunction.', false, 'SOURCE_CHECKED', NULL, ARRAY['src.ecfr.38_part4_2026_08_27']::text[], '{}'::text[]);
INSERT INTO ref.rating_code (code, name, body_system, subsection, cfr_section, notes, has_criteria, status, status_note, source_ids, cited_codes) VALUES ('7542', 'Neurogenic bladder', 'THE GENITOURINARY SYSTEM', NULL, '38 CFR 4.115b', 'Rate as voiding dysfunction or urinary tract infection, whichever is predominant.', false, 'SOURCE_CHECKED', NULL, ARRAY['src.ecfr.38_part4_2026_08_27']::text[], '{}'::text[]);
INSERT INTO ref.rating_code (code, name, body_system, subsection, cfr_section, notes, has_criteria, status, status_note, source_ids, cited_codes) VALUES ('7543', 'Varicocele/Hydrocele', 'THE GENITOURINARY SYSTEM', NULL, '38 CFR 4.115b', NULL, true, 'SOURCE_CHECKED', NULL, ARRAY['src.ecfr.38_part4_2026_08_27']::text[], '{}'::text[]);
INSERT INTO ref.rating_code (code, name, body_system, subsection, cfr_section, notes, has_criteria, status, status_note, source_ids, cited_codes) VALUES ('7544', 'Renal disease caused by viral infection such as HIV, Hepatitis B, and Hepatitis C', 'THE GENITOURINARY SYSTEM', NULL, '38 CFR 4.115b', 'Rate as renal dysfunction.', false, 'SOURCE_CHECKED', NULL, ARRAY['src.ecfr.38_part4_2026_08_27']::text[], '{}'::text[]);
INSERT INTO ref.rating_code (code, name, body_system, subsection, cfr_section, notes, has_criteria, status, status_note, source_ids, cited_codes) VALUES ('7545', 'Bladder, diverticulum of', 'THE GENITOURINARY SYSTEM', NULL, '38 CFR 4.115b', 'Rate as voiding dysfunction or urinary tract infection, whichever is predominant.', false, 'SOURCE_CHECKED', NULL, ARRAY['src.ecfr.38_part4_2026_08_27']::text[], '{}'::text[]);
INSERT INTO ref.rating_code (code, name, body_system, subsection, cfr_section, notes, has_criteria, status, status_note, source_ids, cited_codes) VALUES ('7610', 'Vulva or clitoris, disease or injury of (including vulvovaginitis)', 'GYNECOLOGICAL CONDITIONS AND DISORDERS OF THE BREAST', NULL, '38 CFR 4.116', NULL, false, 'SOURCE_CHECKED', NULL, ARRAY['src.ecfr.38_part4_2026_08_27']::text[], '{}'::text[]);
INSERT INTO ref.rating_code (code, name, body_system, subsection, cfr_section, notes, has_criteria, status, status_note, source_ids, cited_codes) VALUES ('7611', 'Vagina, disease or injury', 'GYNECOLOGICAL CONDITIONS AND DISORDERS OF THE BREAST', NULL, '38 CFR 4.116', NULL, false, 'SOURCE_CHECKED', NULL, ARRAY['src.ecfr.38_part4_2026_08_27']::text[], '{}'::text[]);
INSERT INTO ref.rating_code (code, name, body_system, subsection, cfr_section, notes, has_criteria, status, status_note, source_ids, cited_codes) VALUES ('7612', 'Cervix, disease or injury', 'GYNECOLOGICAL CONDITIONS AND DISORDERS OF THE BREAST', NULL, '38 CFR 4.116', NULL, false, 'SOURCE_CHECKED', NULL, ARRAY['src.ecfr.38_part4_2026_08_27']::text[], '{}'::text[]);
INSERT INTO ref.rating_code (code, name, body_system, subsection, cfr_section, notes, has_criteria, status, status_note, source_ids, cited_codes) VALUES ('7613', 'Uterus, disease or injury', 'GYNECOLOGICAL CONDITIONS AND DISORDERS OF THE BREAST', NULL, '38 CFR 4.116', NULL, false, 'SOURCE_CHECKED', NULL, ARRAY['src.ecfr.38_part4_2026_08_27']::text[], '{}'::text[]);
INSERT INTO ref.rating_code (code, name, body_system, subsection, cfr_section, notes, has_criteria, status, status_note, source_ids, cited_codes) VALUES ('7614', 'Fallopian tube, disease or injury', 'GYNECOLOGICAL CONDITIONS AND DISORDERS OF THE BREAST', NULL, '38 CFR 4.116', NULL, false, 'SOURCE_CHECKED', NULL, ARRAY['src.ecfr.38_part4_2026_08_27']::text[], '{}'::text[]);
INSERT INTO ref.rating_code (code, name, body_system, subsection, cfr_section, notes, has_criteria, status, status_note, source_ids, cited_codes) VALUES ('7615', 'Ovary, disease or injury', 'GYNECOLOGICAL CONDITIONS AND DISORDERS OF THE BREAST', NULL, '38 CFR 4.116', NULL, false, 'SOURCE_CHECKED', NULL, ARRAY['src.ecfr.38_part4_2026_08_27']::text[], '{}'::text[]);
INSERT INTO ref.rating_code (code, name, body_system, subsection, cfr_section, notes, has_criteria, status, status_note, source_ids, cited_codes) VALUES ('7617', 'Uterus and both ovaries, removal', 'GYNECOLOGICAL CONDITIONS AND DISORDERS OF THE BREAST', NULL, '38 CFR 4.116', NULL, true, 'SOURCE_CHECKED', NULL, ARRAY['src.ecfr.38_part4_2026_08_27']::text[], '{}'::text[]);
INSERT INTO ref.rating_code (code, name, body_system, subsection, cfr_section, notes, has_criteria, status, status_note, source_ids, cited_codes) VALUES ('7618', 'Uterus, removal', 'GYNECOLOGICAL CONDITIONS AND DISORDERS OF THE BREAST', NULL, '38 CFR 4.116', NULL, true, 'SOURCE_CHECKED', NULL, ARRAY['src.ecfr.38_part4_2026_08_27']::text[], '{}'::text[]);
INSERT INTO ref.rating_code (code, name, body_system, subsection, cfr_section, notes, has_criteria, status, status_note, source_ids, cited_codes) VALUES ('7619', 'Ovary, removal', 'GYNECOLOGICAL CONDITIONS AND DISORDERS OF THE BREAST', NULL, '38 CFR 4.116', 'Note: In cases of the removal of one ovary as the result of a service-connected injury or disease, with the absence or nonfunctioning of a second ovary unrelated to service, an evaluation of 30 percent will be assigned for the service-connected ovarian loss', true, 'SOURCE_CHECKED', NULL, ARRAY['src.ecfr.38_part4_2026_08_27']::text[], '{}'::text[]);
INSERT INTO ref.rating_code (code, name, body_system, subsection, cfr_section, notes, has_criteria, status, status_note, source_ids, cited_codes) VALUES ('7620', 'Ovaries, atrophy of both', 'GYNECOLOGICAL CONDITIONS AND DISORDERS OF THE BREAST', NULL, '38 CFR 4.116', NULL, true, 'SOURCE_CHECKED', NULL, ARRAY['src.ecfr.38_part4_2026_08_27']::text[], '{}'::text[]);
INSERT INTO ref.rating_code (code, name, body_system, subsection, cfr_section, notes, has_criteria, status, status_note, source_ids, cited_codes) VALUES ('7621', 'Complete or incomplete pelvic organ prolapse due to injury or disease or surgical complications of pregnancy', 'GYNECOLOGICAL CONDITIONS AND DISORDERS OF THE BREAST', NULL, '38 CFR 4.116', 'Note: Pelvic organ prolapse occurs when a pelvic organ such as bladder, urethra, uterus, vagina, small bowel, or rectum drops (prolapse) from its normal place in the abdomen. Conditions associated with pelvic organ prolapse include: uterine or vaginal vault prolapse, cystocele, urethrocele, rectocele, enterocele, or any combination thereof. Evaluate pelvic organ prolapse under DC 7621. Evaluate separately any genitourinary, digestive, or skin symptoms under the appropriate diagnostic code(s) and combine all evaluations with the 10 percent evaluation under DC 7621', true, 'SOURCE_CHECKED', NULL, ARRAY['src.ecfr.38_part4_2026_08_27']::text[], '{}'::text[]);
INSERT INTO ref.rating_code (code, name, body_system, subsection, cfr_section, notes, has_criteria, status, status_note, source_ids, cited_codes) VALUES ('7624', 'Fistula, rectovaginal', 'GYNECOLOGICAL CONDITIONS AND DISORDERS OF THE BREAST', NULL, '38 CFR 4.116', NULL, true, 'SOURCE_CHECKED', NULL, ARRAY['src.ecfr.38_part4_2026_08_27']::text[], '{}'::text[]);
INSERT INTO ref.rating_code (code, name, body_system, subsection, cfr_section, notes, has_criteria, status, status_note, source_ids, cited_codes) VALUES ('7625', 'Fistula, urethrovaginal', 'GYNECOLOGICAL CONDITIONS AND DISORDERS OF THE BREAST', NULL, '38 CFR 4.116', NULL, true, 'SOURCE_CHECKED', NULL, ARRAY['src.ecfr.38_part4_2026_08_27']::text[], '{}'::text[]);
INSERT INTO ref.rating_code (code, name, body_system, subsection, cfr_section, notes, has_criteria, status, status_note, source_ids, cited_codes) VALUES ('7626', 'Breast, surgery', 'GYNECOLOGICAL CONDITIONS AND DISORDERS OF THE BREAST', NULL, '38 CFR 4.116', 'Note: For VA purposes: (1) Radical mastectomy means removal of the entire breast, underlying pectoral muscles, and regional lymph nodes up to the coracoclavicular ligament. (2) Modified radical mastectomy means removal of the entire breast and axillary lymph nodes (in continuity with the breast). Pectoral muscles are left intact. (3) Simple (or total) mastectomy means removal of all of the breast tissue, nipple, and a small portion of the overlying skin, but lymph nodes and muscles are left intact. (4) Wide local excision (including partial mastectomy, lumpectomy, tylectomy, segmentectomy, and quadrantectomy) means removal of a portion of the breast tissue.', true, 'SOURCE_CHECKED', NULL, ARRAY['src.ecfr.38_part4_2026_08_27']::text[], '{}'::text[]);
INSERT INTO ref.rating_code (code, name, body_system, subsection, cfr_section, notes, has_criteria, status, status_note, source_ids, cited_codes) VALUES ('7627', 'Malignant neoplasms of gynecological system', 'GYNECOLOGICAL CONDITIONS AND DISORDERS OF THE BREAST', NULL, '38 CFR 4.116', 'Note: A rating of 100 percent shall continue beyond the cessation of any surgical, radiation, antineoplastic chemotherapy or other therapeutic procedures. Six months after discontinuance of such treatment, the appropriate disability rating shall be determined by mandatory VA examination. Any change in evaluation based upon that or any subsequent examination shall be subject to the provisions of § 3.105(e) of this chapter. Rate chronic residuals to include scars, lymphedema, disfigurement, and/or other impairment of function under the appropriate diagnostic code(s) within the appropriate body system', true, 'SOURCE_CHECKED', NULL, ARRAY['src.ecfr.38_part4_2026_08_27']::text[], '{}'::text[]);
INSERT INTO ref.rating_code (code, name, body_system, subsection, cfr_section, notes, has_criteria, status, status_note, source_ids, cited_codes) VALUES ('7628', 'Benign neoplasms of gynecological system', 'GYNECOLOGICAL CONDITIONS AND DISORDERS OF THE BREAST', NULL, '38 CFR 4.116', 'Rate chronic residuals to include scars, lymphedema, disfigurement, and/or other impairment of function under the appropriate diagnostic code(s) within the appropriate body system', false, 'SOURCE_CHECKED', NULL, ARRAY['src.ecfr.38_part4_2026_08_27']::text[], '{}'::text[]);
INSERT INTO ref.rating_code (code, name, body_system, subsection, cfr_section, notes, has_criteria, status, status_note, source_ids, cited_codes) VALUES ('7629', 'Endometriosis', 'GYNECOLOGICAL CONDITIONS AND DISORDERS OF THE BREAST', NULL, '38 CFR 4.116', 'Note: Diagnosis of endometriosis must be substantiated by laparoscopy.', true, 'SOURCE_CHECKED', NULL, ARRAY['src.ecfr.38_part4_2026_08_27']::text[], '{}'::text[]);
INSERT INTO ref.rating_code (code, name, body_system, subsection, cfr_section, notes, has_criteria, status, status_note, source_ids, cited_codes) VALUES ('7630', 'Malignant neoplasms of the breast', 'GYNECOLOGICAL CONDITIONS AND DISORDERS OF THE BREAST', NULL, '38 CFR 4.116', 'Note: A rating of 100 percent shall continue beyond the cessation of any surgical, radiation, antineoplastic chemotherapy or other therapeutic procedure. Six months after discontinuance of such treatment, the appropriate disability rating shall be determined by mandatory VA examination. Any change in evaluation based upon that or any subsequent examination shall be subject to the provisions of § 3.105(e) of this chapter. Rate chronic residuals according to impairment of function due to scars, lymphedema, or disfigurement (e.g., limitation of arm, shoulder, and wrist motion, or loss of grip strength, or loss of sensation, or residuals from harvesting of muscles for reconstructive purposes), and/or under diagnostic code 7626', true, 'SOURCE_CHECKED', NULL, ARRAY['src.ecfr.38_part4_2026_08_27']::text[], ARRAY['7626']::text[]);
INSERT INTO ref.rating_code (code, name, body_system, subsection, cfr_section, notes, has_criteria, status, status_note, source_ids, cited_codes) VALUES ('7631', 'Benign neoplasms of the breast and other injuries of the breast', 'GYNECOLOGICAL CONDITIONS AND DISORDERS OF THE BREAST', NULL, '38 CFR 4.116', 'Rate chronic residuals according to impairment of function due to scars, lymphedema, or disfigurement (e.g., limitation of arm, shoulder, and wrist motion, or loss of grip strength, or loss of sensation, or residuals from harvesting of muscles for reconstructive purposes), and/or under diagnostic code 7626', false, 'SOURCE_CHECKED', NULL, ARRAY['src.ecfr.38_part4_2026_08_27']::text[], ARRAY['7626']::text[]);
INSERT INTO ref.rating_code (code, name, body_system, subsection, cfr_section, notes, has_criteria, status, status_note, source_ids, cited_codes) VALUES ('7632', 'Female sexual arousal disorder (FSAD)', 'GYNECOLOGICAL CONDITIONS AND DISORDERS OF THE BREAST', NULL, '38 CFR 4.116', NULL, true, 'SOURCE_CHECKED', NULL, ARRAY['src.ecfr.38_part4_2026_08_27']::text[], '{}'::text[]);
INSERT INTO ref.rating_code (code, name, body_system, subsection, cfr_section, notes, has_criteria, status, status_note, source_ids, cited_codes) VALUES ('7702', 'Agranulocytosis, acquired', 'THE HEMATOLOGIC AND LYMPHATIC SYSTEMS', NULL, '38 CFR 4.117', 'Note: A 100 percent evaluation for bone marrow transplant shall be assigned as of the date of hospital admission and shall continue with a mandatory VA examination six months following hospital discharge. Any change in evaluation based upon that or any subsequent examination shall be subject to the provisions of § 3.105(e) of this chapter', true, 'SOURCE_CHECKED', NULL, ARRAY['src.ecfr.38_part4_2026_08_27']::text[], '{}'::text[]);
INSERT INTO ref.rating_code (code, name, body_system, subsection, cfr_section, notes, has_criteria, status, status_note, source_ids, cited_codes) VALUES ('7703', 'Leukemia', 'THE HEMATOLOGIC AND LYMPHATIC SYSTEMS', NULL, '38 CFR 4.117', NULL, true, 'SOURCE_CHECKED', NULL, ARRAY['src.ecfr.38_part4_2026_08_27']::text[], '{}'::text[]);
INSERT INTO ref.rating_code (code, name, body_system, subsection, cfr_section, notes, has_criteria, status, status_note, source_ids, cited_codes) VALUES ('7704', 'Polycythemia vera', 'THE HEMATOLOGIC AND LYMPHATIC SYSTEMS', NULL, '38 CFR 4.117', NULL, true, 'SOURCE_CHECKED', NULL, ARRAY['src.ecfr.38_part4_2026_08_27']::text[], '{}'::text[]);
INSERT INTO ref.rating_code (code, name, body_system, subsection, cfr_section, notes, has_criteria, status, status_note, source_ids, cited_codes) VALUES ('7705', 'Immune thrombocytopenia', 'THE HEMATOLOGIC AND LYMPHATIC SYSTEMS', NULL, '38 CFR 4.117', NULL, true, 'SOURCE_CHECKED', NULL, ARRAY['src.ecfr.38_part4_2026_08_27']::text[], '{}'::text[]);
INSERT INTO ref.rating_code (code, name, body_system, subsection, cfr_section, notes, has_criteria, status, status_note, source_ids, cited_codes) VALUES ('7706', 'Splenectomy', 'THE HEMATOLOGIC AND LYMPHATIC SYSTEMS', NULL, '38 CFR 4.117', NULL, true, 'SOURCE_CHECKED', NULL, ARRAY['src.ecfr.38_part4_2026_08_27']::text[], '{}'::text[]);
INSERT INTO ref.rating_code (code, name, body_system, subsection, cfr_section, notes, has_criteria, status, status_note, source_ids, cited_codes) VALUES ('7707', 'Spleen, injury of, healed', 'THE HEMATOLOGIC AND LYMPHATIC SYSTEMS', NULL, '38 CFR 4.117', 'Rate for any residuals.', false, 'SOURCE_CHECKED', NULL, ARRAY['src.ecfr.38_part4_2026_08_27']::text[], '{}'::text[]);
INSERT INTO ref.rating_code (code, name, body_system, subsection, cfr_section, notes, has_criteria, status, status_note, source_ids, cited_codes) VALUES ('7709', 'Hodgkin''s lymphoma', 'THE HEMATOLOGIC AND LYMPHATIC SYSTEMS', NULL, '38 CFR 4.117', 'Note: A 100 percent evaluation shall continue beyond the cessation of any surgical therapy, radiation therapy, antineoplastic chemotherapy, or other therapeutic procedures. Six months after discontinuance of such treatment, the appropriate disability rating shall be determined by mandatory VA examination. Any reduction in evaluation based upon that or any subsequent examination shall be subject to the provisions of § 3.105(e) of this chapter. If there has been no local recurrence or metastasis, rate on residuals under the appropriate diagnostic code(s)', true, 'SOURCE_CHECKED', NULL, ARRAY['src.ecfr.38_part4_2026_08_27']::text[], '{}'::text[]);
INSERT INTO ref.rating_code (code, name, body_system, subsection, cfr_section, notes, has_criteria, status, status_note, source_ids, cited_codes) VALUES ('7710', 'Adenitis, tuberculous', 'THE HEMATOLOGIC AND LYMPHATIC SYSTEMS', NULL, '38 CFR 4.117', 'Rate under § 4.88c or 4.89 of this part, whichever is appropriate', false, 'SOURCE_CHECKED', NULL, ARRAY['src.ecfr.38_part4_2026_08_27']::text[], '{}'::text[]);
INSERT INTO ref.rating_code (code, name, body_system, subsection, cfr_section, notes, has_criteria, status, status_note, source_ids, cited_codes) VALUES ('7712', 'Multiple myeloma', 'THE HEMATOLOGIC AND LYMPHATIC SYSTEMS', NULL, '38 CFR 4.117', NULL, true, 'SOURCE_CHECKED', NULL, ARRAY['src.ecfr.38_part4_2026_08_27']::text[], '{}'::text[]);
