INSERT INTO ref.rating_code (code, name, body_system, subsection, cfr_section, notes, has_criteria, status, status_note, source_ids, cited_codes) VALUES ('7717', 'AL amyloidosis (primary amyloidosis)', 'THE HEMATOLOGIC AND LYMPHATIC SYSTEMS', NULL, '38 CFR 4.117', NULL, true, 'SOURCE_CHECKED', NULL, ARRAY['src.ecfr.38_part4_2026_08_27']::text[], '{}'::text[]);
INSERT INTO ref.rating_code (code, name, body_system, subsection, cfr_section, notes, has_criteria, status, status_note, source_ids, cited_codes) VALUES ('7718', 'Essential thrombocythemia and primary myelofibrosis', 'THE HEMATOLOGIC AND LYMPHATIC SYSTEMS', NULL, '38 CFR 4.117', 'Note (1): If the condition undergoes leukemic transformation, evaluate as leukemia under diagnostic code 7703. Note (2): A 100 percent evaluation shall be assigned as of the date of hospital admission for peripheral blood or bone marrow stem cell transplant; or during the period of treatment with chemotherapy (including myelosuppressants) or interferon treatment. Six months following hospital discharge or, in the case of chemotherapy treatment, six months after completion of treatment, the appropriate disability rating shall be determined by mandatory VA examination. Any reduction in evaluation based upon that or any subsequent examination shall be subject to the provisions of § 3.105(e) of this chapter.', true, 'SOURCE_CHECKED', NULL, ARRAY['src.ecfr.38_part4_2026_08_27']::text[], ARRAY['7703']::text[]);
INSERT INTO ref.rating_code (code, name, body_system, subsection, cfr_section, notes, has_criteria, status, status_note, source_ids, cited_codes) VALUES ('7719', 'Chronic myelogenous leukemia (CML) (chronic myeloid leukemia or chronic granulocytic leukemia)', 'THE HEMATOLOGIC AND LYMPHATIC SYSTEMS', NULL, '38 CFR 4.117', NULL, true, 'SOURCE_CHECKED', NULL, ARRAY['src.ecfr.38_part4_2026_08_27']::text[], '{}'::text[]);
