INSERT INTO ref.rating_code (code, name, body_system, subsection, cfr_section, notes, has_criteria, status, status_note, source_ids, cited_codes) VALUES ('7721', 'Folic acid deficiency', 'THE HEMATOLOGIC AND LYMPHATIC SYSTEMS', NULL, '38 CFR 4.117', NULL, true, 'SOURCE_CHECKED', NULL, ARRAY['src.ecfr.38_part4_2026_08_27']::text[], '{}'::text[]);
