INSERT INTO ref.rating_code (code, name, body_system, subsection, cfr_section, notes, has_criteria, status, status_note, source_ids, cited_codes) VALUES ('7724', 'Solitary plasmacytoma', 'THE HEMATOLOGIC AND LYMPHATIC SYSTEMS', NULL, '38 CFR 4.117', NULL, true, 'SOURCE_CHECKED', NULL, ARRAY['src.ecfr.38_part4_2026_08_27']::text[], '{}'::text[]);
INSERT INTO ref.rating_code (code, name, body_system, subsection, cfr_section, notes, has_criteria, status, status_note, source_ids, cited_codes) VALUES ('7725', 'Myelodysplastic syndromes', 'THE HEMATOLOGIC AND LYMPHATIC SYSTEMS', NULL, '38 CFR 4.117', NULL, true, 'SOURCE_CHECKED', NULL, ARRAY['src.ecfr.38_part4_2026_08_27']::text[], '{}'::text[]);
INSERT INTO ref.rating_code (code, name, body_system, subsection, cfr_section, notes, has_criteria, status, status_note, source_ids, cited_codes) VALUES ('7800', 'Burn scar(s) of the head, face, or neck; scar(s) of the head, face, or neck due to other causes; or other disfigurement of the head, face, or neck', 'THE SKIN', NULL, '38 CFR 4.118', 'Note (1): The 8 characteristics of disfigurement, for purposes of evaluation under § 4.118, are: Scar 5 or more inches (13 or more cm.) in length. Scar at least one-quarter inch (0.6 cm.) wide at widest part. Surface contour of scar elevated or depressed on palpation. Scar adherent to underlying tissue. Skin hypo-or hyper-pigmented in an area exceeding six square inches (39 sq. cm.). Skin texture abnormal (irregular, atrophic, shiny, scaly, etc.) in an area exceeding six square inches (39 sq. cm.). Underlying soft tissue missing in an area exceeding six square inches (39 sq. cm.). Skin indurated and inflexible in an area exceeding six square inches (39 sq. cm.). Note (2): Rate tissue loss of the auricle under DC 6207 (loss of auricle) and anatomical loss of the eye under DC 6061 (anatomical loss of both eyes) or DC 6063 (anatomical loss of one eye), as appropriate. Note (3): Take into consideration unretouched color photographs when evaluating under these criteria. Note (4): Separately evaluate disabling effects other than disfigurement that are associated with individual scar(s) of the head, face, or neck, such as pain, instability, and residuals of associated muscle or nerve injury, under the appropriate diagnostic code(s) and apply § 4.25 to combine the evaluation(s) with the evaluation assigned under this diagnostic code. Note (5): The characteristic(s) of disfigurement may be caused by one scar or by multiple scars; the characteristic(s) required to assign a particular evaluation need not be caused by a single scar in order to assign that evaluation. Note (3): Scars evaluated under diagnostic codes 7800, 7801, 7802, or 7805 may also receive an evaluation under this diagnostic code, when applicable', true, 'SOURCE_CHECKED', NULL, ARRAY['src.ecfr.38_part4_2026_08_27']::text[], ARRAY['6061','6063','6207','7801','7802','7805']::text[]);
INSERT INTO ref.rating_code (code, name, body_system, subsection, cfr_section, notes, has_criteria, status, status_note, source_ids, cited_codes) VALUES ('7801', 'Burn scar(s) or scar(s) due to other causes, not of the head, face, or neck that are associated with underlying soft tissue damage', 'THE SKIN', NULL, '38 CFR 4.118', 'Note (1): For the purposes of DCs 7801 and 7802, the six (6) zones of the body are defined as each extremity, anterior trunk, and posterior trunk. The midaxillary line divides the anterior trunk from the posterior trunk Note (2): A separate evaluation may be assigned for each affected zone of the body under this diagnostic code if there are multiple scars, or a single scar, affecting multiple zones of the body. Combine the separate evaluations under § 4.25. Alternatively, if a higher evaluation would result from adding the areas affected from multiple zones of the body, a single evaluation may also be assigned under this diagnostic code Note (3): Scars evaluated under diagnostic codes 7800, 7801, 7802, or 7805 may also receive an evaluation under this diagnostic code, when applicable', true, 'SOURCE_CHECKED', NULL, ARRAY['src.ecfr.38_part4_2026_08_27']::text[], ARRAY['7800','7802','7805']::text[]);
INSERT INTO ref.rating_code (code, name, body_system, subsection, cfr_section, notes, has_criteria, status, status_note, source_ids, cited_codes) VALUES ('7802', 'Burn scar(s) or scar(s) due to other causes, not of the head, face, or neck that are not associated with underlying soft tissue damage', 'THE SKIN', NULL, '38 CFR 4.118', 'Note (1): For the purposes of DCs 7801 and 7802, the six (6) zones of the body are defined as each extremity, anterior trunk, and posterior trunk. The midaxillary line divides the anterior trunk from the posterior trunk Note (2): A separate evaluation may be assigned for each affected zone of the body under this diagnostic code if there are multiple scars, or a single scar, affecting multiple zones of the body. Combine the separate evaluations under § 4.25. Alternatively, if a higher evaluation would result from adding the areas affected from multiple zones of the body, a single evaluation may also be assigned under this diagnostic code Note (3): Scars evaluated under diagnostic codes 7800, 7801, 7802, or 7805 may also receive an evaluation under this diagnostic code, when applicable', true, 'SOURCE_CHECKED', NULL, ARRAY['src.ecfr.38_part4_2026_08_27']::text[], ARRAY['7800','7801','7805']::text[]);
INSERT INTO ref.rating_code (code, name, body_system, subsection, cfr_section, notes, has_criteria, status, status_note, source_ids, cited_codes) VALUES ('7804', 'Scar(s), unstable or painful', 'THE SKIN', NULL, '38 CFR 4.118', 'Note (1): An unstable scar is one where, for any reason, there is frequent loss of covering of skin over the scar. Note (2): If one or more scars are both unstable and painful, add 10 percent to the evaluation that is based on the total number of unstable or painful scars Note (3): Scars evaluated under diagnostic codes 7800, 7801, 7802, or 7805 may also receive an evaluation under this diagnostic code, when applicable', true, 'SOURCE_CHECKED', NULL, ARRAY['src.ecfr.38_part4_2026_08_27']::text[], ARRAY['7800','7801','7802','7805']::text[]);
INSERT INTO ref.rating_code (code, name, body_system, subsection, cfr_section, notes, has_criteria, status, status_note, source_ids, cited_codes) VALUES ('7805', 'Scars, other; and other effects of scars evaluated under diagnostic codes 7800, 7801, 7802, or 7804', 'THE SKIN', NULL, '38 CFR 4.118', 'Scars, other; and other effects of scars evaluated under diagnostic codes 7800, 7801, 7802, or 7804: Evaluate any disabling effect(s) not considered in a rating provided under diagnostic codes 7800-04 under an appropriate diagnostic code', false, 'SOURCE_CHECKED', NULL, ARRAY['src.ecfr.38_part4_2026_08_27']::text[], ARRAY['7800','7801','7802','7804']::text[]);
INSERT INTO ref.rating_code (code, name, body_system, subsection, cfr_section, notes, has_criteria, status, status_note, source_ids, cited_codes) VALUES ('7806', 'Dermatitis or eczema', 'THE SKIN', NULL, '38 CFR 4.118', 'Evaluate under the General Rating Formula for the Skin', false, 'SOURCE_CHECKED', NULL, ARRAY['src.ecfr.38_part4_2026_08_27']::text[], '{}'::text[]);
INSERT INTO ref.rating_code (code, name, body_system, subsection, cfr_section, notes, has_criteria, status, status_note, source_ids, cited_codes) VALUES ('7807', 'Leishmaniasis, American (New World)', 'THE SKIN', NULL, '38 CFR 4.118', 'Rate as disfigurement of the head, face, or neck (DC 7800), scars (DC''s 7801, 7802, 7803, 7804, or 7805), or dermatitis (DC 7806), depending upon the predominant disability Note: Evaluate non-cutaneous (visceral) leishmaniasis under DC 6301 (visceral leishmaniasis).', false, 'SOURCE_CHECKED', NULL, ARRAY['src.ecfr.38_part4_2026_08_27']::text[], ARRAY['6301','7800','7801','7802','7804','7805','7806']::text[]);
INSERT INTO ref.rating_code (code, name, body_system, subsection, cfr_section, notes, has_criteria, status, status_note, source_ids, cited_codes) VALUES ('7808', 'Leishmaniasis, Old World', 'THE SKIN', NULL, '38 CFR 4.118', 'Rate as disfigurement of the head, face, or neck (DC 7800), scars (DC''s, 7801, 7802, 7803, 7804, or 7805), or dermatitis (DC 7806), depending upon the predominant disabililty Note: Evaluate non-cutaneous (visceral) leishmaniasis under DC 6301 (visceral leishmaniasis).', false, 'SOURCE_CHECKED', NULL, ARRAY['src.ecfr.38_part4_2026_08_27']::text[], ARRAY['6301','7800','7801','7802','7804','7805','7806']::text[]);
INSERT INTO ref.rating_code (code, name, body_system, subsection, cfr_section, notes, has_criteria, status, status_note, source_ids, cited_codes) VALUES ('7809', 'Discoid lupus erythematosus', 'THE SKIN', NULL, '38 CFR 4.118', 'Evaluate under the General Rating Formula for the Skin Note: Do not combine with ratings under DC 6350', false, 'SOURCE_CHECKED', NULL, ARRAY['src.ecfr.38_part4_2026_08_27']::text[], ARRAY['6350']::text[]);
INSERT INTO ref.rating_code (code, name, body_system, subsection, cfr_section, notes, has_criteria, status, status_note, source_ids, cited_codes) VALUES ('7811', 'Tuberculosis luposa (lupus vulgaris)', 'THE SKIN', NULL, '38 CFR 4.118', 'Rate under §§ 4.88c or 4.89, whichever is appropriate', false, 'SOURCE_CHECKED', NULL, ARRAY['src.ecfr.38_part4_2026_08_27']::text[], '{}'::text[]);
INSERT INTO ref.rating_code (code, name, body_system, subsection, cfr_section, notes, has_criteria, status, status_note, source_ids, cited_codes) VALUES ('7813', 'Dermatophytosis', 'THE SKIN', NULL, '38 CFR 4.118', 'Evaluate under the General Rating Formula for the Skin', false, 'SOURCE_CHECKED', NULL, ARRAY['src.ecfr.38_part4_2026_08_27']::text[], '{}'::text[]);
INSERT INTO ref.rating_code (code, name, body_system, subsection, cfr_section, notes, has_criteria, status, status_note, source_ids, cited_codes) VALUES ('7815', 'Bullous disorders', 'THE SKIN', NULL, '38 CFR 4.118', 'Evaluate under the General Rating Formula for the Skin Note: Rate complications and residuals of mucosal involvement (ocular, oral, gastrointestinal, respiratory, or genitourinary) separately under the appropriate diagnostic code', false, 'SOURCE_CHECKED', NULL, ARRAY['src.ecfr.38_part4_2026_08_27']::text[], '{}'::text[]);
INSERT INTO ref.rating_code (code, name, body_system, subsection, cfr_section, notes, has_criteria, status, status_note, source_ids, cited_codes) VALUES ('7816', 'Psoriasis', 'THE SKIN', NULL, '38 CFR 4.118', 'Evaluate under the General Rating Formula for the Skin Note: Rate complications such as psoriatic arthritis and other clinical manifestations (e.g., oral mucosa, nails) separately under the appropriate diagnostic code', false, 'SOURCE_CHECKED', NULL, ARRAY['src.ecfr.38_part4_2026_08_27']::text[], '{}'::text[]);
INSERT INTO ref.rating_code (code, name, body_system, subsection, cfr_section, notes, has_criteria, status, status_note, source_ids, cited_codes) VALUES ('7817', 'Erythroderma', 'THE SKIN', NULL, '38 CFR 4.118', 'Note: Treatment failure is defined as either disease progression, or less than a 25 percent reduction in the extent and severity of disease after four weeks of prescribed therapy, as documented by medical records', true, 'SOURCE_CHECKED', NULL, ARRAY['src.ecfr.38_part4_2026_08_27']::text[], '{}'::text[]);
INSERT INTO ref.rating_code (code, name, body_system, subsection, cfr_section, notes, has_criteria, status, status_note, source_ids, cited_codes) VALUES ('7818', 'Malignant skin neoplasms', 'THE SKIN', NULL, '38 CFR 4.118', 'Rate as disfigurement of the head, face, or neck (DC 7800), scars (DC''s 7801, 7802, 7803, 7804, or 7805), or impairment of function Note: If a skin malignancy requires therapy that is comparable to that used for systemic malignancies, i.e., systemic chemotherapy, X-ray therapy more extensive than to the skin, or surgery more extensive than wide local excision, a 100-percent evaluation will be assigned from the date of onset of treatment, and will continue, with a mandatory VA examination six months following the completion of such antineoplastic treatment, and any change in evaluation based upon that or any subsequent examination will be subject to the provisions of § 3.105(e) of this chapter. If there has been no local recurrence or metastasis, evaluation will then be made on residuals. If treatment is confined to the skin, the provisions for a 100-percent evaluation do not apply.', false, 'SOURCE_CHECKED', NULL, ARRAY['src.ecfr.38_part4_2026_08_27']::text[], ARRAY['7800','7801','7802','7804','7805']::text[]);
INSERT INTO ref.rating_code (code, name, body_system, subsection, cfr_section, notes, has_criteria, status, status_note, source_ids, cited_codes) VALUES ('7819', 'Benign skin neoplasms', 'THE SKIN', NULL, '38 CFR 4.118', 'Rate as disfigurement of the head, face, or neck (DC 7800), scars (DC''s 7801, 7802, 7803, 7804, or 7805), or impairment of function', false, 'SOURCE_CHECKED', NULL, ARRAY['src.ecfr.38_part4_2026_08_27']::text[], ARRAY['7800','7801','7802','7804','7805']::text[]);
INSERT INTO ref.rating_code (code, name, body_system, subsection, cfr_section, notes, has_criteria, status, status_note, source_ids, cited_codes) VALUES ('7820', 'Infections of the skin', 'THE SKIN', NULL, '38 CFR 4.118', 'Evaluate under the General Rating Formula for the Skin', false, 'SOURCE_CHECKED', NULL, ARRAY['src.ecfr.38_part4_2026_08_27']::text[], '{}'::text[]);
INSERT INTO ref.rating_code (code, name, body_system, subsection, cfr_section, notes, has_criteria, status, status_note, source_ids, cited_codes) VALUES ('7821', 'Cutaneous manifestations of collagen-vascular diseases not listed elsewhere', 'THE SKIN', NULL, '38 CFR 4.118', 'Evaluate under the General Rating Formula for the Skin', false, 'SOURCE_CHECKED', NULL, ARRAY['src.ecfr.38_part4_2026_08_27']::text[], '{}'::text[]);
INSERT INTO ref.rating_code (code, name, body_system, subsection, cfr_section, notes, has_criteria, status, status_note, source_ids, cited_codes) VALUES ('7822', 'Papulosquamous disorders not listed elsewhere', 'THE SKIN', NULL, '38 CFR 4.118', 'Evaluate under the General Rating Formula for the Skin', false, 'SOURCE_CHECKED', NULL, ARRAY['src.ecfr.38_part4_2026_08_27']::text[], '{}'::text[]);
INSERT INTO ref.rating_code (code, name, body_system, subsection, cfr_section, notes, has_criteria, status, status_note, source_ids, cited_codes) VALUES ('7823', 'Vitiligo', 'THE SKIN', NULL, '38 CFR 4.118', NULL, true, 'SOURCE_CHECKED', NULL, ARRAY['src.ecfr.38_part4_2026_08_27']::text[], '{}'::text[]);
INSERT INTO ref.rating_code (code, name, body_system, subsection, cfr_section, notes, has_criteria, status, status_note, source_ids, cited_codes) VALUES ('7824', 'Keratinization, diseases', 'THE SKIN', NULL, '38 CFR 4.118', 'Evaluate under the General Rating Formula for the Skin', false, 'SOURCE_CHECKED', NULL, ARRAY['src.ecfr.38_part4_2026_08_27']::text[], '{}'::text[]);
INSERT INTO ref.rating_code (code, name, body_system, subsection, cfr_section, notes, has_criteria, status, status_note, source_ids, cited_codes) VALUES ('7825', 'Chronic urticaria', 'THE SKIN', NULL, '38 CFR 4.118', NULL, true, 'SOURCE_CHECKED', NULL, ARRAY['src.ecfr.38_part4_2026_08_27']::text[], '{}'::text[]);
INSERT INTO ref.rating_code (code, name, body_system, subsection, cfr_section, notes, has_criteria, status, status_note, source_ids, cited_codes) VALUES ('7826', 'Vasculitis, primary cutaneous', 'THE SKIN', NULL, '38 CFR 4.118', 'Or rate as disfigurement of the head, face, or neck (DC 7800) or scars (DCs 7801, 7802, 7804, or 7805), depending upon the predominant disability', true, 'SOURCE_CHECKED', NULL, ARRAY['src.ecfr.38_part4_2026_08_27']::text[], ARRAY['7800','7801','7802','7804','7805']::text[]);
INSERT INTO ref.rating_code (code, name, body_system, subsection, cfr_section, notes, has_criteria, status, status_note, source_ids, cited_codes) VALUES ('7827', 'Erythema multiforme', 'THE SKIN', NULL, '38 CFR 4.118', 'Or rate as disfigurement of the head, face, or neck (DC 7800) or scars (DCs 7801, 7802, 7804, or 7805), depending upon the predominant disability Note: For the purposes of this DC only, systemic therapy may consist of one or more of the following treatment agents: immunosuppressives, antihistamines, or sympathomimetics', true, 'SOURCE_CHECKED', NULL, ARRAY['src.ecfr.38_part4_2026_08_27']::text[], ARRAY['7800','7801','7802','7804','7805']::text[]);
INSERT INTO ref.rating_code (code, name, body_system, subsection, cfr_section, notes, has_criteria, status, status_note, source_ids, cited_codes) VALUES ('7828', 'Acne', 'THE SKIN', NULL, '38 CFR 4.118', 'Or rate as disfigurement of the head, face, or neck (DC 7800) or scars (DCs 7801, 7802, 7804, or 7805), depending upon the predominant disability', true, 'SOURCE_CHECKED', NULL, ARRAY['src.ecfr.38_part4_2026_08_27']::text[], ARRAY['7800','7801','7802','7804','7805']::text[]);
INSERT INTO ref.rating_code (code, name, body_system, subsection, cfr_section, notes, has_criteria, status, status_note, source_ids, cited_codes) VALUES ('7829', 'Chloracne', 'THE SKIN', NULL, '38 CFR 4.118', 'Or rate as disfigurement of the head, face, or neck (DC 7800) or scars (DCs 7801, 7802, 7804, or 7805), depending upon the predominant disability', true, 'SOURCE_CHECKED', NULL, ARRAY['src.ecfr.38_part4_2026_08_27']::text[], ARRAY['7800','7801','7802','7804','7805']::text[]);
INSERT INTO ref.rating_code (code, name, body_system, subsection, cfr_section, notes, has_criteria, status, status_note, source_ids, cited_codes) VALUES ('7830', 'Scarring alopecia', 'THE SKIN', NULL, '38 CFR 4.118', NULL, true, 'SOURCE_CHECKED', NULL, ARRAY['src.ecfr.38_part4_2026_08_27']::text[], '{}'::text[]);
INSERT INTO ref.rating_code (code, name, body_system, subsection, cfr_section, notes, has_criteria, status, status_note, source_ids, cited_codes) VALUES ('7831', 'Alopecia areata', 'THE SKIN', NULL, '38 CFR 4.118', NULL, true, 'SOURCE_CHECKED', NULL, ARRAY['src.ecfr.38_part4_2026_08_27']::text[], '{}'::text[]);
INSERT INTO ref.rating_code (code, name, body_system, subsection, cfr_section, notes, has_criteria, status, status_note, source_ids, cited_codes) VALUES ('7832', 'Hyperhidrosis', 'THE SKIN', NULL, '38 CFR 4.118', NULL, true, 'SOURCE_CHECKED', NULL, ARRAY['src.ecfr.38_part4_2026_08_27']::text[], '{}'::text[]);
INSERT INTO ref.rating_code (code, name, body_system, subsection, cfr_section, notes, has_criteria, status, status_note, source_ids, cited_codes) VALUES ('7833', 'Malignant melanoma', 'THE SKIN', NULL, '38 CFR 4.118', 'Rate as scars (DC''s 7801, 7802, 7803, 7804, or 7805), disfigurement of the head, face, or neck (DC 7800), or impairment of function (under the appropriate body system) Note: If a skin malignancy requires therapy that is comparable to that used for systemic malignancies, i.e., systemic chemotherapy, X-ray therapy more extensive than to the skin, or surgery more extensive than wide local excision, a 100-percent evaluation will be assigned from the date of onset of treatment, and will continue, with a mandatory VA examination six months following the completion of such antineoplastic treatment, and any change in evaluation based upon that or any subsequent examination will be subject to the provisions of § 3.105(e). If there has been no local recurrence or metastasis, evaluation will then be made on residuals. If treatment is confined to the skin, the provisions for a 100-percent evaluation do not apply.', false, 'SOURCE_CHECKED', NULL, ARRAY['src.ecfr.38_part4_2026_08_27']::text[], ARRAY['7800','7801','7802','7804','7805']::text[]);
INSERT INTO ref.rating_code (code, name, body_system, subsection, cfr_section, notes, has_criteria, status, status_note, source_ids, cited_codes) VALUES ('7900', 'Hyperthyroidism, including, but not limited to, Graves'' disease', 'THE ENDOCRINE SYSTEM', NULL, '38 CFR 4.119', 'Thereafter, rate residuals of disease or complications of medical treatment within the appropriate diagnostic code(s) within the appropriate body system. Note (1): If hyperthyroid cardiovascular or cardiac disease is present, separately evaluate under DC 7008 (hyperthyroid heart disease). Note (2): Separately evaluate eye involvement occurring as a manifestation of Graves'' Disease as diplopia (DC 6090); impairment of central visual acuity (DCs 6061-6066); or under the most appropriate DCs in § 4.79.', true, 'SOURCE_CHECKED', NULL, ARRAY['src.ecfr.38_part4_2026_08_27']::text[], ARRAY['6061','6062','6063','6064','6065','6066','6090','7008']::text[]);
INSERT INTO ref.rating_code (code, name, body_system, subsection, cfr_section, notes, has_criteria, status, status_note, source_ids, cited_codes) VALUES ('7901', 'Thyroid enlargement, toxic', 'THE ENDOCRINE SYSTEM', NULL, '38 CFR 4.119', 'Note (1): Evaluate symptoms of hyperthyroidism under DC 7900, hyperthyroidism, including, but not limited to, Graves'' disease. Note (2): If disfigurement of the neck is present due to thyroid disease or enlargement, separately evaluate under DC 7800 (burn scar(s) of the head, face, or neck; scar(s) of the head, face, or neck due to other causes; or other disfigurement of the head, face, or neck).', false, 'SOURCE_CHECKED', NULL, ARRAY['src.ecfr.38_part4_2026_08_27']::text[], ARRAY['7800','7900']::text[]);
INSERT INTO ref.rating_code (code, name, body_system, subsection, cfr_section, notes, has_criteria, status, status_note, source_ids, cited_codes) VALUES ('7902', 'Thyroid enlargement, nontoxic', 'THE ENDOCRINE SYSTEM', NULL, '38 CFR 4.119', 'Note (1): Evaluate symptoms due to pressure on adjacent organs (such as the trachea, larynx, or esophagus) under the appropriate diagnostic code(s) within the appropriate body system. Note (2): If disfigurement of the neck is present due to thyroid disease or enlargement, separately evaluate under DC 7800 (burn scar(s) of the head, face, or neck; scar(s) of the head, face, or neck due to other causes; or other disfigurement of the head, face, or neck).', false, 'SOURCE_CHECKED', NULL, ARRAY['src.ecfr.38_part4_2026_08_27']::text[], ARRAY['7800']::text[]);
INSERT INTO ref.rating_code (code, name, body_system, subsection, cfr_section, notes, has_criteria, status, status_note, source_ids, cited_codes) VALUES ('7903', 'Hypothyroidism', 'THE ENDOCRINE SYSTEM', NULL, '38 CFR 4.119', 'Note (1): This evaluation shall continue for six months beyond the date that an examining physician has determined crisis stabilization. Thereafter, the residual effects of hypothyroidism shall be rated under the appropriate diagnostic code(s) within the appropriate body system(s) (e.g., eye, digestive, and mental disorders). Note (2): This evaluation shall continue for six months after initial diagnosis. Thereafter, rate residuals of disease or medical treatment under the most appropriate diagnostic code(s) under the appropriate body system (e.g., eye, digestive, mental disorders). Note (3): If eye involvement, such as exophthalmos, corneal ulcer, blurred vision, or diplopia, is also present due to thyroid disease, also separately evaluate under the appropriate diagnostic code(s) in § 4.79, Schedule of Ratings—Eye (such as diplopia (DC 6090) or impairment of central visual acuity (DCs 6061-6066)).', true, 'SOURCE_CHECKED', NULL, ARRAY['src.ecfr.38_part4_2026_08_27']::text[], ARRAY['6061','6062','6063','6064','6065','6066','6090']::text[]);
INSERT INTO ref.rating_code (code, name, body_system, subsection, cfr_section, notes, has_criteria, status, status_note, source_ids, cited_codes) VALUES ('7904', 'Hyperparathyroidism', 'THE ENDOCRINE SYSTEM', NULL, '38 CFR 4.119', 'Note (1): After six months, rate on residuals under the appropriate diagnostic code(s) within the appropriate body system(s) based on a VA examination. Note (2): Where surgical intervention is indicated, this evaluation shall continue until the day of surgery, at which time the provisions pertaining to a 100-percent evaluation shall apply. Note (3): Where surgical intervention is not indicated, this evaluation shall continue for six months after pharmacologic treatment begins. After six months, rate on residuals under the appropriate diagnostic code(s) within the appropriate body system(s) based on a VA examination. Note (4): Following surgery or other treatment, evaluate chronic residuals, such as nephrolithiasis (kidney stones), decreased renal function, fractures, vision problems, and cardiovascular complications, under the appropriate diagnostic codes.', true, 'SOURCE_CHECKED', NULL, ARRAY['src.ecfr.38_part4_2026_08_27']::text[], '{}'::text[]);
INSERT INTO ref.rating_code (code, name, body_system, subsection, cfr_section, notes, has_criteria, status, status_note, source_ids, cited_codes) VALUES ('7905', 'Hypoparathyroidism', 'THE ENDOCRINE SYSTEM', NULL, '38 CFR 4.119', 'Thereafter, evaluate chronic residuals, such as nephrolithiasis (kidney stones), cataracts, decreased renal function, and congestive heart failure under the appropriate diagnostic codes.', true, 'SOURCE_CHECKED', NULL, ARRAY['src.ecfr.38_part4_2026_08_27']::text[], '{}'::text[]);
INSERT INTO ref.rating_code (code, name, body_system, subsection, cfr_section, notes, has_criteria, status, status_note, source_ids, cited_codes) VALUES ('7906', 'Thyroiditis', 'THE ENDOCRINE SYSTEM', NULL, '38 CFR 4.119', 'Note: Manifesting as hyperthyroidism, evaluate as hyperthyroidism, including, but not limited to, Graves'' disease (DC 7900); manifesting as hypothyroidism, evaluate as hypothyroidism (DC 7903).', true, 'SOURCE_CHECKED', NULL, ARRAY['src.ecfr.38_part4_2026_08_27']::text[], ARRAY['7900','7903']::text[]);
INSERT INTO ref.rating_code (code, name, body_system, subsection, cfr_section, notes, has_criteria, status, status_note, source_ids, cited_codes) VALUES ('7907', 'Cushing''s syndrome', 'THE ENDOCRINE SYSTEM', NULL, '38 CFR 4.119', 'Note: The evaluations specifically indicated under this diagnostic code shall continue for six months following initial diagnosis. After six months, rate on residuals under the appropriate diagnostic code(s) within the appropriate body system(s).', true, 'SOURCE_CHECKED', NULL, ARRAY['src.ecfr.38_part4_2026_08_27']::text[], '{}'::text[]);
INSERT INTO ref.rating_code (code, name, body_system, subsection, cfr_section, notes, has_criteria, status, status_note, source_ids, cited_codes) VALUES ('7908', 'Acromegaly', 'THE ENDOCRINE SYSTEM', NULL, '38 CFR 4.119', NULL, true, 'SOURCE_CHECKED', NULL, ARRAY['src.ecfr.38_part4_2026_08_27']::text[], '{}'::text[]);
INSERT INTO ref.rating_code (code, name, body_system, subsection, cfr_section, notes, has_criteria, status, status_note, source_ids, cited_codes) VALUES ('7909', 'Diabetes insipidus', 'THE ENDOCRINE SYSTEM', NULL, '38 CFR 4.119', 'Note: Thereafter, if diabetes insipidus has subsided, rate residuals under the appropriate diagnostic code(s) within the appropriate body system.', true, 'SOURCE_CHECKED', NULL, ARRAY['src.ecfr.38_part4_2026_08_27']::text[], '{}'::text[]);
INSERT INTO ref.rating_code (code, name, body_system, subsection, cfr_section, notes, has_criteria, status, status_note, source_ids, cited_codes) VALUES ('7911', 'Addison''s disease (adrenocortical insufficiency)', 'THE ENDOCRINE SYSTEM', NULL, '38 CFR 4.119', 'Note (1): An Addisonian “crisis” consists of the rapid onset of peripheral vascular collapse (with acute hypotension and shock), with findings that may include: anorexia; nausea; vomiting; dehydration; profound weakness; pain in abdomen, legs, and back; fever; apathy, and depressed mentation with possible progression to coma, renal shutdown, and death. Note (2): An Addisonian “episode,” for VA purposes, is a less acute and less severe event than an Addisonian crisis and may consist of anorexia, nausea, vomiting, diarrhea, dehydration, weakness, malaise, orthostatic hypotension, or hypoglycemia, but no peripheral vascular collapse. Note (3): Tuberculous Addison''s disease will be evaluated as active or inactive tuberculosis. If inactive, these evaluations are not to be combined with the graduated ratings of 50 percent or 30 percent for non-pulmonary tuberculosis specified under § 4.88b. Assign the higher rating.', true, 'SOURCE_CHECKED', NULL, ARRAY['src.ecfr.38_part4_2026_08_27']::text[], '{}'::text[]);
INSERT INTO ref.rating_code (code, name, body_system, subsection, cfr_section, notes, has_criteria, status, status_note, source_ids, cited_codes) VALUES ('7912', 'Polyglandular syndrome (multiple endocrine neoplasia, autoimmune polyglandular syndrome)', 'THE ENDOCRINE SYSTEM', NULL, '38 CFR 4.119', 'Evaluate according to major manifestations to include, but not limited to, Type I diabetes mellitus, hyperthyroidism, hypothyroidism, hypoparathyroidism, or Addison''s disease.', false, 'SOURCE_CHECKED', NULL, ARRAY['src.ecfr.38_part4_2026_08_27']::text[], '{}'::text[]);
INSERT INTO ref.rating_code (code, name, body_system, subsection, cfr_section, notes, has_criteria, status, status_note, source_ids, cited_codes) VALUES ('7913', 'Diabetes mellitus', 'THE ENDOCRINE SYSTEM', NULL, '38 CFR 4.119', 'Note (1): Evaluate compensable complications of diabetes separately unless they are part of the criteria used to support a 100-percent evaluation. Noncompensable complications are considered part of the diabetic process under DC 7913. Note (2): When diabetes mellitus has been conclusively diagnosed, do not request a glucose tolerance test solely for rating purposes.', true, 'SOURCE_CHECKED', NULL, ARRAY['src.ecfr.38_part4_2026_08_27']::text[], '{}'::text[]);
INSERT INTO ref.rating_code (code, name, body_system, subsection, cfr_section, notes, has_criteria, status, status_note, source_ids, cited_codes) VALUES ('7914', 'Malignant neoplasm', 'THE ENDOCRINE SYSTEM', NULL, '38 CFR 4.119', 'Note: A rating of 100 percent shall continue beyond the cessation of any surgical, X-ray, antineoplastic chemotherapy or other therapeutic procedure. Six months after discontinuance of such treatment, the appropriate disability rating shall be determined by mandatory VA examination. Any change in evaluation based upon that or any subsequent examination shall be subject to the provisions of § 3.105(e) of this chapter. If there has been no local recurrence or metastasis, rate on residuals.', true, 'SOURCE_CHECKED', NULL, ARRAY['src.ecfr.38_part4_2026_08_27']::text[], '{}'::text[]);
INSERT INTO ref.rating_code (code, name, body_system, subsection, cfr_section, notes, has_criteria, status, status_note, source_ids, cited_codes) VALUES ('7915', 'Benign neoplasm', 'THE ENDOCRINE SYSTEM', NULL, '38 CFR 4.119', 'Rate as residuals of endocrine dysfunction.', false, 'SOURCE_CHECKED', NULL, ARRAY['src.ecfr.38_part4_2026_08_27']::text[], '{}'::text[]);
INSERT INTO ref.rating_code (code, name, body_system, subsection, cfr_section, notes, has_criteria, status, status_note, source_ids, cited_codes) VALUES ('7916', 'Hyperpituitarism', 'THE ENDOCRINE SYSTEM', NULL, '38 CFR 4.119', 'Note: Evaluate as malignant or benign neoplasm, as appropriate.', false, 'SOURCE_CHECKED', NULL, ARRAY['src.ecfr.38_part4_2026_08_27']::text[], '{}'::text[]);
INSERT INTO ref.rating_code (code, name, body_system, subsection, cfr_section, notes, has_criteria, status, status_note, source_ids, cited_codes) VALUES ('7917', 'Hyperaldosteronism', 'THE ENDOCRINE SYSTEM', NULL, '38 CFR 4.119', 'Note: Evaluate as malignant or benign neoplasm, as appropriate.', false, 'SOURCE_CHECKED', NULL, ARRAY['src.ecfr.38_part4_2026_08_27']::text[], '{}'::text[]);
INSERT INTO ref.rating_code (code, name, body_system, subsection, cfr_section, notes, has_criteria, status, status_note, source_ids, cited_codes) VALUES ('7918', 'Pheochromocytoma', 'THE ENDOCRINE SYSTEM', NULL, '38 CFR 4.119', 'Note: Evaluate as malignant or benign neoplasm as appropriate.', false, 'SOURCE_CHECKED', NULL, ARRAY['src.ecfr.38_part4_2026_08_27']::text[], '{}'::text[]);
INSERT INTO ref.rating_code (code, name, body_system, subsection, cfr_section, notes, has_criteria, status, status_note, source_ids, cited_codes) VALUES ('7919', 'C-cell hyperplasia, thyroid', 'THE ENDOCRINE SYSTEM', NULL, '38 CFR 4.119', 'If antineoplastic therapy is required, evaluate as a malignant neoplasm under DC 7914. If a prophylactic thyroidectomy is performed (based upon genetic testing) and antineoplastic therapy is not required, evaluate as hypothyroidism under DC 7903.', false, 'SOURCE_CHECKED', NULL, ARRAY['src.ecfr.38_part4_2026_08_27']::text[], ARRAY['7903','7914']::text[]);
INSERT INTO ref.rating_code (code, name, body_system, subsection, cfr_section, notes, has_criteria, status, status_note, source_ids, cited_codes) VALUES ('8000', 'Encephalitis, epidemic, chronic', 'NEUROLOGICAL CONDITIONS AND CONVULSIVE DISORDERS', 'Organic Diseases of the Central Nervous System', '38 CFR 4.124a', 'Note: It is required for the minimum ratings for residuals under diagnostic codes 8000-8025, that there be ascertainable residuals. Determinations as to the presence of residuals not capable of objective verification, i.e., headaches, dizziness, fatigability, must be approached on the basis of the diagnosis recorded; subjective residuals will be accepted when consistent with the disease and not more likely attributable to other disease or no disease. It is of exceptional importance that when ratings in excess of the prescribed minimum ratings are assigned, the diagnostic codes utilized as bases of evaluation be cited, in addition to the codes identifying the diagnoses.', true, 'SOURCE_CHECKED', NULL, ARRAY['src.ecfr.38_part4_2026_08_27']::text[], ARRAY['8002','8003','8004','8005','8007','8008','8009','8010','8011','8012','8013','8014','8015','8017','8018','8019','8020','8021','8022','8023','8024','8025']::text[]);
INSERT INTO ref.rating_code (code, name, body_system, subsection, cfr_section, notes, has_criteria, status, status_note, source_ids, cited_codes) VALUES ('8002', 'Malignant', 'NEUROLOGICAL CONDITIONS AND CONVULSIVE DISORDERS', 'Brain, New Growth of', '38 CFR 4.124a', 'Note: The rating in code 8002 will be continued for 2 years following cessation of surgical, chemotherapeutic or other treatment modality. At this point, if the residuals have stabilized, the rating will be made on neurological residuals according to symptomatology. Note: It is required for the minimum ratings for residuals under diagnostic codes 8000-8025, that there be ascertainable residuals. Determinations as to the presence of residuals not capable of objective verification, i.e., headaches, dizziness, fatigability, must be approached on the basis of the diagnosis recorded; subjective residuals will be accepted when consistent with the disease and not more likely attributable to other disease or no disease. It is of exceptional importance that when ratings in excess of the prescribed minimum ratings are assigned, the diagnostic codes utilized as bases of evaluation be cited, in addition to the codes identifying the diagnoses.', true, 'SOURCE_CHECKED', NULL, ARRAY['src.ecfr.38_part4_2026_08_27']::text[], ARRAY['8000','8003','8004','8005','8007','8008','8009','8010','8011','8012','8013','8014','8015','8017','8018','8019','8020','8021','8022','8023','8024','8025']::text[]);
INSERT INTO ref.rating_code (code, name, body_system, subsection, cfr_section, notes, has_criteria, status, status_note, source_ids, cited_codes) VALUES ('8003', 'Benign', 'NEUROLOGICAL CONDITIONS AND CONVULSIVE DISORDERS', 'Brain, New Growth of', '38 CFR 4.124a', 'Note: It is required for the minimum ratings for residuals under diagnostic codes 8000-8025, that there be ascertainable residuals. Determinations as to the presence of residuals not capable of objective verification, i.e., headaches, dizziness, fatigability, must be approached on the basis of the diagnosis recorded; subjective residuals will be accepted when consistent with the disease and not more likely attributable to other disease or no disease. It is of exceptional importance that when ratings in excess of the prescribed minimum ratings are assigned, the diagnostic codes utilized as bases of evaluation be cited, in addition to the codes identifying the diagnoses.', true, 'SOURCE_CHECKED', NULL, ARRAY['src.ecfr.38_part4_2026_08_27']::text[], ARRAY['8000','8002','8004','8005','8007','8008','8009','8010','8011','8012','8013','8014','8015','8017','8018','8019','8020','8021','8022','8023','8024','8025']::text[]);
