INSERT INTO ref.rating_code (code, name, body_system, subsection, cfr_section, notes, has_criteria, status, status_note, source_ids, cited_codes) VALUES ('8021', 'Malignant', 'NEUROLOGICAL CONDITIONS AND CONVULSIVE DISORDERS', 'Spinal Cord, New Growths', '38 CFR 4.124a', 'Note: The rating in code 8021 will be continued for 2 years following cessation of surgical, chemotherapeutic or other treatment modality. At this point, if the residuals have stabilized, the rating will be made on neurological residuals according to symptomatology. Note: It is required for the minimum ratings for residuals under diagnostic codes 8000-8025, that there be ascertainable residuals. Determinations as to the presence of residuals not capable of objective verification, i.e., headaches, dizziness, fatigability, must be approached on the basis of the diagnosis recorded; subjective residuals will be accepted when consistent with the disease and not more likely attributable to other disease or no disease. It is of exceptional importance that when ratings in excess of the prescribed minimum ratings are assigned, the diagnostic codes utilized as bases of evaluation be cited, in addition to the codes identifying the diagnoses.', true, 'SOURCE_CHECKED', NULL, ARRAY['src.ecfr.38_part4_2026_08_27']::text[], ARRAY['8000','8002','8003','8004','8005','8007','8008','8009','8010','8011','8012','8013','8014','8015','8017','8018','8019','8020','8022','8023','8024','8025']::text[]);
