INSERT INTO ref.rating_code (code, name, body_system, subsection, cfr_section, notes, has_criteria, status, status_note, source_ids, cited_codes) VALUES ('8910', 'Grand mal', 'NEUROLOGICAL CONDITIONS AND CONVULSIVE DISORDERS', 'The Epilepsies', '38 CFR 4.124a', 'Rate under the general rating formula for major seizures.', false, 'SOURCE_CHECKED', NULL, ARRAY['src.ecfr.38_part4_2026_08_27']::text[], '{}'::text[]);
INSERT INTO ref.rating_code (code, name, body_system, subsection, cfr_section, notes, has_criteria, status, status_note, source_ids, cited_codes) VALUES ('8911', 'Petit mal', 'NEUROLOGICAL CONDITIONS AND CONVULSIVE DISORDERS', 'The Epilepsies', '38 CFR 4.124a', 'Rate under the general rating formula for minor seizures. Note (1): A major seizure is characterized by the generalized tonic-clonic convulsion with unconsciousness. Note (2): A minor seizure consists of a brief interruption in consciousness or conscious control associated with staring or rhythmic blinking of the eyes or nodding of the head (“pure” petit mal), or sudden jerking movements of the arms, trunk, or head (myoclonic type) or sudden loss of postural control (akinetic type).', false, 'SOURCE_CHECKED', NULL, ARRAY['src.ecfr.38_part4_2026_08_27']::text[], '{}'::text[]);
INSERT INTO ref.rating_code (code, name, body_system, subsection, cfr_section, notes, has_criteria, status, status_note, source_ids, cited_codes) VALUES ('8912', 'Jacksonian and focal motor or sensory', 'NEUROLOGICAL CONDITIONS AND CONVULSIVE DISORDERS', 'The Epilepsies', '38 CFR 4.124a', NULL, false, 'SOURCE_CHECKED', NULL, ARRAY['src.ecfr.38_part4_2026_08_27']::text[], '{}'::text[]);
INSERT INTO ref.rating_code (code, name, body_system, subsection, cfr_section, notes, has_criteria, status, status_note, source_ids, cited_codes) VALUES ('8913', 'Diencephalic', 'NEUROLOGICAL CONDITIONS AND CONVULSIVE DISORDERS', 'The Epilepsies', '38 CFR 4.124a', 'Rate as minor seizures, except in the presence of major and minor seizures, rate the predominating type.', false, 'SOURCE_CHECKED', NULL, ARRAY['src.ecfr.38_part4_2026_08_27']::text[], '{}'::text[]);
INSERT INTO ref.rating_code (code, name, body_system, subsection, cfr_section, notes, has_criteria, status, status_note, source_ids, cited_codes) VALUES ('8914', 'Psychomotor', 'NEUROLOGICAL CONDITIONS AND CONVULSIVE DISORDERS', 'The Epilepsies', '38 CFR 4.124a', 'Major seizures: Psychomotor seizures will be rated as major seizures under the general rating formula when characterized by automatic states and/or generalized convulsions with unconsciousness. Minor seizures: Psychomotor seizures will be rated as minor seizures under the general rating formula when characterized by brief transient episodes of random motor movements, hallucinations, perceptual illusions, abnormalities of thinking, memory or mood, or autonomic disturbances.', false, 'SOURCE_CHECKED', NULL, ARRAY['src.ecfr.38_part4_2026_08_27']::text[], '{}'::text[]);
