INSERT INTO ref.rating_code (code, name, body_system, subsection, cfr_section, notes, has_criteria, status, status_note, source_ids, cited_codes) VALUES ('9904', 'Mandible, malunion', 'DENTAL AND ORAL CONDITIONS', NULL, '38 CFR 4.150', NULL, true, 'SOURCE_CHECKED', NULL, ARRAY['src.ecfr.38_part4_2026_08_27']::text[], '{}'::text[]);
INSERT INTO ref.rating_code (code, name, body_system, subsection, cfr_section, notes, has_criteria, status, status_note, source_ids, cited_codes) VALUES ('9905', 'Temporomandibular disorder (TMD)', 'DENTAL AND ORAL CONDITIONS', NULL, '38 CFR 4.150', 'Note (1): Ratings for limited interincisal movement shall not be combined with ratings for limited lateral excursion Note (2): For VA compensation purposes, the normal maximum unassisted range of vertical jaw opening is from 35 to 50 mm Note (3): For VA compensation purposes, mechanically altered foods are defined as altered by blending, chopping, grinding or mashing so that they are easy to chew and swallow. There are four levels of mechanically altered foods: full liquid, puree, soft, and semisolid foods. To warrant elevation based on mechanically altered foods, the use of texture-modified diets must be recorded or verified by a physician', true, 'SOURCE_CHECKED', NULL, ARRAY['src.ecfr.38_part4_2026_08_27']::text[], '{}'::text[]);
INSERT INTO ref.rating_code (code, name, body_system, subsection, cfr_section, notes, has_criteria, status, status_note, source_ids, cited_codes) VALUES ('9908', 'Condyloid process', 'DENTAL AND ORAL CONDITIONS', NULL, '38 CFR 4.150', NULL, true, 'SOURCE_CHECKED', NULL, ARRAY['src.ecfr.38_part4_2026_08_27']::text[], '{}'::text[]);
INSERT INTO ref.rating_code (code, name, body_system, subsection, cfr_section, notes, has_criteria, status, status_note, source_ids, cited_codes) VALUES ('9909', 'Coronoid process', 'DENTAL AND ORAL CONDITIONS', NULL, '38 CFR 4.150', NULL, true, 'SOURCE_CHECKED', NULL, ARRAY['src.ecfr.38_part4_2026_08_27']::text[], '{}'::text[]);
INSERT INTO ref.rating_code (code, name, body_system, subsection, cfr_section, notes, has_criteria, status, status_note, source_ids, cited_codes) VALUES ('9911', 'Hard palate, loss of', 'DENTAL AND ORAL CONDITIONS', NULL, '38 CFR 4.150', NULL, true, 'SOURCE_CHECKED', NULL, ARRAY['src.ecfr.38_part4_2026_08_27']::text[], '{}'::text[]);
INSERT INTO ref.rating_code (code, name, body_system, subsection, cfr_section, notes, has_criteria, status, status_note, source_ids, cited_codes) VALUES ('9913', 'Teeth, loss of', 'DENTAL AND ORAL CONDITIONS', NULL, '38 CFR 4.150', 'Note—These ratings apply only to bone loss through trauma or disease such as osteomyelitis, and not to the loss of the alveolar process as a result of periodontal disease, since such loss is not considered disabling', true, 'SOURCE_CHECKED', NULL, ARRAY['src.ecfr.38_part4_2026_08_27']::text[], '{}'::text[]);
INSERT INTO ref.rating_code (code, name, body_system, subsection, cfr_section, notes, has_criteria, status, status_note, source_ids, cited_codes) VALUES ('9914', 'Maxilla, loss of more than half', 'DENTAL AND ORAL CONDITIONS', NULL, '38 CFR 4.150', NULL, true, 'SOURCE_CHECKED', NULL, ARRAY['src.ecfr.38_part4_2026_08_27']::text[], '{}'::text[]);
INSERT INTO ref.rating_code (code, name, body_system, subsection, cfr_section, notes, has_criteria, status, status_note, source_ids, cited_codes) VALUES ('9915', 'Maxilla, loss of half or less', 'DENTAL AND ORAL CONDITIONS', NULL, '38 CFR 4.150', NULL, true, 'SOURCE_CHECKED', NULL, ARRAY['src.ecfr.38_part4_2026_08_27']::text[], '{}'::text[]);
INSERT INTO ref.rating_code (code, name, body_system, subsection, cfr_section, notes, has_criteria, status, status_note, source_ids, cited_codes) VALUES ('9916', 'Maxilla, malunion or nonunion of', 'DENTAL AND ORAL CONDITIONS', NULL, '38 CFR 4.150', 'Note: For VA compensation purposes, the severity of maxillary nonunion is dependent upon the degree of abnormal mobility of maxilla fragments following treatment (i.e., presence or absence of false motion), and maxillary nonunion must be confirmed by diagnostic imaging studies', true, 'SOURCE_CHECKED', NULL, ARRAY['src.ecfr.38_part4_2026_08_27']::text[], '{}'::text[]);
INSERT INTO ref.rating_code (code, name, body_system, subsection, cfr_section, notes, has_criteria, status, status_note, source_ids, cited_codes) VALUES ('9917', 'Neoplasm, hard and soft tissue, benign', 'DENTAL AND ORAL CONDITIONS', NULL, '38 CFR 4.150', 'Rate as loss of supporting structures (bone or teeth) and/or functional impairment due to scarring.', false, 'SOURCE_CHECKED', NULL, ARRAY['src.ecfr.38_part4_2026_08_27']::text[], '{}'::text[]);
INSERT INTO ref.rating_code (code, name, body_system, subsection, cfr_section, notes, has_criteria, status, status_note, source_ids, cited_codes) VALUES ('9918', 'Neoplasm, hard and soft tissue, malignant', 'DENTAL AND ORAL CONDITIONS', NULL, '38 CFR 4.150', 'Note: A rating of 100 percent shall continue beyond the cessation of any surgical, radiation, antineoplastic chemotherapy or other therapeutic procedure. Six months after discontinuance of such treatment, the appropriate disability rating shall be determined by mandatory VA examination. Any change in evaluation based upon that or any subsequent examination shall be subject to the provisions of § 3.105(e) of this chapter. If there has been no local recurrence or metastasis, rate on residuals such as loss of supporting structures (bone or teeth) and/or functional impairment due to scarring', true, 'SOURCE_CHECKED', NULL, ARRAY['src.ecfr.38_part4_2026_08_27']::text[], '{}'::text[]);
INSERT INTO ref.rating_criterion (criterion_id, code, position, percent, percent_minor, criteria_text) VALUES ('5000:00', '5000', 0, 100, NULL, 'Of the pelvis, vertebrae, or extending into major joints, or with multiple localization or with long history of intractability and debility, anemia, amyloid liver changes, or other continuous constitutional symptoms');
