INSERT INTO ref.rating_criterion (criterion_id, code, position, percent, percent_minor, criteria_text) VALUES ('6354:00', '6354', 0, 100, NULL, 'Debilitating fatigue, cognitive impairments (such as inability to concentrate, forgetfulness, or confusion), or a combination of other signs and symptoms: Which are nearly constant and so severe as to restrict routine daily activities almost completely and which may occasionally preclude self-care');
