INSERT INTO ref.rating_criterion (criterion_id, code, position, percent, percent_minor, criteria_text) VALUES ('6730:00', '6730', 0, 100, NULL, 'Tuberculosis, pulmonary, chronic, active; (a) Associated with active tuberculosis involving other than the respiratory system.; (b) With severe associated symptoms or with extensive cavity formation.; (c) Reactivated cases, generally.; (d) With advancement of lesions on successive examinations or while under treatment.; (e) Without retrogression of lesions or other evidence of material improvement at the end of six months hospitalization or without change of diagnosis from “active” at the end of 12 months hospitalization. Material improvement means lessening or absence of clinical symptoms, and X-ray findings of a stationary or retrogressive lesion.');
