INSERT INTO ref.rating_criterion (criterion_id, code, position, percent, percent_minor, criteria_text) VALUES ('7122:00', '7122', 0, 30, NULL, 'With the following in affected parts: Arthralgia or other pain, numbness, or cold sensitivity plus two or more of the following: Tissue loss, nail abnormalities, color changes, locally impaired sensation, hyperhidrosis, anhydrosis, X-ray abnormalities (osteoporosis, subarticular punched-out lesions, or osteoarthritis), atrophy or fibrosis of the affected musculature, flexion or extension deformity of distal joints, volar fat pad loss in fingers or toes, avascular necrosis of bone, chronic ulceration, carpal or tarsal tunnel syndrome');
INSERT INTO ref.rating_criterion (criterion_id, code, position, percent, percent_minor, criteria_text) VALUES ('7122:01', '7122', 1, 20, NULL, 'With the following in affected parts: Arthralgia or other pain, numbness, or cold sensitivity plus one of the following: Tissue loss, nail abnormalities, color changes, locally impaired sensation, hyperhidrosis, anhydrosis, X-ray abnormalities (osteoporosis, subarticular punched-out lesions, or osteoarthritis), atrophy or fibrosis of the affected musculature, flexion or extension deformity of distal joints, volar fat pad loss in fingers or toes, avascular necrosis of bone, chronic ulceration, carpal or tarsal tunnel syndrome');
INSERT INTO ref.rating_criterion (criterion_id, code, position, percent, percent_minor, criteria_text) VALUES ('7122:02', '7122', 2, 10, NULL, 'With the following in affected parts: Arthralgia or other pain, numbness, or cold sensitivity');
INSERT INTO ref.rating_criterion (criterion_id, code, position, percent, percent_minor, criteria_text) VALUES ('7123:00', '7123', 0, 100, NULL, 'Soft tissue sarcoma (of vascular origin)');
