INSERT INTO ref.rating_criterion (criterion_id, code, position, percent, percent_minor, criteria_text) VALUES ('7203:03', '7203', 3, 10, NULL, 'Documented history of esophageal stricture(s) that requires daily medications to control dysphagia otherwise asymptomatic');
INSERT INTO ref.rating_criterion (criterion_id, code, position, percent, percent_minor, criteria_text) VALUES ('7203:04', '7203', 4, 0, NULL, 'Documented history without daily symptoms or requirement for daily medications');
INSERT INTO ref.rating_criterion (criterion_id, code, position, percent, percent_minor, criteria_text) VALUES ('7206:00', '7206', 0, 80, NULL, 'Documented history of recurrent or refractory esophageal stricture(s) causing dysphagia with at least one of the symptoms present: (1) aspiration, (2) undernutrition, and/or (3) substantial weight loss as defined by § 4.112(a) and treatment with either surgical correction of esophageal stricture(s) or percutaneous esophago-gastrointestinal tube (PEG tube)');
INSERT INTO ref.rating_criterion (criterion_id, code, position, percent, percent_minor, criteria_text) VALUES ('7206:01', '7206', 1, 50, NULL, 'Documented history of recurrent or refractory esophageal stricture(s) causing dysphagia which requires at least one of the following (1) dilatation 3 or more times per year, (2) dilatation using steroids at least one time per year, or (3) esophageal stent placement');
INSERT INTO ref.rating_criterion (criterion_id, code, position, percent, percent_minor, criteria_text) VALUES ('7206:02', '7206', 2, 30, NULL, 'Documented history of recurrent esophageal stricture(s) causing dysphagia which requires dilatation no more than 2 times per year');
INSERT INTO ref.rating_criterion (criterion_id, code, position, percent, percent_minor, criteria_text) VALUES ('7206:03', '7206', 3, 10, NULL, 'Documented history of esophageal stricture(s) that requires daily medications to control dysphagia otherwise asymptomatic');
INSERT INTO ref.rating_criterion (criterion_id, code, position, percent, percent_minor, criteria_text) VALUES ('7206:04', '7206', 4, 0, NULL, 'Documented history without daily symptoms or requirement for daily medications');
