INSERT INTO ref.rating_criterion (criterion_id, code, position, percent, percent_minor, criteria_text) VALUES ('7301:00', '7301', 0, 80, NULL, 'Persistent partial bowel obstruction that is either inoperable and refractory to treatment, or requires total parenteral nutrition (TPN) for obstructive symptoms');
INSERT INTO ref.rating_criterion (criterion_id, code, position, percent, percent_minor, criteria_text) VALUES ('7301:01', '7301', 1, 50, NULL, 'Symptomatic peritoneal adhesions, persisting or recurring after surgery, trauma, inflammatory disease process such as chronic cholecystitis or Crohn''s disease, or infection, as determined by a healthcare provider; and clinical evidence of recurrent obstruction requiring hospitalization at least once a year; and medically-directed dietary modification other than total parenteral nutrition (TPN); and at least one of the following: (1) abdominal pain, (2) nausea, (3) vomiting, (4) colic, (5) constipation, or (6) diarrhea');
INSERT INTO ref.rating_criterion (criterion_id, code, position, percent, percent_minor, criteria_text) VALUES ('7301:02', '7301', 2, 30, NULL, 'Symptomatic peritoneal adhesions, persisting or recurring after surgery, trauma, inflammatory disease process such as chronic cholecystitis or Crohn''s disease, or infection, as determined by a healthcare provider; and medically-directed dietary modification other than total parenteral nutrition (TPN); and at least one of the following: (1) abdominal pain, (2) nausea, (3) vomiting, (4) colic, (5) constipation, or (6) diarrhea');
INSERT INTO ref.rating_criterion (criterion_id, code, position, percent, percent_minor, criteria_text) VALUES ('7301:03', '7301', 3, 10, NULL, 'Symptomatic peritoneal adhesions, persisting or recurring after surgery, trauma, inflammatory disease process such as chronic cholecystitis or Crohn''s disease, or infection, as determined by a healthcare provider, and at least one of the following: (1) abdominal pain, (2) nausea, (3) vomiting, (4) colic, (5) constipation, or (6) diarrhea');
INSERT INTO ref.rating_criterion (criterion_id, code, position, percent, percent_minor, criteria_text) VALUES ('7301:04', '7301', 4, 0, NULL, 'History of peritoneal adhesions, currently asymptomatic');
INSERT INTO ref.rating_criterion (criterion_id, code, position, percent, percent_minor, criteria_text) VALUES ('7303:00', '7303', 0, 80, NULL, 'Requiring continuous total parenteral nutrition (TPN) or tube feeding for a period longer than 30 consecutive days in the last six months');
INSERT INTO ref.rating_criterion (criterion_id, code, position, percent, percent_minor, criteria_text) VALUES ('7303:01', '7303', 1, 50, NULL, 'Any one of the following symptoms with or without pain: (1) daily vomiting despite oral dietary modification or medication; (2) six or more watery bowel movements per day every day, or explosive bowel movements that are difficult to predict or control; (3) post-prandial (meal-induced) light-headedness (syncope) with sweating and the need for medications to specifically treat complications of upper gastrointestinal surgery such as dumping syndrome or delayed gastric emptying');
INSERT INTO ref.rating_criterion (criterion_id, code, position, percent, percent_minor, criteria_text) VALUES ('7303:02', '7303', 2, 30, NULL, 'With two or more of the following symptoms: (1) vomiting two or more times per week or vomiting despite medical treatment; (2) discomfort or pain within an hour of eating and requiring ongoing oral dietary modification; (3) three to five watery bowel movements per day every day');
INSERT INTO ref.rating_criterion (criterion_id, code, position, percent, percent_minor, criteria_text) VALUES ('7303:03', '7303', 3, 10, NULL, 'With either nausea or vomiting managed by ongoing medical treatment');
INSERT INTO ref.rating_criterion (criterion_id, code, position, percent, percent_minor, criteria_text) VALUES ('7303:04', '7303', 4, 0, NULL, 'Post-operative status, asymptomatic');
INSERT INTO ref.rating_criterion (criterion_id, code, position, percent, percent_minor, criteria_text) VALUES ('7304:00', '7304', 0, 100, NULL, 'Post-operative for perforation or hemorrhage, for three months');
INSERT INTO ref.rating_criterion (criterion_id, code, position, percent, percent_minor, criteria_text) VALUES ('7304:01', '7304', 1, 60, NULL, 'Continuous abdominal pain with intermittent vomiting, recurrent hematemesis (vomiting blood) or melena (tarry stools); and manifestations of anemia which require hospitalization at least once in the past 12 months');
INSERT INTO ref.rating_criterion (criterion_id, code, position, percent, percent_minor, criteria_text) VALUES ('7304:02', '7304', 2, 40, NULL, 'Episodes of abdominal pain, nausea, or vomiting, that: last for at least three consecutive days in duration; occur four or more times in the past 12 months; and are managed by daily prescribed medication');
INSERT INTO ref.rating_criterion (criterion_id, code, position, percent, percent_minor, criteria_text) VALUES ('7304:03', '7304', 3, 20, NULL, 'Episodes of abdominal pain, nausea, or vomiting, that: last for at least three consecutive days in duration; occur three times or less in the past 12 months; and are managed by daily prescribed medication');
INSERT INTO ref.rating_criterion (criterion_id, code, position, percent, percent_minor, criteria_text) VALUES ('7304:04', '7304', 4, 0, NULL, 'History of peptic ulcer disease documented by endoscopy or diagnostic imaging studies');
INSERT INTO ref.rating_criterion (criterion_id, code, position, percent, percent_minor, criteria_text) VALUES ('7312:00', '7312', 0, 100, NULL, 'Liver disease with Model for End-Stage Liver Disease score greater than or equal to 15; or with continuous daily debilitating symptoms, generalized weakness and at least one of the following: (1) ascites (fluid in the abdomen), or (2) a history of spontaneous bacterial peritonitis, or (3) hepatic encephalopathy, or (4) variceal hemorrhage, or (5) coagulopathy, or (6) portal gastropathy, or (7) hepatopulmonary or hepatorenal syndrome');
INSERT INTO ref.rating_criterion (criterion_id, code, position, percent, percent_minor, criteria_text) VALUES ('7312:01', '7312', 1, 60, NULL, 'Liver disease with Model for End-Stage Liver Disease score greater than 11 but less than 15; or with daily fatigue and at least one episode in the last year of either (1) variceal hemorrhage, or (2) portal gastropathy or hepatic encephalopathy');
INSERT INTO ref.rating_criterion (criterion_id, code, position, percent, percent_minor, criteria_text) VALUES ('7312:02', '7312', 2, 30, NULL, 'Liver disease with Model for End-Stage Liver Disease score of 10 or 11; or with signs of portal hypertension such as splenomegaly or ascites (fluid in the abdomen) and either weakness, anorexia, abdominal pain, or malaise');
INSERT INTO ref.rating_criterion (criterion_id, code, position, percent, percent_minor, criteria_text) VALUES ('7312:03', '7312', 3, 10, NULL, 'Liver disease with Model for End-Stage Liver Disease score greater than 6 but less than 10; or with evidence of either anorexia, weakness, abdominal pain or malaise');
INSERT INTO ref.rating_criterion (criterion_id, code, position, percent, percent_minor, criteria_text) VALUES ('7312:04', '7312', 4, 0, NULL, 'Asymptomatic, but with a history of liver disease');
INSERT INTO ref.rating_criterion (criterion_id, code, position, percent, percent_minor, criteria_text) VALUES ('7314:00', '7314', 0, 30, NULL, 'With three or more clinically documented attacks of right upper quadrant pain with nausea and vomiting during the past 12 months; or requiring dilatation of biliary tract strictures at least once during the past 12 months.');
INSERT INTO ref.rating_criterion (criterion_id, code, position, percent, percent_minor, criteria_text) VALUES ('7314:01', '7314', 1, 10, NULL, 'With one or two clinically documented attacks of right upper quadrant pain with nausea and vomiting in the past 12 months.');
INSERT INTO ref.rating_criterion (criterion_id, code, position, percent, percent_minor, criteria_text) VALUES ('7314:02', '7314', 2, 0, NULL, 'Asymptomatic, without history of a clinically documented attack of right upper quadrant pain with nausea and vomiting in the past 12 months.');
INSERT INTO ref.rating_criterion (criterion_id, code, position, percent, percent_minor, criteria_text) VALUES ('7318:00', '7318', 0, 30, NULL, 'With recurrent abdominal pain (post-prandial or nocturnal); and chronic diarrhea characterized by three or more watery bowel movements per day');
INSERT INTO ref.rating_criterion (criterion_id, code, position, percent, percent_minor, criteria_text) VALUES ('7318:01', '7318', 1, 10, NULL, 'With intermittent abdominal pain; and diarrhea characterized by one to two watery bowel movements per day');
INSERT INTO ref.rating_criterion (criterion_id, code, position, percent, percent_minor, criteria_text) VALUES ('7318:02', '7318', 2, 0, NULL, 'Asymptomatic');
INSERT INTO ref.rating_criterion (criterion_id, code, position, percent, percent_minor, criteria_text) VALUES ('7319:00', '7319', 0, 30, NULL, 'Abdominal pain related to defecation at least one day per week during the previous three months; and two or more of the following: (1) change in stool frequency, (2) change in stool form, (3) altered stool passage (straining and/or urgency), (4) mucorrhea, (5) abdominal bloating, or (6) subjective distension');
INSERT INTO ref.rating_criterion (criterion_id, code, position, percent, percent_minor, criteria_text) VALUES ('7319:01', '7319', 1, 20, NULL, 'Abdominal pain related to defecation for at least three days per month during the previous three months; and two or more of the following: (1) change in stool frequency, (2) change in stool form, (3) altered stool passage (straining and/or urgency), (4) mucorrhea, (5) abdominal bloating, or (6) subjective distension');
INSERT INTO ref.rating_criterion (criterion_id, code, position, percent, percent_minor, criteria_text) VALUES ('7319:02', '7319', 2, 10, NULL, 'Abdominal pain related to defecation at least once during the previous three months; and two or more of the following: (1) change in stool frequency, (2) change in stool form, (3) altered stool passage (straining and/or urgency), (4) mucorrhea, (5) abdominal bloating, or (6) subjective distension');
INSERT INTO ref.rating_criterion (criterion_id, code, position, percent, percent_minor, criteria_text) VALUES ('7326:00', '7326', 0, 100, NULL, 'Severe inflammatory bowel disease that is unresponsive to treatment; and requires hospitalization at least once per year; and results in either an inability to work or is characterized by recurrent abdominal pain associated with at least two of the following: (1) six or more episodes per day of diarrhea, (2) six or more episodes per day of rectal bleeding, (3) recurrent episodes of rectal incontinence, or (4) recurrent abdominal distension');
INSERT INTO ref.rating_criterion (criterion_id, code, position, percent, percent_minor, criteria_text) VALUES ('7326:01', '7326', 1, 60, NULL, 'Moderate inflammatory bowel disease that is managed on an outpatient basis with immunosuppressants or other biologic agents; and is characterized by recurrent abdominal pain, four to five daily episodes of diarrhea; and intermittent signs of toxicity such as fever, tachycardia, or anemia');
INSERT INTO ref.rating_criterion (criterion_id, code, position, percent, percent_minor, criteria_text) VALUES ('7326:02', '7326', 2, 30, NULL, 'Mild to moderate inflammatory bowel disease that is managed with oral and topical agents (other than immunosuppressants or other biologic agents); and is characterized by recurrent abdominal pain with three or less daily episodes of diarrhea and minimal signs of toxicity such as fever, tachycardia, or anemia');
INSERT INTO ref.rating_criterion (criterion_id, code, position, percent, percent_minor, criteria_text) VALUES ('7326:03', '7326', 3, 10, NULL, 'Minimal to mild symptomatic inflammatory bowel disease that is managed with oral or topical agents (other than immunosuppressants or other biologic agents); and is characterized by recurrent abdominal pain with three or less daily episodes of diarrhea and no signs of systemic toxicity');
INSERT INTO ref.rating_criterion (criterion_id, code, position, percent, percent_minor, criteria_text) VALUES ('7327:00', '7327', 0, 30, NULL, 'Diverticular disease requiring hospitalization for abdominal distress, fever, and leukocytosis (elevated white blood cells) one or more times in the past 12 months; and with at least one of the following complications: (1) hemorrhage, (2) obstruction, (3) abscess, (4) peritonitis, or (5) perforation');
INSERT INTO ref.rating_criterion (criterion_id, code, position, percent, percent_minor, criteria_text) VALUES ('7327:01', '7327', 1, 20, NULL, 'Diverticular disease requiring hospitalization for abdominal distress, fever, and leukocytosis (elevated white blood cells) one or more times in the past 12 months; and without associated (1) hemorrhage, (2) obstruction, (3) abscess, (4) peritonitis, or (5) perforation');
INSERT INTO ref.rating_criterion (criterion_id, code, position, percent, percent_minor, criteria_text) VALUES ('7327:02', '7327', 2, 0, NULL, 'Asymptomatic; or a symptomatic diverticulitis or diverticulosis that is managed by diet and medication');
INSERT INTO ref.rating_criterion (criterion_id, code, position, percent, percent_minor, criteria_text) VALUES ('7328:00', '7328', 0, 80, NULL, 'Status post intestinal resection with undernutrition and anemia; and requiring total parenteral nutrition (TPN)');
INSERT INTO ref.rating_criterion (criterion_id, code, position, percent, percent_minor, criteria_text) VALUES ('7328:01', '7328', 1, 60, NULL, 'Status post intestinal resection with undernutrition and anemia; and requiring prescribed oral dietary supplementation, continuous medication and intermittent total parenteral nutrition (TPN)');
INSERT INTO ref.rating_criterion (criterion_id, code, position, percent, percent_minor, criteria_text) VALUES ('7328:02', '7328', 2, 40, NULL, 'Status post intestinal resection with four or more episodes of diarrhea per day resulting in undernutrition and anemia; and requiring prescribed oral dietary supplementation and continuous medication');
INSERT INTO ref.rating_criterion (criterion_id, code, position, percent, percent_minor, criteria_text) VALUES ('7328:03', '7328', 3, 20, NULL, 'Status post intestinal resection with four or more episodes of diarrhea per day');
