INSERT INTO ref.rating_criterion (criterion_id, code, position, percent, percent_minor, criteria_text) VALUES ('7329:01', '7329', 1, 60, NULL, 'Total colectomy with or without permanent colostomy or ileostomy without high-output syndrome');
