INSERT INTO ref.rating_criterion (criterion_id, code, position, percent, percent_minor, criteria_text) VALUES ('7329:03', '7329', 3, 20, NULL, 'Partial colectomy with reanastomosis (reconnection of the intestinal tube) with loss of ileocecal valve and recurrent episodes of diarrhea more than 3 times per day');
