INSERT INTO ref.rating_criterion (criterion_id, code, position, percent, percent_minor, criteria_text) VALUES ('7330:00', '7330', 0, 100, NULL, 'Requiring total parenteral nutrition (TPN); or enteral nutritional support along with at least one of the following: (1) daily discharge equivalent to four or more ostomy bags (sized 130 cc), (2) requiring ten or more pad changes per day, or (3) a Body Mass Index (BMI) less than 16 and persistent drainage (any amount) for more than 1 month during the past 12 months');
INSERT INTO ref.rating_criterion (criterion_id, code, position, percent, percent_minor, criteria_text) VALUES ('7330:01', '7330', 1, 60, NULL, 'Requiring enteral nutritional support along with at least one of the following: (1) daily discharge equivalent to three or less ostomy bags (sized 130 cc), (2) requiring fewer than ten pad changes per day, or (3) a Body Mass Index (BMI) of 16 to 18 inclusive and persistent drainage (any amount) for more than 2 months in the past 12 months');
